INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('andy-austin/quipu/create-command', 'community', 'andy-austin', 'quipu', 'andy-austin/quipu', 'create-command', 0, 0, 60, '2026-03-02T10:42:30Z', '2026-03-07T04:06:33.727Z', '4447d39d33c7886f7e7b7785bcb973ba7919e50cad4fefa47fe9f437ff1af6d9', '{"id":"andy-austin/quipu/create-command","name":"create-command","description":{"en":"The create-command skill helps developers create custom Claude Code slash commands, ideal for frequently-used prompts. It enables the creation of reusable prompts stored as Markdown files.","zh":"创建命令技能帮助您创建自定义 Claude Code 刷命令，提高开发效率。通过创建可重用的 Markdown 提示，您可以使用 /command-name 语法触发","ja":"スラッシュコマンドを作成するスキルは、Claude Code のカスタムスラッシュコマンドを作成するのに役立ち、開発効率を向上させます。再利用可能な Markdown プロンプトを作成して、/command-name 構文でトリガーします","ko":"명령 만들기 기술은 Claude Code 사용자 정의 슬래시 명령을 생성하여 개발 효율성을 높이는 데 도움이 됩니다. 재사용 가능한 Markdown 프롬프트를 생성하여 /command-name 구문으로 트리거할 수 있습니다","es":"Create-command es una habilidad que permite crear comandos personalizados reutilizables como archivos Markdown. Ideal para prompts frecuentemente utilizados.","fr":"Create-command est une compétence qui permet de créer des commandes personnalisées réutilisables sous forme de fichiers Markdown. Idéal pour les invites fréquemment utilisées.","de":"Create-command ist eine Fähigkeit, die die Erstellung von benutzerdefinierten, wiederverwendbaren Befehlen als Markdown-Dateien ermöglicht. Ideal für häufig verwendete Prompts.","pt":"O Create Command permite criar prompts reutilizáveis e invocá-los com sintaxe /command-name. Aprenda a criar comandos personalizados para uso frequente","ru":"Create Command позволяет создавать многоразовые промпты и вызывать их с синтаксисом /command-name. Узнайте, как создать пользовательские команды для частого использования","ar":"Create Command يسمح بإنشاء دوافع قابلة لإعادة الاستخدام واستدعائها بناءً على بناء الجملة /command-name. تعلم كيفية إنشاء أوامر مخصصة للاستخدام المتكرر"},"seo":{"title":{"en":"create-command: Custom Slash Command Setup Guide | AI Age...","zh":"创建命令指南：自定义 Claude Code 刷命令","ja":"スラッシュコマンドを作成する：Claude Code のカスタムコマンド","ko":"명령 만들기 가이드: Claude Code 사용자 정의 슬래시 명령","es":"Guía de configuración de comandos personalizados con crea...","fr":"Guide de démarrage rapide pour les commandes Slash avec c...","de":"Einrichtungsanleitung für benutzerdefinierte Befehle mit ...","pt":"Guia de Configuração do Create Command","ru":"Настройка Команды Create: ИИ Агенты","ar":"دليل إنشاء أوامر Create Command"},"description":{"en":"Learn how to create reusable prompts with create-command. Discover how to invoke custom Claude Code slash commands with /command-name syntax and improve your...","zh":"了解如何创建自定义 Claude Code 刷命令，提高开发效率。使用该技能，创建可重用的 Markdown 提示，并使用 /command-name 语法触发","ja":"Claude Code のカスタムスラッシュコマンドを作成する方法を学び、開発効率を向上させましょう。このスキルを使用して、再利用可能な Markdown プロンプトを作成し、/command-name 構文でトリガーします","ko":"Claude Code 사용자 정의 슬래시 명령을 생성하여 개발 효율성을 높이는 방법에 대해 알아보세요. 이 기술을 사용하면 재사용 가능한 Markdown 프롬프트를 생성하고 /command-name 구문으로 트리거할 수 있습니다","es":"Aprende a crear comandos personalizados con create-command. Descubre cómo implementar comandos Slash reutilizables en tus proyectos.","fr":"Découvrez comment créer des commandes personnalisées avec create-command. Mettez en place des commandes Slash réutilisables dans vos projets.","de":"Erfahren Sie, wie Sie benutzerdefinierte Befehle mit create-command erstellen. Implementieren Sie wiederverwendbare Slash-Befehle in Ihren Projekten.","pt":"Aprenda a criar comandos personalizados com o Create Command. Descubra como criar prompts reutilizáveis e invocá-los com sintaxe /command-name","ru":"Узнайте, как создать пользовательские команды с помощью Create Command. Откройте для себя, как создавать многоразовые промпты и вызывать их с синтаксисом /co...","ar":"تعلم كيفية إنشاء أوامر مخصصة باستخدام Create Command. اكتشف كيفية إنشاء دوافع قابلة لإعادة الاستخدام واستدعائها بناءً على بناء الجملة /command-name"},"definition":{"en":"create-command is a skill that enables the creation of custom slash commands, allowing developers to store reusable prompts as Markdown files and invoke them with a specific syntax","zh":"创建命令是 Claude Code 中的一种技能，用于创建自定义的刷命令，允许开发者使用 /command-name 语法触发可重用的 Markdown 提示","ja":"スラッシュコマンドを作成するのは、Claude Code のスキルの一種で、カスタムスラッシュコマンドを作成し、/command-name 構文で再利用可能な Markdown プロンプトをトリガーすることを可能にします","ko":"명령 만들기는 Claude Code의 기술 중 하나로, 사용자 정의 슬래시 명령을 생성하여 /command-name 구문으로 재사용 가능한 Markdown 프롬프트를 트리거할 수 있습니다","es":"Create-command es una habilidad que permite crear comandos personalizados reutilizables","fr":"Create-command est une compétence qui permet de créer des commandes personnalisées réutilisables","de":"Create-command ist eine Fähigkeit, die die Erstellung von benutzerdefinierten, wiederverwendbaren Befehlen ermöglicht","pt":"O Create Command é uma habilidade que permite criar comandos personalizados reutilizáveis","ru":"Create Command - это способность, которая позволяет создавать пользовательские многоразовые команды","ar":"Create Command هو مهارة يسمح بإنشاء أوامر مخصصة قابلة لإعادة الاستخدام"},"features":{"en":["Creates custom Claude Code slash commands","Stores reusable prompts as Markdown files","Supports project-level and personal scope","Invokes commands with /command-name syntax","Enables explicit triggering of frequently-used prompts","Follows a workflow for identifying purpose and choosing scope"],"zh":["创建可重用的 Markdown 提示","使用 /command-name 语法触发","支持项目级和个人级命令","使用 .claude/commands/ 和 ~/.claude/command 目录存储命令"],"ja":["再利用可能な Markdown プロンプトを作成","/command-name 構文でトリガー","プロジェクトレベルと個人レベルのコマンドをサポート",".claude/commands/ と ~/.claude/command ディレクトリを使用してコマンドを保存"],"ko":["재사용 가능한 Markdown 프롬프트 생성","/command-name 구문으로 트리거","프로젝트 수준 및 개인 수준 명령 지원",".claude/commands/ 및 ~/.claude/command 디렉토리를 사용하여 명령 저장"],"es":["Creación de comandos personalizados como archivos Markdown","Implementación de comandos Slash reutilizables","Alcance de proyecto o personal para los comandos","Sintaxis de comando personalizable con /command-name","Almacenamiento de comandos en archivos Markdown"],"fr":["Création de commandes personnalisées sous forme de fichiers Markdown","Mise en place de commandes Slash réutilisables","Portée de projet ou personnelle pour les commandes","Syntaxe de commande personnalisable avec /command-name","Stockage de commandes dans des fichiers Markdown"],"de":["Erstellung von benutzerdefinierten Befehlen als Markdown-Dateien","Implementierung von wiederverwendbaren Slash-Befehlen","Projekt- oder personale Reichweite für Befehle","Befehlssyntax anpassbar mit /command-name","Speicherung von Befehlen in Markdown-Dateien"],"pt":["Criação de prompts reutilizáveis","Invocação de comandos com sintaxe /command-name","Definição de escopo de projeto ou pessoal","Armazenamento de comandos em arquivos Markdown"],"ru":["Создание многоразовых промптов","Вызов команд с синтаксисом /command-name","Определение области проекта или личного","Хранение команд в файлах Markdown"],"ar":["إنشاء دوافع قابلة لإعادة الاستخدام","استدعاء أوامر بناءً على بناء الجملة /command-name","تحديد نطاق المشروع أو الشخصي","تخزين الأوامر في ملفات Markdown"]},"keywords":{"en":["how to use create-command","create-command setup guide","what is create-command","create-command alternative","create-command vs Claude Code","create-command install","custom slash command creation","Markdown file storage","Claude Code integration"],"zh":["AI工具","Claude Code","创建命令","自定义刷命令","Markdown 提示","开发效率","命令创建","项目级命令","个人级命令"],"ja":["AIエージェント","Claude Code","スラッシュコマンド","カスタムコマンド","Markdown プロンプト","開発効率","コマンド作成","プロジェクトレベルコマンド","個人レベルコマンド"],"ko":["AI 에이전트","Claude Code","슬래시 명령","사용자 정의 명령","Markdown 프롬프트","개발 효율성","명령 생성","프로젝트 수준 명령","개인 수준 명령"],"es":["create-command","comandos personalizados","comandos Slash","Markdown","CLI","desarrollo de software","herramientas de desarrollo","agentes de IA","herramientas de automatización"],"fr":["create-command","commandes personnalisées","commandes Slash","Markdown","CLI","développement de logiciels","outils de développement","agents d''IA","outils d''automatisation"],"de":["create-command","benutzerdefinierte Befehle","Slash-Befehle","Markdown","CLI","Software-Entwicklung","Entwicklungstools","KI-Agenten","Automatisierungstools"],"pt":["Create Command","comandos personalizados","prompts reutilizáveis","sintaxe /command-name","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Create Command","пользовательские команды","многоразовые промпты","синтаксис /command-name","разработка программного обеспечения","инструменты разработки"],"ar":["Create Command","أوامر مخصصة","دوافع قابلة لإعادة الاستخدام","بناء الجملة /command-name","تطوير البرمجيات","أدوات التطوير"]}},"owner":"andy-austin","repo":"quipu","repoPath":"andy-austin/quipu","stars":0,"forks":0,"updatedAt":"2026-03-02T10:42:30Z","topics":[],"category":"community","skillMd":{"name":"create-command","description":"Guide for creating custom Claude Code slash commands with proper structure, argument handling, frontmatter configuration, and best practices. Use when the user wants to create slash commands, custom commands, reusable prompts, or mentions creating/designing/building commands.","bodyPreview":"# Create Slash Command Guide\n\nThis skill helps you create custom Claude Code slash commands - reusable prompts stored as Markdown files that can be invoked with `/command-name` syntax. Slash commands are ideal for frequently-used prompts that you want to trigger explicitly.\n\n## Quick Start\n\nWhen creating a new slash command, follow this workflow:\n\n1. **Identify the purpose** - What reusable prompt do you need?\n2. **Choose scope** - Project-level (.claude/commands/) or personal (~/.claude/command","body":"# Create Slash Command Guide\n\nThis skill helps you create custom Claude Code slash commands - reusable prompts stored as Markdown files that can be invoked with `/command-name` syntax. Slash commands are ideal for frequently-used prompts that you want to trigger explicitly.\n\n## Quick Start\n\nWhen creating a new slash command, follow this workflow:\n\n1. **Identify the purpose** - What reusable prompt do you need?\n2. **Choose scope** - Project-level (.claude/commands/) or personal (~/.claude/commands/)?\n3. **Select name** - Clear, descriptive filename without .md extension\n4. **Design arguments** - Will it use $ARGUMENTS, $1/$2/$3, or none?\n5. **Add frontmatter** - Optional metadata (description, tools, model)\n6. **Write prompt** - The markdown content that becomes the prompt\n7. **Test invocation** - Verify command works with various arguments\n\n## Basic Syntax\n\nCommands are invoked with:\n```\n/command-name [arguments]\n```\n\nThe command name comes from the filename without `.md` extension.\n\n## File Locations\n\n### Project Commands (.claude/commands/)\n- **Scope:** Project-specific, shared with team via git\n- **Label:** Shows as \"(project)\" in help listing\n- **Use for:** Team workflows, project conventions, shared prompts\n\n```bash\n# Create project command\necho \"Review this code for security vulnerabilities\" > .claude/commands/security-review.md\n```\n\n**Example structure:**\n```\n.claude/commands/\n├── review.md           # /review\n├── optimize.md         # /optimize\n├── test.md            # /test\n└── frontend/\n    └── component.md   # /component (project:frontend)\n```\n\n### Personal Commands (~/.claude/commands/)\n- **Scope:** Available across all projects\n- **Label:** Shows as \"(user)\" in help listing\n- **Use for:** Personal productivity, individual workflows, cross-project utilities\n\n```bash\n# Create personal command\necho \"Explain this code in simple terms\" > ~/.claude/commands/explain.md\n```\n\n**Example structure:**\n```\n~/.claude/commands/\n├── explain.md         # /explain (user)\n├── refactor.md        # /refactor (user)\n└── snippets/\n    └── doc.md         # /doc (user:snippets)\n```\n\n## Argument Handling\n\n### No Arguments\nSimple commands that don''t need input:\n\n```markdown\nReview the current codebase for potential improvements and suggest optimizations.\n```\n\nUsage: `/review`\n\n### All Arguments with $ARGUMENTS\nCaptures everything passed to the command:\n\n```markdown\nFix issue #$ARGUMENTS following our coding standards and best practices.\n```\n\nUsage:\n- `/fix-issue 123`\n- `/fix-issue 123 high-priority security`\n\n### Positional Arguments with $1, $2, $3, etc.\nAccess specific arguments by position:\n\n```markdown\nReview PR #$1 with priority $2 and assign to $3 for review.\n```\n\nUsage: `/review-pr 456 high alice`\n\n**Benefits:**\n- Access arguments in different parts of the prompt\n- Provide defaults for missing arguments\n- Build structured commands with specific parameter roles\n- Clearer intent for multi-parameter commands\n\n### Combining Arguments\nUse both positional and all arguments:\n\n```markdown\nCreate a $1 feature called \"$2\" with the following requirements:\n\n$ARGUMENTS\n```\n\nUsage: `/create-feature backend \"user authentication\" JWT tokens, role-based access, password hashing`\n\n## Frontmatter Configuration\n\nAdd optional metadata at the top of your command file:\n\n```markdown\n---\nallowed-tools: Read, Write, Edit, Bash\nargument-hint: <issue-number> [priority]\ndescription: Fix GitHub issue following coding standards\nmodel: claude-3-5-sonnet-20241022\n---\n\nYour command prompt content goes here...\n```\n\n### Frontmatter Fields\n\n**allowed-tools:** Restrict which tools Claude can use\n```yaml\nallowed-tools: Read, Write, Edit, Bash\nallowed-tools: Bash(git add:*), Bash(git status:*), Bash(git commit:*)\n```\n\n**argument-hint:** Show expected arguments in autocomplete\n```yaml\nargument-hint: <file-path>\nargument-hint: <pr-number> [priority] [assignee]\nargument-hint: [message]\n```\n\n**description:** Brief command description (overrides first line)\n```yaml\ndescription: Create a git commit with proper formatting\n```\n\n**model:** Specific model to use for this command\n```yaml\nmodel: claude-3-5-haiku-20241022      # Fast, cheap\nmodel: claude-3-5-sonnet-20241022     # Balanced\nmodel: claude-opus-4-20250514         # Advanced\n```\n\n**disable-model-invocation:** Prevent auto-invocation via SlashCommand tool\n```yaml\ndisable-model-invocation: true\n```\n\n## Advanced Features\n\n### File References with @\nInclude file contents in your command:\n\n```markdown\n---\ndescription: Review code implementation\n---\n\nReview the implementation in @src/utils/helpers.js and compare it with @src/utils/legacy.js.\n\nIdentify:\n- Code quality improvements\n- Performance optimizations\n- Security vulnerabilities\n```\n\nUsage: `/review-implementation`\n\n### Bash Command Execution with !\nExecute bash commands and include output (requires allowed-tools):\n\n```markdown\n---\nallowed-tools: Bash(git add:*), Bash(git status:*), Bash(git commit:*)\ndescription: Create a git commit\n---\n\nCreate a git commit with the following context:\n\n**Current Status:**\n!`git status`\n\n**Recent Changes:**\n!`git diff HEAD`\n\n**Commit Message:** $ARGUMENTS\n```\n\nUsage: `/commit \"Add user authentication feature\"`\n\n### Extended Thinking\nTrigger extended reasoning by including keywords in the command content:\n\n```markdown\n---\ndescription: Analyze complex architectural decisions\n---\n\nPlease use extended thinking to analyze the following architectural decision:\n\n$ARGUMENTS\n\nConsider:\n- Scalability implications\n- Maintenance overhead\n- Team expertise requirements\n- Long-term technical debt\n```\n\n### Namespacing with Subdirectories\nOrganize commands in subdirectories (affects description, not command name):\n\n```\n.claude/commands/\n├── git/\n│   ├── commit.md     # /commit (project:git)\n│   └── review.md     # /review (project:git)\n└── frontend/\n    └── component.md  # /component (project:frontend)\n```\n\nThe subdirectory appears in the description but doesn''t change the command invocation.\n\n## Complete Examples\n\n### 1. Simple Code Review Command\n\n**File:** `.claude/commands/review.md`\n\n```markdown\n---\ndescription: Comprehensive code review for quality and security\n---\n\nReview this code for:\n- Code quality and maintainability\n- Security vulnerabilities\n- Performance optimizations\n- Best practices adherence\n- Potential bugs or edge cases\n\nProvide specific, actionable feedback with code examples.\n```\n\nUsage: `/review`\n\n### 2. Issue Fix Command with Arguments\n\n**File:** `.claude/commands/fix-issue.md`\n\n```markdown\n---\nargument-hint: <issue-number> [priority]\ndescription: Fix GitHub issue following coding standards\n---\n\nFix issue #$1 following our coding standards.\n\nPriority: $2\n\nSteps:\n1. Read the issue details from GitHub\n2. Analyze the problem and root cause\n3. Implement the fix with tests\n4. Update documentation if needed\n5. Create a commit with proper message format\n```\n\nUsage:\n- `/fix-issue 123 high`\n- `/fix-issue 456`\n\n### 3. PR Creation with Template\n\n**File:** `.claude/commands/create-pr.md`\n\n```markdown\n---\nallowed-tools: Bash(git *), Read, Write\nargument-hint: <title> [description]\ndescription: Create GitHub pull request with template\nmodel: claude-3-5-sonnet-20241022\n---\n\nCreate a GitHub pull request with the following details:\n\n**Title:** $1\n\n**Description:** $2\n\n**Context:**\n\n**Current Branch:**\n!`git branch --show-current`\n\n**Changes:**\n!`git diff main...HEAD --stat`\n\n**Commits:**\n!`git log main..HEAD --oneline`\n\nGenerate a comprehensive PR description following our template at @.github/pull_request_template.md\n```\n\nUsage: `/create-pr \"Add user authentication\" \"Implements JWT-based authentication system\"`\n\n### 4. Test Runner Command\n\n**File:** `.claude/commands/test.md`\n\n```markdown\n---\nallowed-tools: Bash, Read, Grep\nargument-hint: [file-pattern]\ndescription: Run tests and analyze failures\nmodel: claude-3-5-haiku-20241022\n---\n\nRun tests matching pattern: $ARGUMENTS\n\nSteps:\n1. Execute test suite\n2. Analyze any failures\n3. Suggest fixes for failing tests\n4. Validate fixes and re-run\n\nProvide clear, actionable feedback on test failures.\n```\n\nUsage:\n- `/test`\n- `/test auth`\n- `/test src/components/Button.test.ts`\n\n### 5. Documentation Generator\n\n**File:** `.claude/commands/document.md`\n\n```markdown\n---\nallowed-tools: Read, Write, Grep, Glob\ndescription: Generate comprehensive documentation\n---\n\nGenerate comprehensive documentation for: $ARGUMENTS\n\nInclude:\n- Overview and purpose\n- API reference\n- Usage examples\n- Configuration options\n- Best practices\n- Common pitfalls\n\nFormat output in clear, professional markdown.\n```\n\nUsage: `/document src/utils/api-client.ts`\n\n### 6. Code Optimization Command\n\n**File:** `.claude/commands/optimize.md`\n\n```markdown\n---\ndescription: Analyze and optimize code performance\n---\n\nAnalyze this code for performance optimizations:\n\n$ARGUMENTS\n\nFocus on:\n- Algorithm complexity (O(n) analysis)\n- Memory usage and allocations\n- Database query efficiency\n- Caching opportunities\n- Parallel processing potential\n- Resource cleanup and lifecycle management\n\nProvide specific refactoring suggestions with before/after examples.\n```\n\nUsage: `/optimize`\n\n### 7. Multi-Argument PR Review\n\n**File:** `.claude/commands/review-pr.md`\n\n```markdown\n---\nallowed-tools: Bash(gh *), Read\nargument-hint: <pr-number> <priority> [assignee]\ndescription: Review pull request with priority and assignment\n---\n\nReview PR #$1 with priority: $2\n\n**PR Details:**\n!`gh pr view $1`\n\n**Changes:**\n!`gh pr diff $1`\n\nReview focus areas based on priority $2:\n- high: Security, breaking changes, data integrity\n- medium: Code quality, tests, documentation\n- low: Style, minor improvements\n\nAssign to: $3 (if provided)\n\nProvide comprehensive feedback organized by:\n1. Critical issues (blocking)\n2. Important suggestions\n3. Minor improvements\n4. Positive observations\n```\n\nUsage: `/review-pr 123 high alice`\n\n### 8. Git Workflow Command\n\n**File:** `.claude/commands/git-flow.md`\n\n```markdown\n---\nallowed-tools: Bash(git *)\nargument-hint: <action> <branch-name>\ndescription: Execute git workflow actions\n---\n\nExecute git workflow action: $1\n\nBranch: $2\n\n**Current Status:**\n!`git status`\n\n**Available Branches:**\n!`git branch -a`\n\nActions:\n- start: Create and checkout new branch\n- finish: Merge branch and delete\n- sync: Pull latest and rebase\n- review: Show branch diff\n\nAdditional context: $ARGUMENTS\n```\n\nUsage:\n- `/git-flow start feature/auth`\n- `/git-flow finish bugfix/login`\n- `/git-flow sync`\n\n### 9. Database Query Optimization\n\n**File:** `~/.claude/commands/optimize-query.md`\n\n```markdown\n---\ndescription: Optimize database queries for performance\n---\n\nAnalyze and optimize this database query:\n\n$ARGUMENTS\n\nOptimization checklist:\n- [ ] Execution plan analysis\n- [ ] Index usage and recommendations\n- [ ] Query rewrite opportunities\n- [ ] JOIN optimization\n- [ ] Subquery vs JOIN performance\n- [ ] Parameter binding and caching\n- [ ] Result set size and pagination\n\nProvide:\n1. Performance analysis\n2. Optimized query\n3. Index recommendations\n4. Before/after execution plan comparison\n```\n\nUsage: `/optimize-query`\n\n### 10. Complex Issue Creation\n\n**File:** `.claude/commands/create-issue.md`\n\n```markdown\n---\nallowed-tools: Bash(gh *), Read\nargument-hint: <title> <type>\ndescription: Create detailed GitHub issue with template\nmodel: claude-3-5-sonnet-20241022\n---\n\nCreate a GitHub issue with:\n\n**Title:** $1\n**Type:** $2 (feature/bug/enhancement/docs)\n\n**Repository Analysis:**\n!`gh repo view --json name,description,url`\n\n**Template:**\n@.github/ISSUE_TEMPLATE/$2.md\n\nGenerate a comprehensive issue following our template structure with:\n- Clear problem statement\n- Proposed solution\n- Acceptance criteria\n- Implementation notes\n- Related issues/PRs\n\nAdditional context: $ARGUMENTS\n```\n\nUsage: `/create-issue \"Add dark mode support\" feature \"Users want theme customization\"`\n\n## Slash Commands vs Skills\n\n### When to Use Slash Commands\n\n**Characteristics:**\n- Explicit invocation required (`/command`)\n- Quick, frequently-used prompts\n- Simple prompt snippets\n- Single-file capabilities\n- Manual control over execution\n\n**Best for:**\n- Code review workflows (`/review`)\n- Quick explanations (`/explain`)\n- Frequent operations (`/optimize`, `/test`)\n- Personal productivity shortcuts\n- Team-standardized prompts\n\n### When to Use Skills\n\n**Characteristics:**\n- Automatic discovery based on context\n- Claude decides when to invoke\n- Complex workflows with multiple steps\n- Multiple files (scripts, templates, docs)\n- Advanced capabilities\n\n**Best for:**\n- PDF processing (auto-invoked when user mentions PDFs)\n- API documentation generation (auto-invoked for API tasks)\n- Complex multi-step workflows\n- Capabilities requiring external scripts\n- Knowledge organized across multiple files\n\n### Can They Coexist?\n\n**Yes!** Use both approaches:\n- **Commands:** Explicit, manual shortcuts (`/review-pr`)\n- **Skills:** Automatic, context-driven capabilities (PDF extraction)\n\n## Best Practices Checklist\n\nWhen creating a slash command:\n\n- [ ] Filename is descriptive and uses kebab-case\n- [ ] File location matches scope (project vs personal)\n- [ ] Description frontmatter is clear and concise\n- [ ] Arguments are well-documented with argument-hint\n- [ ] Prompt content is specific and actionable\n- [ ] File references (@) use correct paths\n- [ ] Bash commands (!) have proper tool restrictions\n- [ ] Model selection matches complexity (haiku/sonnet/opus)\n- [ ] Command tested with various argument combinations\n- [ ] Related commands organized in subdirectories\n- [ ] No sensitive data (credentials, API keys) in commands\n- [ ] Clear examples in comments or description\n\n## Testing Slash Commands\n\n### 1. Verify Command Appears\n\nList all available commands:\n```bash\n# In Claude Code\n/help\n```\n\nLook for your command in the output.\n\n### 2. Test Basic Invocation\n\n```bash\n/your-command\n```\n\nVerify the prompt expands correctly.\n\n### 3. Test with Arguments\n\n```bash\n/your-command arg1\n/your-command arg1 arg2 arg3\n```\n\nVerify argument substitution works.\n\n### 4. Test File References\n\nIf using `@file.txt`, verify the file exists and is readable.\n\n### 5. Test Bash Commands\n\nIf using `!command`, verify:\n- Command executes successfully\n- Output is captured correctly\n- Tool restrictions are appropriate\n\n## Common Issues\n\n**Command not appearing:**\n- Check filename has `.md` extension\n- Verify file is in correct location (.claude/commands/ or ~/.claude/commands/)\n- Restart Claude Code to reload commands\n\n**Arguments not substituting:**\n- Ensure `$ARGUMENTS`, `$1`, `$2` syntax is correct\n- Check for extra spaces or special characters\n- Verify arguments are passed when invoking\n\n**File references not working:**\n- Confirm file path is correct (relative to project root)\n- Check file exists and is readable\n- Verify `@` prefix is present\n\n**Bash commands failing:**\n- Add `allowed-tools: Bash` to frontmatter\n- Verify command works independently\n- Check tool restriction patterns (e.g., `Bash(git *)`)\n\n**Description not showing:**\n- Add `description` field in frontmatter\n- Ensure frontmatter YAML is valid (opening/closing `---`)\n\n## Organization Strategies\n\n### By Feature Area\n\n```\n.claude/commands/\n├── git/\n│   ├── commit.md\n│   ├── review.md\n│   └── workflow.md\n├── testing/\n│   ├── run.md\n│   ├── coverage.md\n│   └── debug.md\n└── docs/\n    ├── generate.md\n    └── update.md\n```\n\n### By Complexity\n\n```\n~/.claude/commands/\n├── quick/         # Simple, haiku-model commands\n│   ├── explain.md\n│   └── format.md\n├── standard/      # Regular sonnet commands\n│   ├── review.md\n│   └── optimize.md\n└── complex/       # Advanced opus commands\n    └── architect.md\n```\n\n### By Team Role\n\n```\n.claude/commands/\n├── frontend/\n│   ├── component.md\n│   └── style.md\n├── backend/\n│   ├── api.md\n│   └── database.md\n└── devops/\n    ├── deploy.md\n    └── monitor.md\n```\n\n## Migration from Skills\n\nConverting a skill to a slash command:\n\n**Skill (automatic invocation):**\n```markdown\n---\nname: code-explainer\ndescription: Explain code in simple terms when user asks\n---\n\n# Code Explainer\nInstructions for explaining code...\n```\n\n**Slash Command (explicit invocation):**\n```markdown\n---\ndescription: Explain code in simple terms\n---\n\nExplain this code in simple, beginner-friendly terms:\n\n$ARGUMENTS\n\nInclude:\n- What the code does\n- How it works\n- Why it''s structured this way\n- Common use cases\n```\n\nUsage: `/explain`\n\n## Security Considerations\n\n**Avoid:**\n- Hardcoding credentials or API keys\n- Network calls without encryption\n- Destructive commands without confirmation\n- Accessing sensitive files unnecessarily\n\n**Safe practices:**\n- Use environment variables for secrets\n- Validate file paths before access\n- Restrict bash command patterns\n- Log command execution for audit trails\n\n## Advanced Patterns\n\n### Template-Based Commands\n\n```markdown\n---\ndescription: Create component from template\n---\n\nCreate a new $1 component named $2:\n\n**Template:**\n@templates/$1-template.tsx\n\n**Destination:**\nsrc/components/$2/\n\nGenerate files:\n1. Component implementation\n2. Test file\n3. Styles\n4. Documentation\n5. Storybook story\n```\n\nUsage: `/create-component button UserProfileButton`\n\n### Multi-Step Workflows\n\n```markdown\n---\nallowed-tools: Bash, Read, Write, Edit\ndescription: Complete feature implementation workflow\n---\n\nImplement feature: $ARGUMENTS\n\nWorkflow:\n1. Create feature branch\n2. Generate boilerplate code\n3. Implement core logic\n4. Add tests\n5. Update documentation\n6. Run quality checks\n7. Create PR\n\nExecute each step with confirmation.\n```\n\nUsage: `/feature-workflow \"user authentication\"`\n\n### Context-Rich Commands\n\n```markdown\n---\nallowed-tools: Bash(git *), Read\ndescription: Comprehensive code review with full context\n---\n\nReview code with full context:\n\n**Project Structure:**\n!`find . -type f -name \"*.ts\" -o -name \"*.tsx\" | head -20`\n\n**Recent Changes:**\n!`git log --oneline -10`\n\n**Modified Files:**\n!`git diff --name-only HEAD~5..HEAD`\n\n**Code to Review:**\n$ARGUMENTS\n\nProvide comprehensive feedback considering project context.\n```\n\n## Key Principles\n\n1. **Descriptive names** - Clear, action-oriented command names\n2. **Explicit invocation** - Users trigger commands intentionally\n3. **Argument clarity** - Use argument-hint for discoverability\n4. **Scope appropriately** - Project commands for team, personal for you\n5. **Tool restrictions** - Only grant necessary tool access\n6. **Model selection** - Match model to task complexity\n7. **Organization** - Use subdirectories for related commands\n8. **Documentation** - Clear descriptions and argument hints\n9. **Testing** - Verify with various inputs before sharing\n10. **Security** - Never hardcode sensitive data\n\n## Workflow Summary\n\nWhen user asks to create a slash command:\n\n1. **Clarify purpose** - What prompt should be reusable?\n2. **Choose scope** - Project or personal command?\n3. **Design arguments** - $ARGUMENTS, $1/$2/$3, or none?\n4. **Select name** - Descriptive, kebab-case filename\n5. **Add frontmatter** - Description, tools, model, argument-hint\n6. **Write prompt** - Clear, actionable command content\n7. **Add features** - File references (@), bash commands (!)\n8. **Test thoroughly** - Various arguments, edge cases\n9. **Document usage** - Examples in comments or description\n10. **Share if needed** - Commit project commands to git\n\nRemember: Slash commands are for explicit, manual invocation of frequently-used prompts. Use skills for automatic, context-driven capabilities.\n"},"lastSynced":"2026-03-07T04:06:33.727Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude Code needing custom slash command creation for reusable prompts.","zh":"适合需要自定义斜杠命令创建可重用提示的 AI 代理，如 Claude Code。","ja":"Claude Code などのカスタムスラッシュコマンドの作成が必要な AI エージェントに最適です。","ko":"재사용 가능한 프롬프트를 위한 사용자 정의 슬래시 명령을 필요로 하는 Claude Code와 같은 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA como Claude Code que necesitan la creación de comandos personalizados de barra diagonal para prompts reutilizables.","fr":"Parfait pour les agents IA comme Claude Code nécessitant la création de commandes de barre oblique personnalisées pour des invites réutilisables.","de":"Perfekt für KI-Agents wie Claude Code, die eine benutzerdefinierte Slash-Befehlserstellung für wiederverwendbare Prompts benötigen.","pt":"Perfeito para Agentes de IA como Claude Code que precisam de criação de comandos personalizados para prompts reutilizáveis.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code, требующих создания пользовательских команд для многоразовых подсказок.","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Claude Code الذين بحاجة إلى إنشاء أوامر مخصصة للتحفيز القابل لإعادة الاستخدام."},"recommendation":{"en":"Empowers agents to create custom Claude Code slash commands, utilizing Markdown files for storing frequently-used prompts, and invoking them with a `/command-name` syntax, streamlining workflow efficiency with project-level or personal command scopes.","zh":"赋予代理创建自定义 Claude Code 斜杠命令的能力，利用 Markdown 文件存储常用的提示，并使用 `/命令名称` 语法调用它们，从而通过项目级或个人命令范围提高工作流效率。","ja":"Claude Code のカスタムスラッシュコマンドを作成するエージェントの能力を提供し、Markdown ファイルを使用して頻繁に使用されるプロンプトを保存し、`/コマンド名` 構文で呼び出すことで、プロジェクトレベルまたは個人コマンドの範囲でワークフローの効率を向上させます。","ko":"에이전트가 Claude Code의 사용자 정의 슬래시 명령을 만들 수 있는 능력을 제공하며, 자주 사용되는 프롬프트를 저장하기 위해 Markdown 파일을 사용하고, `/명령 이름` 구문을 사용하여 호출하여, 프로젝트 수준 또는 개인 명령 범위에서 워크플로우 효율성을 개선합니다.","es":"Habilita a los agentes a crear comandos de barra diagonal personalizados de Claude Code, utilizando archivos Markdown para almacenar prompts frecuentemente utilizados e invocarlos con una sintaxis `/nombre-de-comando`, mejorando la eficiencia del flujo de trabajo con ámbitos de proyecto o comandos personales.","fr":"Permet aux agents de créer des commandes de barre oblique personnalisées de Claude Code, en utilisant des fichiers Markdown pour stocker des invites fréquemment utilisées et en les invoquant avec une syntaxe `/nom-de-comande`, améliorant l''efficacité du flux de travail avec des étendues de projet ou des commandes personnelles.","de":"Ermächtigt Agents, benutzerdefinierte Claude Code-Slash-Befehle zu erstellen, indem Markdown-Dateien für die Speicherung häufig verwendeter Prompts verwendet werden und diese mit einer `/befehlsname`-Syntax aufgerufen werden, wodurch die Workflow-Effizienz mit Projekt- oder persönlichen Befehlsumfängen gestreamt wird.","pt":"Habilita os agentes a criar comandos personalizados Claude Code, utilizando arquivos Markdown para armazenar prompts frequentemente usados e invocá-los com uma sintaxe `/nome-do-comando`, otimizando a eficiência do fluxo de trabalho com escopos de comando de nível de projeto ou pessoal.","ru":"Наделяет агентов возможностью создавать пользовательские команды Claude Code, используя файлы Markdown для хранения часто используемых подсказок и вызова их с помощью синтаксиса `/имя-команды`, оптимизируя эффективность рабочего процесса с помощью областей команд проекта или личного уровня.","ar":"يمنح الوكلاء khảية إنشاء أوامر مخصصة Claude Code، باستخدام ملفات Markdown لحفظ التحفيزات المستخدمة بشكل متكرر واستدعائها بناءً على بناء الجملة `/اسم-الأمر`، مما يزيد من كفاءة تدفق العمل مع نطاقات الأوامر على مستوى المشروع أو الشخصي."},"useCases":{"en":["Creating reusable prompts for frequent tasks","Organizing project-level commands in .claude/commands/","Invoking personal commands from ~/.claude/command"],"zh":["为频繁任务创建可重用的提示","在 .claude/commands/ 中组织项目级命令","从 ~/.claude/command 调用个人命令"],"ja":["頻繁に使用されるタスクの再利用可能なプロンプトの作成",".claude/commands/ にプロジェクトレベルのコマンドを整理する","~/.claude/command から個人コマンドを呼び出す"],"ko":["빈번한 작업을 위한 재사용 가능한 프롬프트 만들기",".claude/commands/에 프로젝트 수준의 명령어를 구성하기","~/.claude/command에서 개인 명령어 호출하기"],"es":["Crear prompts reutilizables para tareas frecuentes","Organizar comandos a nivel de proyecto en .claude/commands/","Invocar comandos personales desde ~/.claude/command"],"fr":["Créer des invites réutilisables pour des tâches fréquentes","Organiser des commandes au niveau du projet dans .claude/commands/","Appeler des commandes personnelles depuis ~/.claude/command"],"de":["Erstellen von wiederverwendbaren Prompts für häufige Aufgaben","Organisieren von Projektkommandos in .claude/commands/","Aufrufen von persönlichen Kommandos von ~/.claude/command"],"pt":["Criar prompts reutilizáveis para tarefas frequentes","Organizar comandos de nível de projeto em .claude/commands/","Invocar comandos pessoais de ~/.claude/command"],"ru":["Создание многоразовых подсказок для частых задач","Организация команд проекта в .claude/commands/","Вызов личных команд из ~/.claude/command"],"ar":["إنشاء تحفيزات قابلة لإعادة الاستخدام للمهام المتكررة","تنظيم أوامر مستوى المشروع في .claude/commands/","استدعاء أوامر شخصية من ~/.claude/command"]},"limitations":{"en":["Requires Claude Code environment","Limited to Markdown file format for command storage"],"zh":["需要 Claude Code 环境","命令存储仅限 Markdown 文件格式"],"ja":["Claude Code 環境が必要","コマンドの保存は Markdown ファイル形式のみ"],"ko":["Claude Code 환경이 필요","명령어 저장은 Markdown 파일 형식만 허용"],"es":["Requiere entorno de Claude Code","Limitado al formato de archivo Markdown para el almacenamiento de comandos"],"fr":["Nécessite un environnement Claude Code","Limité au format de fichier Markdown pour le stockage des commandes"],"de":["Benötigt eine Claude Code-Umgebung","Begrenzt auf Markdown-Dateiformat für die Befehlsspeicherung"],"pt":["Requer ambiente Claude Code","Limitado ao formato de arquivo Markdown para armazenamento de comandos"],"ru":["Требуется среда Claude Code","Ограничен форматом файла Markdown для хранения команд"],"ar":["يتطلب بيئة Claude Code","محدود بتنسيق ملف Markdown لتخزين الأوامر"]},"version":4},"contentHash":"4447d39d33c7886f7e7b7785bcb973ba7919e50cad4fefa47fe9f437ff1af6d9","qualityScore":60}');
