INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('andy-austin/quipu/create-command', 'create-command', 'andy-austin', 'quipu', 'community', 'create-command andy-austin quipu community The create-command skill helps developers create custom Claude Code slash commands, ideal for frequently-used prompts. It enables the creation of reusable prompts stored as Markdown files. 创建命令技能帮助您创建自定义 Claude Code 刷命令，提高开发效率。通过创建可重用的 Markdown 提示，您可以使用 /command-name 语法触发 スラッシュコマンドを作成するスキルは、Claude Code のカスタムスラッシュコマンドを作成するのに役立ち、開発効率を向上させます。再利用可能な Markdown プロンプトを作成して、/command-name 構文でトリガーします 명령 만들기 기술은 Claude Code 사용자 정의 슬래시 명령을 생성하여 개발 효율성을 높이는 데 도움이 됩니다. 재사용 가능한 Markdown 프롬프트를 생성하여 /command-name 구문으로 트리거할 수 있습니다 Create-command es una habilidad que permite crear comandos personalizados reutilizables como archivos Markdown. Ideal para prompts frecuentemente utilizados. Create-command est une compétence qui permet de créer des commandes personnalisées réutilisables sous forme de fichiers Markdown. Idéal pour les invites fréquemment utilisées. Create-command ist eine Fähigkeit, die die Erstellung von benutzerdefinierten, wiederverwendbaren Befehlen als Markdown-Dateien ermöglicht. Ideal für häufig verwendete Prompts. O Create Command permite criar prompts reutilizáveis e invocá-los com sintaxe /command-name. Aprenda a criar comandos personalizados para uso frequente Create Command позволяет создавать многоразовые промпты и вызывать их с синтаксисом /command-name. Узнайте, как создать пользовательские команды для частого использования Create Command يسمح بإنشاء دوافع قابلة لإعادة الاستخدام واستدعائها بناءً على بناء الجملة /command-name. تعلم كيفية إنشاء أوامر مخصصة للاستخدام المتكرر how to use create-command create-command setup guide what is create-command create-command alternative create-command vs Claude Code create-command install custom slash command creation Markdown file storage Claude Code integration AI工具 Claude Code 创建命令 自定义刷命令 Markdown 提示 开发效率 命令创建 项目级命令 个人级命令 Creates custom Claude Code slash commands Stores reusable prompts as Markdown files Supports project-level and personal scope Invokes commands with /command-name syntax Enables explicit triggering of frequently-used prompts Follows a workflow for identifying purpose and choosing scope create-command is a skill that enables the creation of custom slash commands, allowing developers to store reusable prompts as Markdown files and invoke them with a specific syntax');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brunoreinstein-cloud/chat-assitjur/prompt-engineering-patterns', 'community', 'brunoreinstein-cloud', 'chat-assitjur', 'brunoreinstein-cloud/chat-assitjur', 'prompt-engineering-patterns', 0, 0, 60, '2026-03-02T20:44:15Z', '2026-03-07T13:09:54.001Z', '747cb530259ee0d6f77d9b57fd649ec49c292f7a9808939f5a64cd0aa7d8f4c6', '{"id":"brunoreinstein-cloud/chat-assitjur/prompt-engineering-patterns","name":"prompt-engineering-patterns","description":{"en":"The prompt-engineering-patterns skill helps developers maximize LLM performance, reliability, and controllability by mastering advanced prompt engineering techniques. This skill benefits developers designing complex prompts for production LLM applications.","zh":"Prompt 工程模式是一种用于设计复杂提示的技术，能够最大化 LLM 应用的性能、可靠性和可控性","ja":"プロンプトエンジニアリングパターンは、LLM アプリケーションのパフォーマンス、信頼性、制御性を最大化するための複雑なプロンプトを設計する技術","ko":"프롬프트 엔지니어링 패턴은 LLM 애플리케이션의 성능, 신뢰성, 제어성을 최대화하는 복잡한 프롬프트를 설계하는 기술","es":"Los patrones de ingeniería de prompt permiten diseñar complejos prompts para aplicaciones LLM de producción y optimizar su rendimiento","fr":"Les modèles d''ingénierie de prompt permettent de concevoir des prompts complexes pour les applications LLM de production et d''optimiser leurs performances","de":"Die Muster der Prompt-Engineering ermöglichen es, komplexe Prompts für LLM-Produktionsanwendungen zu entwerfen und deren Leistung zu optimieren","pt":"Engenharia de prompt avançada para melhorar o desempenho do LLM. Técnicas para otimizar a performance e a consistência.","ru":"Продвинутая инженерия запросов для улучшения производительности ИИ Агентов. Техники для оптимизации производительности и согласованности.","ar":"هندسة استدعاء متقدمة لتحسين أداء الوكلاء الذكية. تقنيات لتحسين الأداء والموثوقية."},"seo":{"title":{"en":"Prompt-Engineering-Patterns: Mastering LLM Performance | ...","zh":"Prompt 工程模式设置指南","ja":"プロンプトエンジニアリングパターンのベストプラクティス","ko":"프롬프트 엔지니어링 패턴 구현 가이드","es":"Guía de Configuración de Patrones de Ingeniería de Prompt","fr":"Guide de Mise en Place des Modèles d''Ingénierie de Prompt","de":"Einrichtungsleitfaden für Prompt-Engineering-Muster","pt":"Padrões de Engenharia de Prompt: Guia de Configuração par...","ru":"Шаблоны инженерии запросов: Настройка производительности ...","ar":"نماذج هندسة الاستدعاء: دليل الإعداد لتحسين أداء الوكلاء ا..."},"description":{"en":"Unlock advanced prompt engineering techniques for reliable LLM applications. Learn how to design complex prompts, optimize performance, and implement structu...","zh":"了解 Prompt 工程模式的技术细节，优化 LLM 应用的性能和可靠性，实现结构化推理和少样本学习","ja":"プロンプトエンジニアリングパターンを使用して LLM アプリケーションのパフォーマンスと信頼性を最適化し、構造化推論と少数-shot 学習を実現","ko":"프롬프트 엔지니어링 패턴의 기술 세부 사항을 이해하고 LLM 애플리케이션의 성능과 신뢰성을 최적화하여 구조화된 추론과 少샘플 학습을 구현","es":"Aprenda a maximizar el rendimiento de los LLM con técnicas de ingeniería de prompt avanzadas y patrones de razonamiento estructurados","fr":"Découvrez comment optimiser les performances des LLM avec des techniques d''ingénierie de prompt avancées et des modèles de raisonnement structurés","de":"Erfahren Sie, wie Sie die Leistung von LLM mit fortschrittlichen Prompt-Engineering-Techniken und strukturierten Denkmustern maximieren","pt":"Aprenda a maximizar o desempenho do LLM com padrões de engenharia de prompt. Descubra técnicas avançadas para melhorar a confiabilidade e o controle.","ru":"Узнайте, как максимизировать производительность ИИ Агентов с помощью шаблонов инженерии запросов. Откройте для себя продвинутые техники для улучшения надежно...","ar":"تعلم كيفية تحسين أداء الوكلاء الذكية باستخدام نماذج هندسة الاستدعاء. اكتشف تقنيات متقدمة لتحسين الموثوقية والسيطرة."},"definition":{"en":"prompt-engineering-patterns is a set of techniques for designing and optimizing prompts to maximize the performance, reliability, and controllability of Large Language Models (LLMs)","zh":"Prompt 工程模式是一种用于优化 LLM 应用的技术，涉及结构化推理、少样本学习和动态示例选择","ja":"プロンプトエンジニアリングパターンは、LLM アプリケーションを最適化する技術で、構造化推論、少数-shot 学習、動的例選択を含む","ko":"프롬프트 엔지니어링 패턴은 LLM 애플리케이션을 최적화하는 기술로, 구조화된 추론, 少샘플 학습, 동적 예시 선택을 포함","es":"Patrones de ingeniería de prompt: técnicas para maximizar el rendimiento de los LLM","fr":"Modèles d''ingénierie de prompt: techniques pour optimiser les performances des LLM","de":"Prompt-Engineering-Muster: Techniken zur Maximierung der LLM-Leistung","pt":"Padrões de engenharia de prompt são técnicas avançadas para maximizar o desempenho do LLM.","ru":"Шаблоны инженерии запросов - это продвинутые техники для максимизации производительности ИИ Агентов.","ar":"نماذج هندسة الاستدعاء هي تقنيات متقدمة لتحسين أداء الوكلاء الذكية."},"features":{"en":["Designs complex prompts for production LLM applications","Optimizes prompt performance and consistency","Implements structured reasoning patterns such as chain-of-thought and tree-of-thought","Builds few-shot learning systems with dynamic example selection","Creates reusable prompt templates with variable interpolation","Debugs prompt-related issues for reliable LLM performance"],"zh":["设计复杂提示","优化提示性能和一致性","实现结构化推理（链式思维、树式思维）","构建少样本学习系统","创建可重用提示模板"],"ja":["複雑なプロンプトを設計","プロンプトのパフォーマンスと一貫性を最適化","構造化推論（チェーン・オブ・ソート、ツリー・オブ・ソート）を実現","少数-shot 学習システムを構築","再利用可能なプロンプトテンプレートを作成"],"ko":["복잡한 프롬프트 설계","프롬프트 성능과 일관성을 최적화","구조화된 추론（체인 오브 소트, 트리 오브 소트）구현","少샘플 학습 시스템 구축","재사용 가능한 프롬프트 템플릿 생성"],"es":["Diseño de prompts complejos para aplicaciones LLM de producción","Optimización del rendimiento de los prompts","Implementación de patrones de razonamiento estructurados (cadena de pensamiento, árbol de pensamiento)","Creación de sistemas de aprendizaje con pocos ejemplos y selección dinámica de ejemplos","Creación de plantillas de prompts reutilizables con interpolación de variables"],"fr":["Conception de prompts complexes pour les applications LLM de production","Optimisation des performances des prompts","Implémentation de modèles de raisonnement structurés (chaîne de pensée, arbre de pensée)","Création de systèmes d''apprentissage avec peu d''exemples et sélection dynamique d''exemples","Création de modèles de prompts réutilisables avec interpolation de variables"],"de":["Entwurf komplexer Prompts für LLM-Produktionsanwendungen","Optimierung der Prompt-Leistung","Implementierung strukturierter Denkmuster (Gedankenketten, Gedankenbaum)","Erstellung von Few-Shot-Lernsystemen mit dynamischer Beispielwahl","Erstellung wiederverwendbarer Prompt-Vorlagen mit Variableninterpolation"],"pt":["Design de prompts complexos para aplicações de produção do LLM","Otimização do desempenho e consistência dos prompts","Implementação de padrões de raciocínio estruturados","Criação de modelos de prompts reutilizáveis com interpolação de variáveis","Depuração de prompts para melhorar a confiabilidade"],"ru":["Проектирование сложных запросов для производственных приложений ИИ Агентов","Оптимизация производительности и согласованности запросов","Реализация структурированных шаблонов рассуждений","Создание повторно используемых шаблонов запросов с интерполяцией переменных","Отладка запросов для улучшения надежности"],"ar":["تصميم استدعاءات معقدة لتحسين أداء الوكلاء الذكية","تحسين الأداء والموثوقية للاستدعاءات","تنفيذ أنماط استدلالية متعددة","إنشاء نماذج استدعاء قابلة لإعادة الاستخدام مع استبدال المتغيرات","تصحيح الأخطاء في الاستدعاءات لتحسين الموثوقية"]},"keywords":{"en":["how to use prompt-engineering-patterns","prompt-engineering-patterns setup guide","LLM performance optimization","prompt engineering techniques","what is prompt-engineering-patterns","prompt-engineering-patterns alternative","implementing chain-of-thought patterns","few-shot learning systems","prompt-engineering-patterns install","debugging LLM prompts"],"zh":["Prompt 工程模式","LLM 应用","结构化推理","少样本学习","动态示例选择","AI 工具","AIエージェント"],"ja":["プロンプトエンジニアリングパターン","LLM アプリケーション","構造化推論","少数-shot 学習","動的例選択","AI エージェント","AI ツール"],"ko":["프롬프트 엔지니어링 패턴","LLM 애플리케이션","구조화된 추론","少샘플 학습","동적 예시 선택","AI 에이전트","AI 툴"],"es":["patrones de ingeniería de prompt","LLM","aprendizaje de lenguaje natural","ingeniería de prompt","técnicas de optimización de prompts","desarrollo de aplicaciones LLM","Herramientas de AI","Agentes de IA"],"fr":["modèles d''ingénierie de prompt","LLM","apprentissage de langage naturel","ingénierie de prompt","techniques d''optimisation de prompts","développement d''applications LLM","Outils d''IA","Agents d''IA"],"de":["Prompt-Engineering-Muster","LLM","natürliche Sprachverarbeitung","Prompt-Engineering","Techniken zur Optimierung von Prompts","Entwicklung von LLM-Anwendungen","AI-Tools","KI-Agents"],"pt":["engenharia de prompt","LLM","padrões de engenharia de prompt","otimização de desempenho","consistência de prompts","raciocínio estruturado","modelos de prompts reutilizáveis","depuração de prompts"],"ru":["инженерия запросов","ИИ Агенты","шаблоны инженерии запросов","оптимизация производительности","согласованность запросов","структурированные шаблоны рассуждений","повторно используемые шаблоны запросов","отладка запросов"],"ar":["هندسة الاستدعاء","وكلاء ذكية","نماذج هندسة الاستدعاء","تحسين الأداء","موثوقية الاستدعاءات","أنماط استدلالية متعددة","نماذج استدعاء قابلة لإعادة الاستخدام","تصحيح الأخطاء في الاستدعاءات"]}},"owner":"brunoreinstein-cloud","repo":"chat-assitjur","repoPath":"brunoreinstein-cloud/chat-assitjur","stars":0,"forks":0,"updatedAt":"2026-03-02T20:44:15Z","topics":[],"category":"community","skillMd":{"name":"prompt-engineering-patterns","description":"Master advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability in production. Use when optimizing prompts, improving LLM outputs, or designing production prompt templates.","bodyPreview":"# Prompt Engineering Patterns\n\nMaster advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability.\n\n## When to Use This Skill\n\n- Designing complex prompts for production LLM applications\n- Optimizing prompt performance and consistency\n- Implementing structured reasoning patterns (chain-of-thought, tree-of-thought)\n- Building few-shot learning systems with dynamic example selection\n- Creating reusable prompt templates with variable interpolation\n- Debuggin","body":"# Prompt Engineering Patterns\n\nMaster advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability.\n\n## When to Use This Skill\n\n- Designing complex prompts for production LLM applications\n- Optimizing prompt performance and consistency\n- Implementing structured reasoning patterns (chain-of-thought, tree-of-thought)\n- Building few-shot learning systems with dynamic example selection\n- Creating reusable prompt templates with variable interpolation\n- Debugging and refining prompts that produce inconsistent outputs\n- Implementing system prompts for specialized AI assistants\n- Using structured outputs (JSON mode) for reliable parsing\n\n## Core Capabilities\n\n### 1. Few-Shot Learning\n\n- Example selection strategies (semantic similarity, diversity sampling)\n- Balancing example count with context window constraints\n- Constructing effective demonstrations with input-output pairs\n- Dynamic example retrieval from knowledge bases\n- Handling edge cases through strategic example selection\n\n### 2. Chain-of-Thought Prompting\n\n- Step-by-step reasoning elicitation\n- Zero-shot CoT with \"Let''s think step by step\"\n- Few-shot CoT with reasoning traces\n- Self-consistency techniques (sampling multiple reasoning paths)\n- Verification and validation steps\n\n### 3. Structured Outputs\n\n- JSON mode for reliable parsing\n- Pydantic schema enforcement\n- Type-safe response handling\n- Error handling for malformed outputs\n\n### 4. Prompt Optimization\n\n- Iterative refinement workflows\n- A/B testing prompt variations\n- Measuring prompt performance metrics (accuracy, consistency, latency)\n- Reducing token usage while maintaining quality\n- Handling edge cases and failure modes\n\n### 5. Template Systems\n\n- Variable interpolation and formatting\n- Conditional prompt sections\n- Multi-turn conversation templates\n- Role-based prompt composition\n- Modular prompt components\n\n### 6. System Prompt Design\n\n- Setting model behavior and constraints\n- Defining output formats and structure\n- Establishing role and expertise\n- Safety guidelines and content policies\n- Context setting and background information\n\n## Quick Start\n\n```python\nfrom langchain_anthropic import ChatAnthropic\nfrom langchain_core.prompts import ChatPromptTemplate\nfrom pydantic import BaseModel, Field\n\n# Define structured output schema\nclass SQLQuery(BaseModel):\n    query: str = Field(description=\"The SQL query\")\n    explanation: str = Field(description=\"Brief explanation of what the query does\")\n    tables_used: list[str] = Field(description=\"List of tables referenced\")\n\n# Initialize model with structured output\nllm = ChatAnthropic(model=\"claude-sonnet-4-6\")\nstructured_llm = llm.with_structured_output(SQLQuery)\n\n# Create prompt template\nprompt = ChatPromptTemplate.from_messages([\n    (\"system\", \"\"\"You are an expert SQL developer. Generate efficient, secure SQL queries.\n    Always use parameterized queries to prevent SQL injection.\n    Explain your reasoning briefly.\"\"\"),\n    (\"user\", \"Convert this to SQL: {query}\")\n])\n\n# Create chain\nchain = prompt | structured_llm\n\n# Use\nresult = await chain.ainvoke({\n    \"query\": \"Find all users who registered in the last 30 days\"\n})\nprint(result.query)\nprint(result.explanation)\n```\n\n## Key Patterns\n\n### Pattern 1: Structured Output with Pydantic\n\n```python\nfrom anthropic import Anthropic\nfrom pydantic import BaseModel, Field\nfrom typing import Literal\nimport json\n\nclass SentimentAnalysis(BaseModel):\n    sentiment: Literal[\"positive\", \"negative\", \"neutral\"]\n    confidence: float = Field(ge=0, le=1)\n    key_phrases: list[str]\n    reasoning: str\n\nasync def analyze_sentiment(text: str) -> SentimentAnalysis:\n    \"\"\"Analyze sentiment with structured output.\"\"\"\n    client = Anthropic()\n\n    message = client.messages.create(\n        model=\"claude-sonnet-4-6\",\n        max_tokens=500,\n        messages=[{\n            \"role\": \"user\",\n            \"content\": f\"\"\"Analyze the sentiment of this text.\n\nText: {text}\n\nRespond with JSON matching this schema:\n{{\n    \"sentiment\": \"positive\" | \"negative\" | \"neutral\",\n    \"confidence\": 0.0-1.0,\n    \"key_phrases\": [\"phrase1\", \"phrase2\"],\n    \"reasoning\": \"brief explanation\"\n}}\"\"\"\n        }]\n    )\n\n    return SentimentAnalysis(**json.loads(message.content[0].text))\n```\n\n### Pattern 2: Chain-of-Thought with Self-Verification\n\n```python\nfrom langchain_core.prompts import ChatPromptTemplate\n\ncot_prompt = ChatPromptTemplate.from_template(\"\"\"\nSolve this problem step by step.\n\nProblem: {problem}\n\nInstructions:\n1. Break down the problem into clear steps\n2. Work through each step showing your reasoning\n3. State your final answer\n4. Verify your answer by checking it against the original problem\n\nFormat your response as:\n## Steps\n[Your step-by-step reasoning]\n\n## Answer\n[Your final answer]\n\n## Verification\n[Check that your answer is correct]\n\"\"\")\n```\n\n### Pattern 3: Few-Shot with Dynamic Example Selection\n\n```python\nfrom langchain_voyageai import VoyageAIEmbeddings\nfrom langchain_core.example_selectors import SemanticSimilarityExampleSelector\nfrom langchain_chroma import Chroma\n\n# Create example selector with semantic similarity\nexample_selector = SemanticSimilarityExampleSelector.from_examples(\n    examples=[\n        {\"input\": \"How do I reset my password?\", \"output\": \"Go to Settings > Security > Reset Password\"},\n        {\"input\": \"Where can I see my order history?\", \"output\": \"Navigate to Account > Orders\"},\n        {\"input\": \"How do I contact support?\", \"output\": \"Click Help > Contact Us or email support@example.com\"},\n    ],\n    embeddings=VoyageAIEmbeddings(model=\"voyage-3-large\"),\n    vectorstore_cls=Chroma,\n    k=2  # Select 2 most similar examples\n)\n\nasync def get_few_shot_prompt(query: str) -> str:\n    \"\"\"Build prompt with dynamically selected examples.\"\"\"\n    examples = await example_selector.aselect_examples({\"input\": query})\n\n    examples_text = \"\\n\".join(\n        f\"User: {ex[''input'']}\\nAssistant: {ex[''output'']}\"\n        for ex in examples\n    )\n\n    return f\"\"\"You are a helpful customer support assistant.\n\nHere are some example interactions:\n{examples_text}\n\nNow respond to this query:\nUser: {query}\nAssistant:\"\"\"\n```\n\n### Pattern 4: Progressive Disclosure\n\nStart with simple prompts, add complexity only when needed:\n\n```python\nPROMPT_LEVELS = {\n    # Level 1: Direct instruction\n    \"simple\": \"Summarize this article: {text}\",\n\n    # Level 2: Add constraints\n    \"constrained\": \"\"\"Summarize this article in 3 bullet points, focusing on:\n- Key findings\n- Main conclusions\n- Practical implications\n\nArticle: {text}\"\"\",\n\n    # Level 3: Add reasoning\n    \"reasoning\": \"\"\"Read this article carefully.\n1. First, identify the main topic and thesis\n2. Then, extract the key supporting points\n3. Finally, summarize in 3 bullet points\n\nArticle: {text}\n\nSummary:\"\"\",\n\n    # Level 4: Add examples\n    \"few_shot\": \"\"\"Read articles and provide concise summaries.\n\nExample:\nArticle: \"New research shows that regular exercise can reduce anxiety by up to 40%...\"\nSummary:\n• Regular exercise reduces anxiety by up to 40%\n• 30 minutes of moderate activity 3x/week is sufficient\n• Benefits appear within 2 weeks of starting\n\nNow summarize this article:\nArticle: {text}\n\nSummary:\"\"\"\n}\n```\n\n### Pattern 5: Error Recovery and Fallback\n\n```python\nfrom pydantic import BaseModel, ValidationError\nimport json\n\nclass ResponseWithConfidence(BaseModel):\n    answer: str\n    confidence: float\n    sources: list[str]\n    alternative_interpretations: list[str] = []\n\nERROR_RECOVERY_PROMPT = \"\"\"\nAnswer the question based on the context provided.\n\nContext: {context}\nQuestion: {question}\n\nInstructions:\n1. If you can answer confidently (>0.8), provide a direct answer\n2. If you''re somewhat confident (0.5-0.8), provide your best answer with caveats\n3. If you''re uncertain (<0.5), explain what information is missing\n4. Always provide alternative interpretations if the question is ambiguous\n\nRespond in JSON:\n{{\n    \"answer\": \"your answer or ''I cannot determine this from the context''\",\n    \"confidence\": 0.0-1.0,\n    \"sources\": [\"relevant context excerpts\"],\n    \"alternative_interpretations\": [\"if question is ambiguous\"]\n}}\n\"\"\"\n\nasync def answer_with_fallback(\n    context: str,\n    question: str,\n    llm\n) -> ResponseWithConfidence:\n    \"\"\"Answer with error recovery and fallback.\"\"\"\n    prompt = ERROR_RECOVERY_PROMPT.format(context=context, question=question)\n\n    try:\n        response = await llm.ainvoke(prompt)\n        return ResponseWithConfidence(**json.loads(response.content))\n    except (json.JSONDecodeError, ValidationError) as e:\n        # Fallback: try to extract answer without structure\n        simple_prompt = f\"Based on: {context}\\n\\nAnswer: {question}\"\n        simple_response = await llm.ainvoke(simple_prompt)\n        return ResponseWithConfidence(\n            answer=simple_response.content,\n            confidence=0.5,\n            sources=[\"fallback extraction\"],\n            alternative_interpretations=[]\n        )\n```\n\n### Pattern 6: Role-Based System Prompts\n\n```python\nSYSTEM_PROMPTS = {\n    \"analyst\": \"\"\"You are a senior data analyst with expertise in SQL, Python, and business intelligence.\n\nYour responsibilities:\n- Write efficient, well-documented queries\n- Explain your analysis methodology\n- Highlight key insights and recommendations\n- Flag any data quality concerns\n\nCommunication style:\n- Be precise and technical when discussing methodology\n- Translate technical findings into business impact\n- Use clear visualizations when helpful\"\"\",\n\n    \"assistant\": \"\"\"You are a helpful AI assistant focused on accuracy and clarity.\n\nCore principles:\n- Always cite sources when making factual claims\n- Acknowledge uncertainty rather than guessing\n- Ask clarifying questions when the request is ambiguous\n- Provide step-by-step explanations for complex topics\n\nConstraints:\n- Do not provide medical, legal, or financial advice\n- Redirect harmful requests appropriately\n- Protect user privacy\"\"\",\n\n    \"code_reviewer\": \"\"\"You are a senior software engineer conducting code reviews.\n\nReview criteria:\n- Correctness: Does the code work as intended?\n- Security: Are there any vulnerabilities?\n- Performance: Are there efficiency concerns?\n- Maintainability: Is the code readable and well-structured?\n- Best practices: Does it follow language idioms?\n\nOutput format:\n1. Summary assessment (approve/request changes)\n2. Critical issues (must fix)\n3. Suggestions (nice to have)\n4. Positive feedback (what''s done well)\"\"\"\n}\n```\n\n## Integration Patterns\n\n### With RAG Systems\n\n```python\nRAG_PROMPT = \"\"\"You are a knowledgeable assistant that answers questions based on provided context.\n\nContext (retrieved from knowledge base):\n{context}\n\nInstructions:\n1. Answer ONLY based on the provided context\n2. If the context doesn''t contain the answer, say \"I don''t have information about that in my knowledge base\"\n3. Cite specific passages using [1], [2] notation\n4. If the question is ambiguous, ask for clarification\n\nQuestion: {question}\n\nAnswer:\"\"\"\n```\n\n### With Validation and Verification\n\n```python\nVALIDATED_PROMPT = \"\"\"Complete the following task:\n\nTask: {task}\n\nAfter generating your response, verify it meets ALL these criteria:\n✓ Directly addresses the original request\n✓ Contains no factual errors\n✓ Is appropriately detailed (not too brief, not too verbose)\n✓ Uses proper formatting\n✓ Is safe and appropriate\n\nIf verification fails on any criterion, revise before responding.\n\nResponse:\"\"\"\n```\n\n## Performance Optimization\n\n### Token Efficiency\n\n```python\n# Before: Verbose prompt (150+ tokens)\nverbose_prompt = \"\"\"\nI would like you to please take the following text and provide me with a comprehensive\nsummary of the main points. The summary should capture the key ideas and important details\nwhile being concise and easy to understand.\n\"\"\"\n\n# After: Concise prompt (30 tokens)\nconcise_prompt = \"\"\"Summarize the key points concisely:\n\n{text}\n\nSummary:\"\"\"\n```\n\n### Caching Common Prefixes\n\n```python\nfrom anthropic import Anthropic\n\nclient = Anthropic()\n\n# Use prompt caching for repeated system prompts\nresponse = client.messages.create(\n    model=\"claude-sonnet-4-6\",\n    max_tokens=1000,\n    system=[\n        {\n            \"type\": \"text\",\n            \"text\": LONG_SYSTEM_PROMPT,\n            \"cache_control\": {\"type\": \"ephemeral\"}\n        }\n    ],\n    messages=[{\"role\": \"user\", \"content\": user_query}]\n)\n```\n\n## Best Practices\n\n1. **Be Specific**: Vague prompts produce inconsistent results\n2. **Show, Don''t Tell**: Examples are more effective than descriptions\n3. **Use Structured Outputs**: Enforce schemas with Pydantic for reliability\n4. **Test Extensively**: Evaluate on diverse, representative inputs\n5. **Iterate Rapidly**: Small changes can have large impacts\n6. **Monitor Performance**: Track metrics in production\n7. **Version Control**: Treat prompts as code with proper versioning\n8. **Document Intent**: Explain why prompts are structured as they are\n\n## Common Pitfalls\n\n- **Over-engineering**: Starting with complex prompts before trying simple ones\n- **Example pollution**: Using examples that don''t match the target task\n- **Context overflow**: Exceeding token limits with excessive examples\n- **Ambiguous instructions**: Leaving room for multiple interpretations\n- **Ignoring edge cases**: Not testing on unusual or boundary inputs\n- **No error handling**: Assuming outputs will always be well-formed\n- **Hardcoded values**: Not parameterizing prompts for reuse\n\n## Success Metrics\n\nTrack these KPIs for your prompts:\n\n- **Accuracy**: Correctness of outputs\n- **Consistency**: Reproducibility across similar inputs\n- **Latency**: Response time (P50, P95, P99)\n- **Token Usage**: Average tokens per request\n- **Success Rate**: Percentage of valid, parseable outputs\n- **User Satisfaction**: Ratings and feedback\n\n## Resources\n\n- [Anthropic Prompt Engineering Guide](https://docs.anthropic.com/en/docs/build-with-claude/prompt-engineering)\n- [Claude Prompt Caching](https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching)\n- [OpenAI Prompt Engineering](https://platform.openai.com/docs/guides/prompt-engineering)\n- [LangChain Prompts](https://python.langchain.com/docs/concepts/prompts/)\n"},"lastSynced":"2026-03-07T13:09:54.001Z","agentAnalysis":{"suitability":{"en":"Perfect for LLM Agents needing advanced prompt engineering capabilities for production applications","zh":"非常适合需要高级提示工程能力的LLM代理用于生产应用","ja":"生産アプリケーション向けの高度なプロンプトエンジニアリング機能を必要とするLLMエージェントに最適","ko":"생산 응용 프로그램을 위한 고급 프롬프트 엔지니어링 기능이 필요한 LLM 에이전트에 적합","es":"Perfecto para agentes LLM que necesitan capacidades de ingeniería de prompts avanzadas para aplicaciones de producción","fr":"Parfait pour les agents LLM qui ont besoin de capacités de conception de prompts avancées pour les applications de production","de":"Perfekt für LLM-Agents, die erweiterte Prompt-Engineering-Fähigkeiten für Produktionsanwendungen benötigen","pt":"Perfeito para Agentes LLM que necessitam de capacidades avançadas de engenharia de prompts para aplicações de produção","ru":"Идеально для агентов LLM, которым требуются расширенные возможности инженерии подсказок для производственных приложений","ar":"مثالي للوكلاء LLM الذين يحتاجون إلى قدرات هندسة متقدمة لتقديم طلبات لاتطبيق الإنتاج"},"recommendation":{"en":"Empowers agents to master chain-of-thought and tree-of-thought patterns, optimize prompt performance, and implement dynamic example selection for few-shot learning systems using advanced prompt engineering techniques and reusable prompt templates with variable interpolation","zh":"赋予代理掌握链式思维和树式思维模式、优化提示性能，并使用高级提示工程技术和可重用提示模板实现少样本学习系统的动态示例选择","ja":"エージェントが連鎖的思考と樹的思考のパターンをマスターし、プロンプトのパフォーマンスを最適化し、高度なプロンプトエンジニアリング技術と再利用可能なプロンプトテンプレートを使用して、少샘플学習システムの動的例選択を実装することを可能にする","ko":"에이전트가 사슬식 사고와 나무식 사고 패턴을 마스터하고 프롬프트 성능을 최적화하며 고급 프롬프트 엔지니어링 기술과 재사용 가능한 프롬프트 템플릿을 사용하여 소샘플 학습 시스템의 동적 예제 선택을 구현할 수 있도록 한다","es":"Habilita a los agentes a dominar patrones de cadena de pensamiento y árbol de pensamiento, optimizar el rendimiento de los prompts y implementar una selección de ejemplos dinámicos para sistemas de aprendizaje de pocos disparos utilizando técnicas de ingeniería de prompts avanzadas y plantillas de prompts reutilizables con interpolación de variables","fr":"Permet aux agents de maîtriser les modèles de chaîne de pensée et d''arbre de pensée, d''optimiser les performances des prompts et de mettre en œuvre une sélection d''exemples dynamiques pour les systèmes d''apprentissage à quelques exemples en utilisant des techniques de conception de prompts avancées et des modèles de prompts réutilisables avec interpolation de variables","de":"Ermächtigt die Agenten, Muster von Gedankenketten und Gedankenbäumen zu beherrschen, die Leistung von Prompts zu optimieren und eine dynamische Beispielauswahl für Few-Shot-Learning-Systeme mit Hilfe von erweiterten Prompt-Engineering-Techniken und wiederverwendbaren Prompt-Vorlagen mit Variableninterpolation zu implementieren","pt":"Habilita os agentes a dominar padrões de cadeia de pensamento e árvore de pensamento, otimizar o desempenho do prompt e implementar seleção dinâmica de exemplos para sistemas de aprendizado de poucos disparos usando técnicas avançadas de engenharia de prompts e modelos de prompts reutilizáveis com interpolação de variáveis","ru":"Наделяет агентов возможностью овладеть цепочками мыслей и деревьями мыслей, оптимизировать производительность подсказок и реализовать динамический выбор примеров для систем обучения с少численными выстрелами, используя продвинутые техники инженерии подсказок и многократно используемые шаблоны подсказок с интерполацией переменных","ar":"تمكّن الوكلاء من السيطرة على أنماط سلسلة التفكير و شجرة التفكير، وتحسين أداء الطلب، وتنفيذ اختيار ديناميكي للأمثلة لنظم التعلم ذي العدد القليل من الحالات باستخدام تقنيات متقدمة لتقديم الطلبات وقوالب طلبات قابلة لإعادة الاستخدام مع استبدال المتغيرات"},"useCases":{"en":["Designing complex prompts for production LLM applications","Optimizing prompt performance and consistency","Implementing structured reasoning patterns for chain-of-thought and tree-of-thought","Building few-shot learning systems with dynamic example selection","Creating reusable prompt templates with variable interpolation"],"zh":["设计用于生产LLM应用的复杂提示","优化提示性能和一致性","实现链式思维和树式思维的结构化推理模式","使用动态示例选择构建少样本学习系统","创建具有变量插值的可重用提示模板"],"ja":["生産用LLMアプリケーションの複雑なプロンプトを設計する","プロンプトのパフォーマンスと一貫性を最適化する","連鎖的思考と樹的思考の構造化された推論パターンを実装する","動的例選択を使用して少샘플学習システムを構築する","変数補間を備えた再利用可能なプロンプトテンプレートを作成する"],"ko":["생산용 LLM 응용 프로그램을 위한 복잡한 프롬프트 설계","프롬프트 성능과 일관성을 최적화","사슬식 사고와 나무식 사고의 구조화된 추론 패턴 구현","동적 예제 선택을 사용하여 소샘플 학습 시스템 구축","변수 삽입을 갖춘 재사용 가능한 프롬프트 템플릿 생성"],"es":["Diseñar prompts complejos para aplicaciones LLM de producción","Optimizar el rendimiento y la consistencia de los prompts","Implementar patrones de razonamiento estructurados para cadenas de pensamiento y árboles de pensamiento","Crear sistemas de aprendizaje de pocos disparos con selección de ejemplos dinámicos","Crear plantillas de prompts reutilizables con interpolación de variables"],"fr":["Concevoir des prompts complexes pour les applications LLM de production","Optimiser les performances et la cohérence des prompts","Mettre en œuvre des modèles de raisonnement structurés pour les chaînes de pensée et les arbres de pensée","Créer des systèmes d''apprentissage à quelques exemples avec une sélection d''exemples dynamiques","Créer des modèles de prompts réutilisables avec interpolation de variables"],"de":["Komplexe Prompts für Produktions-LLM-Anwendungen entwerfen","Die Leistung und Konsistenz von Prompts optimieren","Strukturierte Denkmuster für Gedankenketten und Gedankenbäume implementieren","Few-Shot-Learning-Systeme mit dynamischer Beispielauswahl erstellen","Wiederverwendbare Prompt-Vorlagen mit Variableninterpolation erstellen"],"pt":["Projeto de prompts complexos para aplicações LLM de produção","Otimização do desempenho e consistência do prompt","Implementação de padrões de raciocínio estruturados para cadeia de pensamento e árvore de pensamento","Construção de sistemas de aprendizado de poucos disparos com seleção dinâmica de exemplos","Criação de modelos de prompts reutilizáveis com interpolação de variáveis"],"ru":["Проектирование сложных подсказок для производственных приложений LLM","Оптимизация производительности и последовательности подсказок","Реализация структурированных шаблонов рассуждений для цепочки мыслей и дерева мыслей","Создание систем обучения с少численными выстрелами с динамическим выбором примеров","Создание многократно используемых шаблонов подсказок с интерполацией переменных"],"ar":["تصميم طلبات معقدة لتطبيقات الإنتاج LLM","تحسين أداء الطلب وثباته","تنفيذ أنماط متكاملة من التفكير لسلسلة التفكير و شجرة التفكير","بناء نظم التعلم ذي العدد القليل من الحالات مع اختيار ديناميكي للأمثلة","إنشاء قوالب طلبات قابلة لإعادة الاستخدام مع استبدال المتغيرات"]},"limitations":{"en":["Requires understanding of LLM applications and prompt engineering principles","May require additional development for integration with specific LLM models"],"zh":["需要了解LLM应用和提示工程原理","可能需要额外的开发来与特定的LLM模型集成"],"ja":["LLMアプリケーションとプロンプトエンジニアリングの原理を理解する必要がある","特定のLLMモデルとの統合には追加の開発が必要になる場合がある"],"ko":["LLM 응용 프로그램과 프롬프트 엔지니어링 원리를 이해해야 함","특정 LLM 모델과 통합하기 위해 추가 개발이 필요할 수 있음"],"es":["Requiere comprensión de las aplicaciones LLM y los principios de ingeniería de prompts","Puede requerir un desarrollo adicional para la integración con modelos LLM específicos"],"fr":["Nécessite une compréhension des applications LLM et des principes de conception de prompts","Peut nécessiter un développement supplémentaire pour l''intégration avec des modèles LLM spécifiques"],"de":["Benötigt Verständnis für LLM-Anwendungen und Prompt-Engineering-Grundsätze","Kann zusätzliche Entwicklung für die Integration mit bestimmten LLM-Modellen erfordern"],"pt":["Exige compreensão de aplicações LLM e princípios de engenharia de prompts","Pode exigir desenvolvimento adicional para integração com modelos LLM específicos"],"ru":["Требует понимания приложений LLM и принципов инженерии подсказок","Может требовать дополнительного развития для интеграции с определенными моделями LLM"],"ar":["يتطلب فهمًا لتطبيقات LLM ومبادئ هندسة الطلبات","يمكن أن يتطلب تطويرًا إضافيًا لتكامل مع نماذج LLM محددة"]},"version":4},"contentHash":"747cb530259ee0d6f77d9b57fd649ec49c292f7a9808939f5a64cd0aa7d8f4c6","qualityScore":60}');
