INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hoanghd218/tranvanhoang.com/ck:research', 'ck:research', 'hoanghd218', 'tranvanhoang.com', 'community', 'ck:research hoanghd218 tranvanhoang.com community ck:research is a systematic research methodology for AI agents, honoring YAGNI, KISS, and DRY principles. It benefits developers by providing a clear research scope definition and evaluation criteria. ck:research是一种研究方法论，遵循YAGNI、KISS和DRY原则，提供范围定义、系统信息收集和评估标准设置等功能 ck:researchは、YAGNI、KISS、DRY原則に従った研究方法論で、範囲定義、体系的な情報収集、評価基準設定などの機能を提供 ck:research는 YAGNI, KISS, DRY 원칙을 따르는 연구 방법론으로, 범위 정의, 체계적인 정보 수집, 평가 기준 설정 등의 기능을 제공 ck:research es una habilidad que permite una investigación sistemática y eficiente, siguiendo los principios YAGNI, KISS y DRY ck:research est une compétence qui permet une recherche systématique et optimisée, suivant les principes YAGNI, KISS et DRY ck:research ist eine Fähigkeit, die eine systematische und effiziente Forschung ermöglicht, indem sie die Prinzipien YAGNI, KISS und DRY befolgt O ck:research é uma ferramenta de pesquisa que segue os princípios YAGNI, KISS e DRY para fornecer resultados precisos ck:research - это инструмент исследования, следующий принципам YAGNI, KISS и DRY для предоставления точных результатов ck:research هو أداة بحث تتبع مبادئ YAGNI و KISS و DRY لتقديم نتائج دقيقة how to use ck:research ck:research alternative ck:research setup guide what is ck:research ck:research vs traditional research methods ck:research install ck:research 研究方法论 范围定义 系统信息收集 评估标准设置 YAGNI KISS DRY AI工具 研究方法 Applies YAGNI, KISS, and DRY principles for efficient research Defines research scope by identifying key terms and concepts Determines recency requirements for information gathering Establishes evaluation criteria for sources Sets boundaries for research depth ck:research is a research methodology that follows a phased approach, including scope definition and systematic information gathering, to provide concise and honest research results.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Vero-Ventures/fuzzycat/vercel', 'community', 'Vero-Ventures', 'fuzzycat', 'Vero-Ventures/fuzzycat', 'vercel', 0, 0, 60, '2026-03-04T01:48:02Z', '2026-03-07T04:11:21.103Z', '081242f4d557817cbcec0e7cd9ef0c407a9d653ba055ca5ba2c817e0d5b0f98e', '{"id":"Vero-Ventures/fuzzycat/vercel","name":"vercel","description":{"en":"The Vercel skill provides deployment management for FuzzyCat''s Vercel deployments, utilizing the Vercel CLI for streamlined deployment inspection and management. It benefits developers and DevOps teams working with Vercel.","zh":"Vercel CLI是用于管理Vercel部署的命令行工具，支持部署、日志查看和状态检查","ja":"Vercel CLIはVercelのデプロイを管理するコマンドラインツールで、デプロイ、ログの確認、ステータスの確認をサポートします","ko":"Vercel CLI는 Vercel 배포를 관리하는 명령줄 도구로, 배포, 로그 확인, 상태 확인을 지원합니다","es":"Vercel es una plataforma para despliegues automatizados que permite gestionar proyectos con facilidad","fr":"Vercel est une plateforme de déploiement automatique qui permet de gérer les projets avec facilité","de":"Vercel ist eine Plattform für automatisierte Deployments, die es ermöglicht, Projekte einfach zu verwalten","pt":"O Vercel é uma ferramenta para gerenciar implantações de aplicativos. Use comandos como vercel ls e vercel inspect para gerenciar suas implantações.","ru":"Vercel - это инструмент для управления развертываниями приложений. Используйте команды vercel ls и vercel inspect для управления своими развертываниями.","ar":"Vercel هو أداة لإدارة توزيعات التطبيقات. استخدم أوامر مثل vercel ls و vercel inspect لإدارة توزيعاتك."},"seo":{"title":{"en":"Vercel: Deployment Management Setup Guide | AI Agent Skill","zh":"Vercel CLI_SETUP GUIDE","ja":"Vercel CLIセットアップガイド","ko":"Vercel CLI설치 가이드","es":"Guía de configuración de Vercel para despliegues automati...","fr":"Configurer Vercel pour des déploiements automatiques","de":"Vercel-Setup-Anleitung für automatisierte Deployments","pt":"Guia de Configuração Vercel para Desenvolvedores","ru":"ИИ Агенты: Руководство по Настройке Vercel","ar":"دليل إعداد Vercel لللمطورين"},"description":{"en":"Discover how to streamline Vercel deployments with the Vercel CLI. Learn to manage and inspect deployments with ease, and get started with our expert guide.","zh":"了解Vercel CLI的功能和用法，包括部署、日志查看和状态检查","ja":"Vercel CLIの機能と使い方を紹介します。デプロイ、ログの確認、ステータスの確認など","ko":"Vercel CLI의 기능과 사용법을 알아보세요. 배포, 로그 확인, 상태 확인 등","es":"Aprende a utilizar Vercel para despliegues automatizados y gestiona tus proyectos con facilidad","fr":"Découvrez comment utiliser Vercel pour des déploiements automatiques et gérer vos projets avec facilité","de":"Erfahren Sie, wie Sie Vercel für automatisierte Deployments verwenden und Ihre Projekte einfach verwalten","pt":"Aprenda a configurar o Vercel CLI e gerenciar implantações com comandos como vercel ls e vercel inspect","ru":"Узнайте, как настроить Vercel CLI и управлять развертываниями с помощью команд vercel ls и vercel inspect","ar":"تعلم كيفية تكوين Vercel CLI وإدارة التوزيعات باستخدام أوامر مثل vercel ls و vercel inspect"},"definition":{"en":"Vercel is a platform for deploying and managing web applications, utilizing the Vercel CLI for deployment management and inspection.","zh":"Vercel CLI是Vercel的命令行接口，用于管理和部署应用","ja":"Vercel CLIはVercelのコマンドラインインターフェースで、アプリケーションの管理とデプロイを行います","ko":"Vercel CLI는 Vercel의 명령줄 인터페이스로, 애플리케이션 관리와 배포를 수행합니다","es":"Vercel es una herramienta de línea de comandos (CLI) para gestionar despliegues automatizados","fr":"Vercel est un outil de ligne de commande (CLI) pour gérer les déploiements automatiques","de":"Vercel ist ein Kommandozeilen-Tool (CLI) für die Verwaltung von automatisierten Deployments","pt":"O que é Vercel? É uma ferramenta de linha de comando para gerenciar implantações de aplicativos","ru":"Что такое Vercel? Это командная строка инструмент для управления развертываниями приложений","ar":"ما هو Vercel؟ إنه أداة سطر أوامر لإدارة توزيعات التطبيقات"},"features":{"en":["Manages FuzzyCat''s Vercel deployments via the Vercel CLI","Lists recent deployments using the `vercel ls` command","Retrieves latest deployment URL with `vercel ls --json`","Inspects deployment details with `vercel inspect <deployment-url>`","Views deployment logs for debugging and monitoring"],"zh":["支持部署和日志查看","可以查看部署状态和创建时间","支持使用Python脚本解析JSON数据","可以使用vercel ls命令列出最近的部署","可以使用vercel inspect命令查看部署详情","支持使用CLI命令行工具进行管理"],"ja":["デプロイとログの確認をサポート","デプロイの状態と作成時間を確認できる","Pythonスクリプトを使用してJSONデータを解析","vercel lsコマンドを使用して最近のデプロイを一覧表示","vercel inspectコマンドを使用してデプロイの詳細を確認","CLIコマンドラインツールを使用して管理"],"ko":["배포와 로그 확인을 지원","배포 상태와 생성 시간을 확인할 수 있음","Python 스크립트를 사용하여 JSON 데이터를 파싱","vercel ls 명령을 사용하여 최근의 배포를 목록으로 표시","vercel inspect 명령을 사용하여 배포 세부 정보를 확인","CLI 명령줄 도구를 사용하여 관리"],"es":["Despliegue automatizado con Vercel CLI","Gestión de despliegues con comandos como `vercel ls` y `vercel inspect`","Autenticación integrada para acceso seguro","Compatibilidad con Python para scripting personalizado","Visualización de registros de despliegue para depuración"],"fr":["Déploiement automatique avec Vercel CLI","Gestion des déploiements avec des commandes comme `vercel ls` et `vercel inspect`","Authentification intégrée pour un accès sécurisé","Compatibilité avec Python pour un scripting personnalisé","Visualisation des journaux de déploiement pour la débogage"],"de":["Automatisierte Deployment mit Vercel CLI","Verwaltung von Deployments mit Befehlen wie `vercel ls` und `vercel inspect`","Integrierte Authentifizierung für sicheren Zugriff","Kompatibilität mit Python für benutzerdefiniertes Scripting","Anzeige von Deployments-Protokollen für Fehlerbehebung"],"pt":["Gerenciamento de implantações com Vercel CLI","Uso de comandos como vercel ls e vercel inspect","Autenticação pré-configurada em ~/.bun/bin/vercel","Suporte a implantações recentes e detalhes de implantação","Integração com Python para análise de implantações"],"ru":["Управление развертываниями с помощью Vercel CLI","Использование команд vercel ls и vercel inspect","Предварительная аутентификация в ~/.bun/bin/vercel","Поддержка недавних развертываний и деталей развертывания","Интеграция с Python для анализа развертываний"],"ar":["إدارة التوزيعات باستخدام Vercel CLI","استخدام أوامر مثل vercel ls و vercel inspect","التحقق المسبق في ~/.bun/bin/vercel","دعم التوزيعات الحديثة و تفاصيل التوزيع","التكامل مع Python للتحليل التوزيعات"]},"keywords":{"en":["how to use Vercel CLI","Vercel deployment management","Vercel alternative","Vercel vs Netlify","Vercel install guide","Vercel setup tutorial","what is Vercel","Vercel benefits for developers","Vercel deployment automation"],"zh":["Vercel CLI","Vercel部署","命令行工具","Python脚本","JSON数据解析","vercel ls","vercel inspect","AIエージェント","开发者工具"],"ja":["Vercel CLI","Vercelデプロイ","コマンドラインツール","Pythonスクリプト","JSONデータ解析","vercel ls","vercel inspect","AIエージェント","開発者ツール"],"ko":["Vercel CLI","Vercel 배포","명령줄 도구","Python 스크립트","JSON 데이터 파싱","vercel ls","vercel inspect","AI 에이전트","개발자 도구"],"es":["vercel","despliegue automatizado","cli","python","gestión de despliegues","autenticación","registros de despliegue","herramientas de desarrollo","desarrollo web"],"fr":["vercel","déploiement automatique","cli","python","gestion des déploiements","authentification","journaux de déploiement","outils de développement","développement web"],"de":["vercel","automatisierte deployment","cli","python","verwaltung von deployments","authentifizierung","deployments-protokolle","entwicklertools","webentwicklung"],"pt":["Vercel CLI","gerenciamento de implantações","comandos vercel","autenticação pré-configurada","implantações recentes","detalhes de implantação","integração com Python","desenvolvimento de aplicativos"],"ru":["Vercel CLI","управление развертываниями","команды vercel","предварительная аутентификация","недавние развертывания","детали развертывания","интеграция с Python","разработка приложений"],"ar":["Vercel CLI","إدارة التوزيعات","أوامر vercel","التحقق المسبق","التوزيعات الحديثة","تفاصيل التوزيع","التكامل مع Python","تطوير التطبيقات"]}},"owner":"Vero-Ventures","repo":"fuzzycat","repoPath":"Vero-Ventures/fuzzycat","stars":0,"forks":0,"updatedAt":"2026-03-04T01:48:02Z","topics":[],"category":"community","skillMd":{"name":"vercel","description":">","bodyPreview":"# Vercel CLI\n\nManage FuzzyCat''s Vercel deployments. The CLI is installed at `~/.bun/bin/vercel` and\nalready authenticated.\n\n## Common Commands\n\n### Deployments\n\n```bash\n# List recent deployments\nvercel ls\n\n# Get latest deployment URL\nvercel ls --json 2>/dev/null | python3 -c \"\nimport sys,json\ndeploys=json.load(sys.stdin)\nif deploys: print(f\\\"{deploys[0][''url'']} | {deploys[0][''state'']} | {deploys[0][''createdAt'']}\\\")\"\n\n# Get deployment details\nvercel inspect <deployment-url>\n\n# View deployment log","body":"# Vercel CLI\n\nManage FuzzyCat''s Vercel deployments. The CLI is installed at `~/.bun/bin/vercel` and\nalready authenticated.\n\n## Common Commands\n\n### Deployments\n\n```bash\n# List recent deployments\nvercel ls\n\n# Get latest deployment URL\nvercel ls --json 2>/dev/null | python3 -c \"\nimport sys,json\ndeploys=json.load(sys.stdin)\nif deploys: print(f\\\"{deploys[0][''url'']} | {deploys[0][''state'']} | {deploys[0][''createdAt'']}\\\")\"\n\n# Get deployment details\nvercel inspect <deployment-url>\n\n# View deployment logs\nvercel logs <deployment-url>\n\n# View real-time logs (streaming)\nvercel logs <deployment-url> --follow\n```\n\n### Environment Variables\n\n```bash\n# List all env vars\nvercel env ls\n\n# List env vars for specific environment\nvercel env ls --environment production\n\n# Pull env vars to a file\nvercel env pull /tmp/prod-env.txt --environment production\n\n# Add an env var (all environments)\nvercel env add VAR_NAME\n\n# Add env var for specific environment\nvercel env add VAR_NAME production\n\n# Remove an env var\nvercel env rm VAR_NAME\n```\n\n### Domains\n\n```bash\n# List domains\nvercel domains ls\n\n# Inspect domain\nvercel domains inspect fuzzycatapp.com\n\n# Add a domain\nvercel domains add subdomain.fuzzycatapp.com\n```\n\n### Projects\n\n```bash\n# Project info\nvercel project ls\n\n# Link current directory to project\nvercel link\n```\n\n### Manual Deployment\n\n```bash\n# Deploy to preview\nvercel\n\n# Deploy to production (prefer auto-deploy via git push)\nvercel --prod\n\n# Note: Auto-deploys from GitHub are the standard workflow.\n# Manual vercel --prod should be avoided unless auto-deploys are broken.\n```\n\n### Debugging\n\n```bash\n# Check build output\nvercel logs <url> --output json 2>/dev/null | python3 -c \"\nimport sys,json\nfor line in sys.stdin:\n    try:\n        entry = json.loads(line)\n        if entry.get(''type'') == ''error'':\n            print(f\\\"ERROR: {entry.get(''text'','''')}\\\")\n    except: pass\"\n\n# Check function logs (serverless)\nvercel logs <url> --follow\n\n# Check if deployment is healthy\ncurl -sL https://www.fuzzycatapp.com/api/health | python3 -m json.tool\n```\n\n## Production Checks\n\n```bash\n# Quick health check\ncurl -sL https://www.fuzzycatapp.com/api/health | jq .status\n\n# Check API v1\ncurl -sL https://www.fuzzycatapp.com/api/v1/health | python3 -m json.tool\n\n# Check deployment status\nvercel ls 2>/dev/null | head -5\n```\n\n## FuzzyCat-Specific\n\n- **Project**: `fuzzy-cat-apps-projects/fuzzycat`\n- **Production URL**: `https://www.fuzzycatapp.com`\n- **Framework**: Next.js (auto-detected by Vercel)\n- **Build command**: `next build` (Vercel default)\n- **Preview deploys**: Currently disabled via `vercel.json` `ignoreCommand`\n- **Auto-deploys**: Triggered by pushes to `main` branch on GitHub\n- **Environments**: Development, Preview, Production (each with separate env vars)\n"},"lastSynced":"2026-03-07T04:11:21.103Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing streamlined Vercel deployment management and inspection capabilities.","zh":"非常适合需要简化Vercel部署管理和检查功能的DevOps代理。","ja":"Vercelのデプロイメント管理と検査機能をストリーミングする必要があるDevOpsエージェントに最適です。","ko":"Vercel 배포 관리와 검사 기능을 간소화해야 하는 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan una gestión de despliegue de Vercel simplificada y capacidades de inspección.","fr":"Parfait pour les agents DevOps ayant besoin d''une gestion de déploiement Vercel simplifiée et de capacités d''inspection.","de":"Perfekt für DevOps-Agents, die eine vereinfachte Vercel-Bereitstellungsverwaltung und Inspektion benötigen.","pt":"Perfeito para Agentes de DevOps que precisam de gestão de implantação do Vercel e capacidades de inspeção simplificadas.","ru":"Идеально подходит для агентов DevOps, которым необходима упрощенная управление развертываниями Vercel и возможности инспекции.","ar":"مثالي لعميل DevOps الذي يحتاج إلى إدارة وتفتيش بسيطة لعمليات نشر Vercel."},"recommendation":{"en":"Empowers agents to manage FuzzyCat''s Vercel deployments using the Vercel CLI, providing features like deployment inspection, log viewing, and URL retrieval via JSON output, leveraging Python for data parsing and utilizing protocols like CLI commands.","zh":"通过使用Vercel CLI，能够让代理管理FuzzyCat的Vercel部署，提供部署检查、日志查看和通过JSON输出检索URL等功能，同时利用Python进行数据解析，并使用类似CLI命令的协议。","ja":"Vercel CLIを使用して、エージェントがFuzzyCatのVercelデプロイメントを管理できるようにし、デプロイメントの検査、ログの表示、JSON出力によるURLの取得などの機能を提供し、Pythonを使用してデータを解析し、CLIコマンドなどのプロトコルを利用します。","ko":"Vercel CLI를 사용하여 에이전트가 FuzzyCat의 Vercel 배포를 관리할 수 있도록 하며, 배포 검사, 로그 보기 및 JSON 출력을 통해 URL을 가져오는 것과 같은 기능을 제공하고, Python을 사용하여 데이터를 파싱하며, CLI 명령과 같은 프로토콜을 활용합니다.","es":"Habilita a los agentes a gestionar los despliegues de Vercel de FuzzyCat utilizando el Vercel CLI, proporcionando características como inspección de despliegue, visualización de registros y recuperación de URL a través de salida JSON, aprovechando Python para el análisis de datos y utilizando protocolos como comandos CLI.","fr":"Permet aux agents de gérer les déploiements Vercel de FuzzyCat en utilisant le Vercel CLI, fournissant des fonctionnalités comme l''inspection de déploiement, la visualisation de journaux et la récupération d''URL via une sortie JSON, en exploitant Python pour l''analyse de données et en utilisant des protocoles comme des commandes CLI.","de":"Ermöglicht es Agenten, FuzzyCats Vercel-Bereitstellungen mit dem Vercel CLI zu verwalten, indem es Funktionen wie Bereitstellungsinspektion, Protokollanzeige und URL-Rückgewinnung über JSON-Ausgabe bereitstellt, wobei Python für die Datenanalyse genutzt wird und Protokolle wie CLI-Befehle verwendet werden.","pt":"Habilita agentes a gerenciar implantações do Vercel da FuzzyCat usando o Vercel CLI, fornecendo recursos como inspeção de implantação, visualização de logs e recuperação de URLs via saída JSON, utilizando Python para análise de dados e utilizando protocolos como comandos CLI.","ru":"Наделяет агентов возможностью управлять развертываниями Vercel от FuzzyCat с помощью Vercel CLI, предоставляя функции, такие как инспекция развертывания, просмотр журналов и получение URL-адресов через JSON-выход, используя Python для парсинга данных и используя протоколы, такие как команды CLI.","ar":"يؤهل العميل لإدارة عمليات نشر Vercel من FuzzyCat باستخدام Vercel CLI، وتقديم ميزات مثل تفتيش النشر ومشاهدة السجلات واسترجاع عناوين URL عبر إخراج JSON، باستخدام Python لتحليل البيانات واستخدام بروتوكولات مثل أوامر CLI."},"useCases":{"en":["Inspecting recent Vercel deployments","Retrieving latest deployment URLs","Debugging deployment issues with log viewing"],"zh":["检查最近的Vercel部署","检索最新的部署URL","使用日志查看进行部署问题调试"],"ja":["最近のVercelデプロイメントを検査する","最新のデプロイメントURLを取得する","ログの表示を使用してデプロイメントの問題をデバッグする"],"ko":["최근의 Vercel 배포를 검사하는 것","최신 배포 URL을 가져오는 것","로그 보기 기능을 사용하여 배포 이슈를 디버깅하는 것"],"es":["Inspeccionar despliegues recientes de Vercel","Recuperar las URLs de despliegue más recientes","Depurar problemas de despliegue con visualización de registros"],"fr":["Inspecter les déploiements Vercel récents","Récupérer les URL de déploiement les plus récentes","Déboguer les problèmes de déploiement avec la visualisation de journaux"],"de":["Aktuelle Vercel-Bereitstellungen untersuchen","Die neuesten Bereitstellungs-URLs abrufen","Bereitstellungsprobleme mit Protokollanzeige debuggen"],"pt":["Inspecionar implantações recentes do Vercel","Recuperar URLs de implantação mais recentes","Depurar problemas de implantação com visualização de logs"],"ru":["Осматривать最近ние развертывания Vercel","Получать последние URL-адреса развертывания","Отлаживать проблемы развертывания с помощью просмотра журналов"],"ar":["فحص عمليات نشر Vercel الأخيرة","استرجاع عناوين URL لأحدث عمليات النشر","تصحيح أخطاء النشر مع مشاهدة السجلات"]},"limitations":{"en":["Requires Vercel CLI installation at ~/.bun/bin/vercel","Needs prior authentication","Dependent on Python 3 for JSON data parsing"],"zh":["需要在~/.bun/bin/vercel安装Vercel CLI","需要事先认证","依赖Python 3进行JSON数据解析"],"ja":["~/.bun/bin/vercelにVercel CLIをインストールする必要がある","事前に認証する必要がある","JSONデータの解析にはPython 3に依存する"],"ko":["~/.bun/bin/vercel에 Vercel CLI를 설치해야 함","사전에 인증해야 함","JSON 데이터 파싱에는 Python 3에 의존"],"es":["Requiere la instalación de Vercel CLI en ~/.bun/bin/vercel","Necesita autenticación previa","Depende de Python 3 para el análisis de datos JSON"],"fr":["Nécessite l''installation de Vercel CLI en ~/.bun/bin/vercel","Nécessite une authentification préalable","Dépend de Python 3 pour l''analyse de données JSON"],"de":["Benötigt die Installation von Vercel CLI in ~/.bun/bin/vercel","Benötigt vorherige Authentifizierung","Hängt von Python 3 für die JSON-Datenanalyse ab"],"pt":["Requer instalação do Vercel CLI em ~/.bun/bin/vercel","Necessita de autenticação prévia","Depende do Python 3 para análise de dados JSON"],"ru":["Требует установки Vercel CLI в ~/.bun/bin/vercel","Требует предварительной аутентификации","Зависит от Python 3 для парсинга JSON-данных"],"ar":["يتطلب تثبيت Vercel CLI في ~/.bun/bin/vercel","يحتاج إلى مصادقة مسبقة","يعتمد على Python 3 لتحليل بيانات JSON"]},"version":4},"contentHash":"081242f4d557817cbcec0e7cd9ef0c407a9d653ba055ca5ba2c817e0d5b0f98e","qualityScore":60}');
