INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('svetzal/hopper/hopper-coordinator', 'hopper-coordinator', 'svetzal', 'hopper', 'community', 'hopper-coordinator svetzal hopper community The hopper-coordinator skill enables developers to dispatch concrete work items to a queue for autonomous execution by Claude Code agents. It provides a personal work dispatch system for substantive coding work. Hopper Coordinator 是一个个人工作队列 CLI，允许您将工作项分配给自动化的 Claude Code 工作代理。它支持自由形式的描述和 LLM 生成的标题 Hopper Coordinatorは、ワークアイテムを自動化されたClaude Codeワーカーエージェントに割り当てることができるパーソナルワークキューCLIです。自由形式の説明とLLM生成のタイトルをサポートしています Hopper Coordinator는 자동화된 Claude Code 작업 에이전트에 작업 항목을 할당할 수 있는 개인 작업 큐 CLI입니다. 자유 형식의 설명 및 LLM 생성 제목을 지원합니다 Hopper Coordinator es un sistema de cola de trabajo personal que permite administrar y ejecutar tareas de codificación de forma autónoma con la CLI. Hopper Coordinator est un système de file d''attente de travail personnel qui permet de gérer et d''exécuter des tâches de codage de manière autonome avec la CLI. Hopper Coordinator ist ein persönliches Work-Queue-System, das die Verwaltung und Ausführung von Codierungsaufgaben mit der CLI ermöglicht O Hopper Coordinator é uma ferramenta de fila de trabalho CLI que permite aos desenvolvedores criar e gerenciar tarefas de codificação de forma eficiente Hopper Coordinator - это инструмент личной очереди работы CLI, который позволяет разработчикам создавать и управлять задачами кодирования эффективно Hopper Coordinator هو أداة صف وظيفي CLI يسمح للمطورين إنشاء و إدارة مهام التشفير بفعالية how to use hopper-coordinator hopper-coordinator setup guide hopper-coordinator alternative hopper-coordinator vs claude code hopper-coordinator install autonomous work queue management cli work queue tools claude code agent integration Hopper Coordinator 自动化工作队列 CLI 工具 AI 工具 LLM 生成标题 自由形式描述 工作项分配 Claude Code 工作代理 Utilizes a CLI for work queue management Supports dispatching of concrete work items to autonomous Claude Code agents Enables unattended execution of work items in the background Provides a personal work dispatch system for substantive coding work Integrates with Claude Code worker agents for automated work execution hopper-coordinator is a personal work dispatch system using a CLI to queue work items for autonomous execution by background Claude Code worker agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('QuicksilverSlick/Metabolic-reset/team-reconcile', 'community', 'QuicksilverSlick', 'Metabolic-reset', 'QuicksilverSlick/Metabolic-reset', 'team-reconcile', 0, 0, 60, '2026-03-03T22:59:27Z', '2026-03-07T04:11:42.242Z', '4b54256f34aca6c86dbcac0c27f2d3b26abd5c862372093ac5215f6215310524', '{"id":"QuicksilverSlick/Metabolic-reset/team-reconcile","name":"team-reconcile","description":{"en":"The team-reconcile skill diagnoses and fixes team/roster issues for the 28-Day Metabolic Reset platform, benefiting users and facilitators. It reconciles team vs recruits index discrepancies.","zh":"团队重置工具帮助解决团队和招募索引不一致问题，确保用户出现在名单中。它通过诊断和修复团队索引问题来实现这一点","ja":"チームリコンシールツールはチームとリクルートのインデックスの不一致を解決し、ユーザーがリストに表示されることを保証する","ko":"팀 리콘실 툴은 팀과 모집 인덱스의 불일치를 해결하여 사용자가 명단에 표시되도록 합니다","es":"El agente team-reconcile diagnostica y soluciona problemas de equipo y roster para la plataforma de Reset Metabólico de 28 días","fr":"L''agent team-reconcile diagnostique et résout les problèmes d''équipe et de roster pour la plateforme de Reset Métabolique de 28 jours","de":"Der Team-Reconcile-Agent diagnostiziert und behebt Team- und Rosterprobleme für die Plattform für metabolischen Reset von 28 Tagen","pt":"O Team-Reconcile é uma ferramenta que diagnostica e corrige problemas de equipe na plataforma de Metabolic Reset, utilizando comandos CLI e processamento de entrada de usuário.","ru":"ИИ Агент Team-Reconcile - это инструмент, который диагностирует и исправляет проблемы с командой на платформе 28-Дневного Метаболического Перезапуска, используя команды CLI и обработку входных данных пользователя.","ar":"أداة الفريق-المصالح هي أداة تشخيص وعلاج مشاكل الفريق على منصة استعادة الأيض، باستخدام أوامر CLI ومعالجة إدخال المستخدم."},"seo":{"title":{"en":"team-reconcile: Troubleshooting Guide for 28-Day Metaboli...","zh":"团队重置工具：团队索引修复设置指南","ja":"チームリコンシ