INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eniosales08-AI/paraguay-shopping-search/prompt-engineering-patterns', 'prompt-engineering-patterns', 'eniosales08-AI', 'paraguay-shopping-search', 'community', 'prompt-engineering-patterns eniosales08-AI paraguay-shopping-search community The prompt-engineering-patterns skill enables developers to maximize LLM performance, reliability, and controllability. It benefits developers designing complex prompts for production LLM applications. prompt-engineering-patterns 技术用于设计复杂的 LLM 应用，优化性能和一致性，实现结构化推理 Prompt エンジニアリング パターン技術は、複雑な LLM アプリケーションを設計し、パフォーマンスと一貫性を最適化し、構造化された推論を実現するために使用されます prompt-engineering-patterns 기술은 복잡한 LLM 애플리케이션을 설계하고 성능 및 일관성을 최적화하고 구조화된 추론을 구현하는 데 사용됩니다 Los patrones de ingeniería de prompts permiten diseñar complejos prompts para aplicaciones de modelos de lenguaje de producción y optimizar su rendimiento Les modèles de prompts permettent de concevoir des prompts complexes pour les applications de modèles de langage de production et d''optimiser leurs performances Prompt-Engineering-Muster ermöglichen das Design komplexer Prompts für Produktionsanwendungen von Sprachmodellen und deren Leistungsoptimierung Padrões de engenharia de prompt para maximizar o desempenho de modelos de linguagem grandes Шаблоны инженерии запросов для максимизации производительности крупных языковых моделей أنماط هندسة الاستجابة لتعزيز أداء نماذج اللغة الكبيرة how to use prompt-engineering-patterns prompt-engineering-patterns tutorial LLM performance optimization prompt engineering techniques prompt-engineering-patterns alternative prompt-engineering-patterns vs traditional methods prompt-engineering-patterns setup guide prompt-engineering-patterns install mastering prompt engineering patterns prompt-engineering-patterns LLM 应用设计 性能优化 一致性优化 结构化推理 few-shot 学习 AI エージェント Designing complex prompts for production LLM applications Optimizing prompt performance and consistency Implementing structured reasoning patterns (chain-of-thought, tree-of-thought) Building few-shot learning systems with dynamic example selection Creating reusable prompt templates with variable interpolation Debugging prompt-related issues prompt-engineering-patterns is a set of advanced techniques for designing and optimizing prompts to improve the performance, reliability, and controllability of Large Language Models (LLMs).');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MinhNhut05/devteam-os/react-query-hook', 'community', 'MinhNhut05', 'devteam-os', 'MinhNhut05/devteam-os', 'react-query-hook', 0, 0, 60, '2026-03-04T16:16:29Z', '2026-03-07T04:15:33.882Z', '7e8ec1f470c3f51b79c04d4aca16c09f75d75050716fcce5c429bba0644118a6', '{"id":"MinhNhut05/devteam-os/react-query-hook","name":"react-query-hook","description":{"en":"The react-query-hook skill generates a custom hook using TanStack Query for data fetching, benefiting freelancers and startup teams. It creates a custom hook for managing project progress.","zh":"React Query Hook 是一个使用 TanStack Query 进行数据获取的自定义钩子","ja":"React Query Hook は TanStack Query を使用してデータを取得するためのカスタムフックです","ko":"React Query Hook는 TanStack Query를 사용하여 데이터를 가져오는 데 사용되는 사용자 정의 훅입니다","es":"React Query Hook es una herramienta para crear hooks personalizados con TanStack Query para la recuperación de datos en aplicaciones web","fr":"React Query Hook est un outil pour créer des hooks personnalisés avec TanStack Query pour la récupération de données dans les applications web","de":"React Query Hook ist ein Tool zum Erstellen benutzerdefinierter Hooks mit TanStack Query für die Datenabfrage in Webanwendungen","pt":"O react-query-hook permite criar hooks personalizados para busca de dados com TanStack Query.","ru":"Крючок react-query позволяет создавать кастомные хуки для получения данных с помощью TanStack Query.","ar":"يسمح Hook الخاص بالاستعلام التفاعلي بإنشاء كروكات مخصصة لاسترجاع البيانات باستخدام TanStack Query."},"seo":{"title":{"en":"react-query-hook: Custom Hook Setup Guide | AI Agent Skill","zh":"React Query Hook_SETUP GUIDE - 使用 TanStack Query 进行数据获取","ja":"React Query Hook_BEST PRACTICES - TanStack Query を使用したデータ取得","ko":"React Query Hook_SETUP GUIDE - TanStack Query를 사용한 데이터 가져오기","es":"Configuración de React Query Hook: Guía de inicio","fr":"Mise en 