INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MinhNhut05/devteam-os/react-query-hook', 'react-query-hook', 'MinhNhut05', 'devteam-os', 'community', 'react-query-hook MinhNhut05 devteam-os community The react-query-hook skill generates a custom hook using TanStack Query for data fetching, benefiting freelancers and startup teams. It creates a custom hook for managing project progress. React Query Hook 是一个使用 TanStack Query 进行数据获取的自定义钩子 React Query Hook は TanStack Query を使用してデータを取得するためのカスタムフックです React Query Hook는 TanStack Query를 사용하여 데이터를 가져오는 데 사용되는 사용자 정의 훅입니다 React Query Hook es una herramienta para crear hooks personalizados con TanStack Query para la recuperación de datos en aplicaciones web React Query Hook est un outil pour créer des hooks personnalisés avec TanStack Query pour la récupération de données dans les applications web React Query Hook ist ein Tool zum Erstellen benutzerdefinierter Hooks mit TanStack Query für die Datenabfrage in Webanwendungen O react-query-hook permite criar hooks personalizados para busca de dados com TanStack Query. Крючок react-query позволяет создавать кастомные хуки для получения данных с помощью TanStack Query. يسمح Hook الخاص بالاستعلام التفاعلي بإنشاء كروكات مخصصة لاسترجاع البيانات باستخدام TanStack Query. how to use react-query-hook react-query-hook setup guide react-query-hook vs TanStack Query react-query-hook install what is react-query-hook react-query-hook alternative react-query-hook for data fetching react-query-hook and Axios react-query-hook for web applications React Query Hook TanStack Query 数据获取 Axios 后端控制器 端点 URL AIエージェント JavaScript 钩子 Generates custom hooks using TanStack Query Supports pre-flight checks for Axios instance config Confirms backend controller endpoint URL and response type Follows Learning Mode guidelines from _templates/learning-mode.md Accepts hook name or API endpoint as arguments (e.g., useTasks, GET /projects/:id) react-query-hook is a custom React hook generator using TanStack Query for data fetching, designed for managing project progress in web applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('batFormat/sancrm-docs/aif-fix', 'community', 'batFormat', 'sancrm-docs', 'batFormat/sancrm-docs', 'aif-fix', 0, 0, 60, '2026-02-23T20:54:45Z', '2026-03-07T04:19:41.918Z', '1eb7bca83eb4dbeb86070e2fdb7f314da5b2ce2e0640a48e41d8af32203b1c28', '{"id":"batFormat/sancrm-docs/aif-fix","name":"aif-fix","description":{"en":"The aif-fix skill enables developers to fix specific bugs or problems in their codebase, supporting immediate fix or plan-first approaches. It benefits developers by automating the bug fixing workflow.","zh":"aif-fix 是一个支持即时修复和计划优先的 Bug Fix Workflow 工具，通过检查 FIX_PLAN.md 文件来执行修复","ja":"aif-fix は即時修正と計画優先のバグ修正ワークフローをサポートするツールで、FIX_PLAN.md ファイルを確認して修正を実行する","ko":"aif-fix는 즉시 修复과 계획 우선의 버그 수정 워크플로우를 지원하는 도구로 FIX_PLAN.md 파일을 확인하여 수정을 실행합니다","es":"aif-fix es una herramienta de reparación de errores de AI que admite dos modos: solución inmediata o enfoque planificado","fr":"aif-fix est un outil de correction de bogues d''IA qui prend en charge deux modes: correction immédiate ou approche planifiée","de":"aif-fix ist ein AI-Fehlerbehebungstool, das zwei Modi unterstützt: sofortige Lösung oder planbasierter Ansatz","pt":"O aif-fix é uma ferramenta de correção de bugs que suporta dois modos: correção imediata ou abordagem planejada. Ele verifica se existe um plano de correção existente antes de iniciar o processo.","ru":"ИИ Агент aif-fix - это инструмент для исправления ошибок, который поддерживает два режима: немедленное исправление или планируемый подход. Он проверяет наличие существующего плана исправления перед началом процесса.","ar":"وكيل إصلاح aif-fix هو أداة لتصحيح أخطاء الكود تدعم نمطين: الإصلاح الفوري أو النهج المخطط. يقوم بفحص وجود خطة إصلاح موجودة قبل البدء في العملية."},"seo":{"title":{"en":"aif-fix: Bug Fix Workflow Setup Guide | AI Agent Skill","zh":"aif-fix Setup Guide - AI 工具 Bug Fix Workflow","ja":"aif-fix の設定方法 - AIエージェントによるバグ修正ワークフロー","ko":"aif-fix 설정 가이드 - AI 에이전트 버그 수정 워크플로우","es":"Guía de configuración de aif-fix: Herramienta de reparaci...","fr":"Guide de configuration de aif-fix: Outil de correction de...","de":"Konfigurationsleitfaden für aif-fix: AI-Fehlerbehebungstool","pt":"Guia de Configuração do aif-fix: Corrigir Bugs de Código","ru":"ИИ Агенты: Настройка aif-fix для Исправления Ошибок","ar":"دليل إعداد aif-fix: إصلاح أخطاء الكود"},"description":{"en":"Streamline your bug fixing process with aif-fix. Discover how to execute fixes based on existing plans and investigate codebases efficiently. Get started now!","zh":"了解 aif-fix 的技术细节，包括 Bug Fix Workflow 和 FIX_PLAN.md 文件的使用方法，提高您的开发效率","ja":"aif-fix の技術的詳細を学び、バグ修正ワークフローと FIX_PLAN.md ファイルの使用方法をマスターして開発効率を向上させる","ko":"aif-fix의 기술적 세부 사항을 배우고 버그 수정 워크플로우 및 FIX_PLAN.md 파일의 사용 방법을 익혀 개발 효율성을 높이세요","es":"Aprende a configurar y utilizar aif-fix para solucionar problemas en tu código con nuestra guía paso a paso","fr":"Découvrez comment configurer et utiliser aif-fix pour résoudre les problèmes de votre code avec notre guide étape par étape","de":"Erfahren Sie, wie Sie aif-fix konfigurieren und verwenden können, um Probleme in Ihrem Code zu beheben, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o aif-fix para corrigir bugs de código de forma eficiente. Descubra como otimizar o fluxo de trabalho de correção de erros.","ru":"Узнайте, как настроить aif-fix для эффективного исправления ошибок кода. Откройте для себя, как оптимизировать процесс исправления ошибок.","ar":"تعلم كيفية تعيين aif-fix لتصحيح أخطاء الكود بفعالية. اكتشف كيفية تحسين تدفق العمل لتصحيح الأخطاء."},"definition":{"en":"aif-fix is a skill that automates the bug fixing workflow, supporting two modes and utilizing files like .ai-factory/FIX_PLAN.md to guide the fixing process.","zh":"aif-fix 是一种 AI 工具，用于自动化 Bug 修复过程，通过检查 FIX_PLAN.md 文件来确定修复计划","ja":"aif-fix はバグ修正プロセスを自動化する AI エージェントで、FIX_PLAN.md ファイルを確認して修正計画を決定する","ko":"aif-fix는 버그 수정 프로세스를 자동화하는 AI 에이전트로 FIX_PLAN.md 파일을 확인하여 수정 계획을 결정합니다","es":"aif-fix es una herramienta de AI que soluciona errores en el código mediante un flujo de trabajo de reparación","fr":"aif-fix est un outil d''IA qui résout les bogues dans le code via un flux de travail de correction","de":"aif-fix ist ein AI-Tool, das Fehler im Code durch einen Reparatur-Workflow behebt","pt":"O aif-fix é uma ferramenta de correção de bugs que automatiza o processo de correção de erros de código.","ru":"ИИ Агент aif-fix - это инструмент для автоматизации процесса исправления ошибок кода.","ar":"وكيل إصلاح aif-fix هو أداة لتحسين عملية تصحيح أخطاء الكود."},"features":{"en":["Checks for existing fix plans in .ai-factory/FIX_PLAN.md files","Executes fixes based on existing plans, skipping unnecessary steps","Supports immediate fix or plan-first approaches for flexible bug fixing","Investigates the codebase to identify and resolve bugs efficiently","Reads and informs users about existing fix plans for transparency"],"zh":["支持即时修复和计划优先的 Bug Fix Workflow","检查 FIX_PLAN.md 文件来确定修复计划","跳过不必要的步骤，直接执行修复","支持多种修复模式","提高开发效率和准确性"],"ja":["即時修正と計画優先のバグ修正ワークフローをサポート","FIX_PLAN.md ファイルを確認して修正計画を決定","不要なステップをスキップして直接修正を実行","複数の修正モードをサポート","開発効率と精度を向上させる"],"ko":["즉시 修复과 계획 우선의 버그 수정 워크플로우를 지원","FIX_PLAN.md 파일을 확인하여 수정 계획을 결정","불필요한 단계를 생략하고 직접 수정을 실행","複数의 수정 모드를 지원","개발 효율성과 정확성을 향상시킵니다"],"es":["Soporte para dos modos: solución inmediata o enfoque planificado","Verificación de la existencia de un plan de reparación en `.ai-factory/FIX_PLAN.md`","Ejecución de la reparación basada en el plan","Investigación del código para identificar y solucionar problemas","Compatibilidad con flujos de trabajo de reparación de errores de AI"],"fr":["Prise en charge de deux modes: correction immédiate ou approche planifiée","Vérification de l''existence d''un plan de correction dans `.ai-factory/FIX_PLAN.md`","Exécution de la correction basée sur le plan","Investigation du code pour identifier et résoudre les problèmes","Compatibilité avec les flux de travail de correction de bogues d''IA"],"de":["Unterstützung für zwei Modi: sofortige Lösung oder planbasierter Ansatz","Überprüfung der Existenz eines Reparaturplans in `.ai-factory/FIX_PLAN.md`","Ausführung der Reparatur basierend auf dem Plan","Untersuchung des Codes zur Identifizierung und Behebung von Fehlern","Kompatibilität mit AI-Fehlerbehebungs-Workflows"],"pt":["Suporte a dois modos: correção imediata ou abordagem planejada","Verificação de plano de correção existente antes de iniciar o processo","Leitura do arquivo .ai-factory/FIX_PLAN.md para execução do plano","Compatibilidade com fluxo de trabalho de correção de erros personalizado","Integração com tecnologias de desenvolvimento de software"],"ru":["Поддержка двух режимов: немедленное исправление или планируемый подход","Проверка наличия существующего плана исправления перед началом процесса","Чтение файла .ai-factory/FIX_PLAN.md для выполнения плана","Возможность настройки процесса исправления ошибок","Интеграция с технологиями разработки программного обеспечения"],"ar":["دعم نمطين: الإصلاح الفوري أو النهج المخطط","فحص وجود خطة إصلاح موجودة قبل البدء في العملية","قراءة ملف .ai-factory/FIX_PLAN.md لتنفيذ الخطة","توافق مع تدفق عمل تصحيح أخطاء مخصص","تكامل مع تكنولوجيا تطوير البرمجيات"]},"keywords":{"en":["how to use aif-fix","aif-fix setup guide","what is aif-fix","aif-fix alternative","aif-fix vs competing bug fixing tools","aif-fix install","bug fix workflow automation","codebase investigation techniques","existing fix plan execution"],"zh":["aif-fix","AI 工具","Bug Fix Workflow","FIX_PLAN.md","即时修复","计划优先","开发效率","自动化修复"],"ja":["aif-fix","AIエージェント","バグ修正ワークフロー","FIX_PLAN.md","即時修正","計画優先","開発効率","自動化修正"],"ko":["aif-fix","AI 에이전트","버그 수정 워크플로우","FIX_PLAN.md","즉시 修复","계획 우선","개발 효율성","자동화 修复"],"es":["herramientas de AI para desarrolladores","reparación de errores de AI","flujo de trabajo de reparación de errores","solución de problemas de código","configuración de aif-fix","guía de configuración de aif-fix"],"fr":["outils d''IA pour les développeurs","correction de bogues d''IA","flux de travail de correction de bogues","résolution de problèmes de code","configuration de aif-fix","guide de configuration de aif-fix"],"de":["AI-Tools für Entwickler","Fehlerbehebung von AI","Reparatur-Workflow","Fehlerbehebung im Code","Konfiguration von aif-fix","Konfigurationsleitfaden für aif-fix"],"pt":["aif-fix","correção de bugs","ferramenta de correção de erros","desenvolvimento de software","fluxo de trabalho de correção de erros","plano de correção","tecnologias de desenvolvimento de software"],"ru":["ИИ Агенты","ИИ Агент aif-fix","исправление ошибок","инструмент для исправления ошибок","разработка программного обеспечения","процесс исправления ошибок","план исправления","технологии разработки программного обеспечения"],"ar":["وكيل إصلاح","aif-fix","تصحيح أخطاء","أداة لتصحيح أخطاء","تطوير البرمجيات","تدفق عمل تصحيح أخطاء","خطة إصلاح","تكنولوجيا تطوير البرمجيات"]}},"owner":"batFormat","repo":"sancrm-docs","repoPath":"batFormat/sancrm-docs","stars":0,"forks":0,"updatedAt":"2026-02-23T20:54:45Z","topics":[],"category":"community","skillMd":{"name":"aif-fix","description":"Fix a specific bug or problem in the codebase. Supports two modes - immediate fix or plan-first. Without arguments executes existing FIX_PLAN.md. Always suggests test coverage and adds logging. Use when user says fix bug, debug this, something is broken, or pastes an error message.","bodyPreview":"# Fix - Bug Fix Workflow\n\nFix a specific bug or problem in the codebase. Supports two modes: immediate fix or plan-first approach.\n\n## Workflow\n\n### Step 0: Check for Existing Fix Plan\n\n**BEFORE anything else**, check if `.ai-factory/FIX_PLAN.md` exists.\n\n**If the file EXISTS:**\n- Read `.ai-factory/FIX_PLAN.md`\n- Inform the user: \"Found existing fix plan. Executing fix based on the plan.\"\n- **Skip Steps 0.1 through 1** — go directly to **Step 2: Investigate the Codebase**, using the plan as your","body":"# Fix - Bug Fix Workflow\n\nFix a specific bug or problem in the codebase. Supports two modes: immediate fix or plan-first approach.\n\n## Workflow\n\n### Step 0: Check for Existing Fix Plan\n\n**BEFORE anything else**, check if `.ai-factory/FIX_PLAN.md` exists.\n\n**If the file EXISTS:**\n- Read `.ai-factory/FIX_PLAN.md`\n- Inform the user: \"Found existing fix plan. Executing fix based on the plan.\"\n- **Skip Steps 0.1 through 1** — go directly to **Step 2: Investigate the Codebase**, using the plan as your guide\n- Follow each step of the plan sequentially\n- After the fix is fully applied and verified, **delete** `.ai-factory/FIX_PLAN.md`:\n  ```bash\n  rm .ai-factory/FIX_PLAN.md\n  ```\n- Continue to Step 4 (Verify), Step 5 (Test suggestion), Step 6 (Patch)\n\n**If the file DOES NOT exist AND `$ARGUMENTS` is empty:**\n- Tell the user: \"No fix plan found and no problem description provided. Please either provide a bug description (`/aif-fix <description>`) or create a fix plan first.\"\n- **STOP.**\n\n**If the file DOES NOT exist AND `$ARGUMENTS` is provided:**\n- Continue to Step 0.1 below.\n\n### Step 0.1: Load Project Context & Past Experience\n\n**Read `.ai-factory/DESCRIPTION.md`** if it exists to understand:\n- Tech stack (language, framework, database)\n- Project architecture\n- Coding conventions\n\n**Read all patches from `.ai-factory/patches/`** if the directory exists:\n- Use `Glob` to find all `*.md` files in `.ai-factory/patches/`\n- Read each patch file to learn from past fixes\n- Pay attention to recurring patterns, root causes, and solutions\n- If the current problem resembles a past patch — apply the same approach or avoid the same mistakes\n- This is your accumulated experience. Use it.\n\n### Step 1: Understand the Problem & Choose Mode\n\nFrom `$ARGUMENTS`, identify:\n- Error message or unexpected behavior\n- Where it occurs (file, function, endpoint)\n- Steps to reproduce (if provided)\n\nIf unclear, ask:\n```\nTo fix this effectively, I need more context:\n\n1. What is the expected behavior?\n2. What actually happens?\n3. Can you share the error message/stack trace?\n4. When did this start happening?\n```\n\n**After understanding the problem, ask the user to choose a mode using `AskUserQuestion`:**\n\nQuestion: \"How would you like to proceed with the fix?\"\n\nOptions:\n1. **Fix now** — Investigate and apply the fix immediately\n2. **Plan first** — Create a fix plan for review, then fix later\n\n**If user chooses \"Plan first\":**\n- Proceed to **Step 1.1: Create Fix Plan**\n\n**If user chooses \"Fix now\":**\n- Skip Step 1.1, proceed directly to **Step 2: Investigate the Codebase**\n\n### Step 1.1: Create Fix Plan\n\nInvestigate the codebase enough to understand the problem and create a plan.\n\n**Use the same parallel exploration approach as Step 2** — launch Explore agents to investigate the problem area, related code, and past patterns simultaneously.\n\nAfter agents return, synthesize findings to:\n1. Identify the root cause (or most likely candidates)\n2. Map affected files and functions\n3. Assess impact scope\n\nThen create `.ai-factory/FIX_PLAN.md` with this structure:\n\n```markdown\n# Fix Plan: [Brief title]\n\n**Problem:** [What''s broken — from user''s description]\n**Created:** YYYY-MM-DD HH:mm\n\n## Analysis\n\nWhat was found during investigation:\n- Root cause (or suspected root cause)\n- Affected files and functions\n- Impact scope\n\n## Fix Steps\n\nStep-by-step plan for implementing the fix:\n\n1. [ ] Step one — what to change and why\n2. [ ] Step two — ...\n3. [ ] Step three — ...\n\n## Files to Modify\n\n- `path/to/file.ts` — what changes are needed\n- `path/to/another.ts` — what changes are needed\n\n## Risks & Considerations\n\n- Potential side effects\n- Things to verify after the fix\n- Edge cases to watch for\n\n## Test Coverage\n\n- What tests should be added\n- What edge cases to cover\n```\n\n**After creating the plan, output:**\n\n```\n## Fix Plan Created ✅\n\nPlan saved to `.ai-factory/FIX_PLAN.md`.\n\nReview the plan and when you''re ready to execute, run:\n\n/aif-fix\n```\n\n**STOP here. Do NOT apply the fix.**\n\n### Step 2: Investigate the Codebase\n\n**Use `Task` tool with `subagent_type: Explore` to investigate the problem in parallel.** This keeps the main context clean and allows simultaneous investigation of multiple angles.\n\nLaunch 2-3 Explore agents simultaneously:\n\n```\nAgent 1 — Locate the problem area:\nTask(subagent_type: Explore, model: sonnet, prompt:\n  \"Find code related to [error location / affected functionality].\n   Read the relevant functions, trace the data flow.\n   Thoroughness: medium.\")\n\nAgent 2 — Related code & side effects:\nTask(subagent_type: Explore, model: sonnet, prompt:\n  \"Find all callers/consumers of [affected function/module].\n   Identify what else might break or be affected.\n   Thoroughness: medium.\")\n\nAgent 3 — Similar past patterns (if patches exist):\nTask(subagent_type: Explore, model: sonnet, prompt:\n  \"Search for similar error patterns or related fixes in the codebase.\n   Check git log for recent changes to [affected files].\n   Thoroughness: quick.\")\n```\n\n**After agents return, synthesize findings to identify:**\n- The root cause (not just symptoms)\n- Related code that might be affected\n- Existing error handling\n\n**Fallback:** If Task tool is unavailable, investigate directly:\n- Find relevant files using Glob/Grep\n- Read the code around the issue\n- Trace the data flow\n- Check for similar patterns elsewhere\n\n### Step 3: Implement the Fix\n\n**Apply the fix with logging:**\n\n```typescript\n// ✅ REQUIRED: Add logging around the fix\nconsole.log(''[FIX] Processing user input'', { userId, input });\n\ntry {\n  // The actual fix\n  const result = fixedLogic(input);\n  console.log(''[FIX] Success'', { userId, result });\n  return result;\n} catch (error) {\n  console.error(''[FIX] Error in fixedLogic'', {\n    userId,\n    input,\n    error: error.message,\n    stack: error.stack\n  });\n  throw error;\n}\n```\n\n**Logging is MANDATORY because:**\n- User needs to verify the fix works\n- If it doesn''t work, logs help debug further\n- Feedback loop: user provides logs → we iterate\n\n### Step 4: Verify the Fix\n\n- Check the code compiles/runs\n- Verify the logic is correct\n- Ensure no regressions introduced\n\n### Step 5: Suggest Test Coverage\n\n**ALWAYS suggest covering this case with a test:**\n\n```\n## Fix Applied ✅\n\nThe issue was: [brief explanation]\nFixed by: [what was changed]\n\n### Logging Added\nThe fix includes logging with prefix `[FIX]`.\nPlease test and share any logs if issues persist.\n\n### Recommended: Add a Test\n\nThis bug should be covered by a test to prevent regression:\n\n\\`\\`\\`typescript\ndescribe(''functionName'', () => {\n  it(''should handle [the edge case that caused the bug]'', () => {\n    // Arrange\n    const input = /* the problematic input */;\n\n    // Act\n    const result = functionName(input);\n\n    // Assert\n    expect(result).toBe(/* expected */);\n  });\n});\n\\`\\`\\`\n\nWould you like me to create this test?\n- [ ] Yes, create the test\n- [ ] No, skip for now\n```\n\n## Logging Requirements\n\n**All fixes MUST include logging:**\n\n1. **Log prefix**: Use `[FIX]` or `[FIX:<issue-id>]` for easy filtering\n2. **Log inputs**: What data was being processed\n3. **Log success**: Confirm the fix worked\n4. **Log errors**: Full context if something fails\n5. **Configurable**: Use LOG_LEVEL if available\n\n```typescript\n// Pattern for fixes\nconst LOG_FIX = process.env.LOG_LEVEL === ''debug'' || process.env.DEBUG_FIX;\n\nfunction fixedFunction(input) {\n  if (LOG_FIX) console.log(''[FIX] Input:'', input);\n\n  // ... fix logic ...\n\n  if (LOG_FIX) console.log(''[FIX] Output:'', result);\n  return result;\n}\n```\n\n## Examples\n\n### Example 1: Null Reference Error\n\n**User:** `/aif-fix TypeError: Cannot read property ''name'' of undefined in UserProfile`\n\n**Actions:**\n1. Search for UserProfile component/function\n2. Find where `.name` is accessed\n3. Add null check with logging\n4. Suggest test for null user case\n\n### Example 2: API Returns Wrong Data\n\n**User:** `/aif-fix /api/orders returns empty array for authenticated users`\n\n**Actions:**\n1. Find orders API endpoint\n2. Trace the query logic\n3. Find the bug (e.g., wrong filter)\n4. Fix with logging\n5. Suggest integration test\n\n### Example 3: Form Validation Not Working\n\n**User:** `/aif-fix email validation accepts invalid emails`\n\n**Actions:**\n1. Find email validation logic\n2. Check regex or validation library usage\n3. Fix the validation\n4. Add logging for validation failures\n5. Suggest unit test with edge cases\n\n## Important Rules\n\n1. **Check FIX_PLAN.md first** - Always check for existing plan before anything else\n2. **Plan mode = plan only** - When user chooses \"Plan first\", create the plan and STOP. Do NOT fix.\n3. **Execute mode = follow the plan** - When FIX_PLAN.md exists, follow it step by step, then delete it\n4. **NO reports** - Don''t create summary documents (patches are learning artifacts, not reports)\n5. **ALWAYS log** - Every fix must have logging for feedback\n6. **ALWAYS suggest tests** - Help prevent regressions\n7. **Root cause** - Fix the actual problem, not symptoms\n8. **Minimal changes** - Don''t refactor unrelated code\n9. **One fix at a time** - Don''t scope creep\n10. **Clean up** - Delete FIX_PLAN.md after successful fix execution\n\n## After Fixing\n\n```\n## Fix Applied ✅\n\n**Issue:** [what was broken]\n**Cause:** [why it was broken]\n**Fix:** [what was changed]\n\n**Files modified:**\n- path/to/file.ts (line X)\n\n**Logging added:** Yes, prefix `[FIX]`\n**Test suggested:** Yes\n\nPlease test the fix and share logs if any issues.\n\nTo add the suggested test:\n- [ ] Yes, create test\n- [ ] No, skip\n```\n\n### Step 6: Create Self-Improvement Patch\n\n**ALWAYS create a patch after every fix.** This builds a knowledge base for future fixes.\n\n**Create the patch:**\n\n1. Create directory if it doesn''t exist:\n   ```bash\n   mkdir -p .ai-factory/patches\n   ```\n\n2. Create a patch file with the current timestamp as filename.\n   **Format:** `YYYY-MM-DD-HH.mm.md` (e.g., `2026-02-07-14.30.md`)\n\n3. Use this template:\n\n```markdown\n# [Brief title describing the fix]\n\n**Date:** YYYY-MM-DD HH:mm\n**Files:** list of modified files\n**Severity:** low | medium | high | critical\n\n## Problem\n\nWhat was broken. How it manifested (error message, wrong behavior).\nBe specific — include the actual error or symptom.\n\n## Root Cause\n\nWHY the problem occurred. This is the most valuable part.\nNot \"what was wrong\" but \"why it was wrong\":\n- Logic error? Why was the logic incorrect?\n- Missing check? Why was it missing?\n- Wrong assumption? What was assumed?\n- Race condition? What sequence caused it?\n\n## Solution\n\nHow the fix was implemented. Key code changes and reasoning.\nInclude the approach, not just \"changed line X\".\n\n## Prevention\n\nHow to prevent this class of problems in the future:\n- What pattern/practice should be followed?\n- What should be checked during code review?\n- What test would catch this?\n\n## Tags\n\nSpace-separated tags for categorization, e.g.:\n`#null-check` `#async` `#validation` `#typescript` `#api` `#database`\n```\n\n**Example patch:**\n\n```markdown\n# Null reference in UserProfile when user has no avatar\n\n**Date:** 2026-02-07 14:30\n**Files:** src/components/UserProfile.tsx\n**Severity:** medium\n\n## Problem\n\nTypeError: Cannot read property ''url'' of undefined when rendering\nUserProfile for users without an uploaded avatar.\n\n## Root Cause\n\nThe `user.avatar` field is optional in the database schema but the\ncomponent accessed `user.avatar.url` without a null check. This was\nintroduced in commit abc123 when avatar display was added — the\ndeveloper tested only with users that had avatars.\n\n## Solution\n\nAdded optional chaining: `user.avatar?.url` with a fallback to a\ndefault avatar URL. Also added a null check in the Avatar sub-component.\n\n## Prevention\n\n- Always check if database fields marked as `nullable` / `optional`\n  are handled with null checks in the UI layer\n- Add test cases for \"empty state\" — user with minimal data\n- Consider a lint rule for accessing nested optional properties\n\n## Tags\n\n`#null-check` `#react` `#optional-field` `#typescript`\n```\n\n**This is NOT optional.** Every fix generates a patch. The patch is your learning.\n\n### Context Cleanup\n\nContext is heavy after investigation, fix, and patch generation. All results are saved — suggest freeing space:\n\n```\nAskUserQuestion: Free up context before continuing?\n\nOptions:\n1. /clear — Full reset (recommended)\n2. /compact — Compress history\n3. Continue as is\n```\n\n---\n\n**DO NOT:**\n- ❌ Apply a fix when user chose \"Plan first\" — only create FIX_PLAN.md and stop\n- ❌ Skip the FIX_PLAN.md check at the start\n- ❌ Leave FIX_PLAN.md after successful fix execution — always delete it\n- ❌ Generate reports or summaries (patches are NOT reports — they are learning artifacts)\n- ❌ Refactor unrelated code\n- ❌ Add features while fixing\n- ❌ Skip logging\n- ❌ Skip test suggestion\n- ❌ Skip patch creation\n"},"lastSynced":"2026-03-07T04:19:41.918Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing automated bug fixing workflows with immediate fix or plan-first approaches.","zh":"非常适合需要自动化 Bug 修复工作流的代码分析代理，支持立即修复或计划优先方法。","ja":"コード分析エージェントが自動化されたバグ修正ワークフローを必要とする場合に最適です。即時修正または計画優先アプローチに対応しています。","ko":"자동화된 버그 수정 워크플ロー가 필요한 코드 분석 에이전트에게 적합합니다. 즉시 수정 또는 계획 우선 접근 방식을 지원합니다.","es":"Perfecto para agentes de análisis de código que necesitan flujos de trabajo de corrección de errores automatizados con enfoques de corrección inmediata o planificación previa.","fr":"Parfait pour les agents d''analyse de code nécessitant des flux de travail de correction de bogue automatisés avec des approches de correction immédiate ou de planification préalable.","de":"Perfekt für Code-Analyse-Agents, die automatisierte Bug-Fixing-Workflows mit sofortigen Fix- oder Plan-erst-Ansätzen benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de fluxos de trabalho de correção de bugs automatizados com abordagens de correção imediata ou planejamento primeiro.","ru":"Идеально подходит для агентов анализа кода, которым необходимы автоматизированные рабочие процессы исправления ошибок с немедленным исправлением или подходами первого планирования.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى عمليات عمل تلقائية لتصحيح الأخطاء باستخدام نهج التصحيح الفوري أو التخطيط الأول."},"recommendation":{"en":"Empowers agents to automate bug fixing workflows by reading and executing fix plans from .ai-factory/FIX_PLAN.md files, supporting both immediate fix and plan-first methodologies using markdown files.","zh":"使代理能够通过读取和执行 .ai-factory/FIX_PLAN.md 文件中的修复计划来自动化 Bug 修复工作流，支持即时修复和计划优先方法，使用 Markdown 文件。","ja":"エージェントが.ai-factory/FIX_PLAN.mdファイルからの修正プランを読み込み実行することでバグ修正ワークフローを自動化できるようにします。即時修正と計画優先アプローチの両方をサポートし、Markdownファイルを使用しています。","ko":"에이전트가 .ai-factory/FIX_PLAN.md 파일의 수정 계획을 읽고 실행하여 버그 수정 워크플ロー를 자동화할 수 있도록 합니다. 즉시 수정과 계획 우선 접근 방식을 모두 지원하며, Markdown 파일을 사용합니다.","es":"Habilita a los agentes a automatizar flujos de trabajo de corrección de errores leyendo y ejecutando planes de corrección desde archivos .ai-factory/FIX_PLAN.md, compatibles con ambas metodologías de corrección inmediata y planificación previa utilizando archivos markdown.","fr":"Permet aux agents d''automatiser les flux de travail de correction de bogue en lisant et en exécutant des plans de correction à partir de fichiers .ai-factory/FIX_PLAN.md, prenant en charge à la fois les méthodologies de correction immédiate et de planification préalable en utilisant des fichiers markdown.","de":"Ermöglicht es Agents, Bug-Fixing-Workflows zu automatisieren, indem sie Korrekturpläne aus .ai-factory/FIX_PLAN.md-Dateien lesen und ausführen, und unterstützt sowohl Immediate-Fix- als auch Plan-erst-Ansätze unter Verwendung von Markdown-Dateien.","pt":"Habilita agentes a automatizar fluxos de trabalho de correção de bugs lendo e executando planos de correção de arquivos .ai-factory/FIX_PLAN.md, suportando tanto metodologias de correção imediata quanto de planejamento primeiro usando arquivos markdown.","ru":"Наделяет агентов возможностью автоматизировать рабочие процессы исправления ошибок, читая и выполняя планы исправления из файлов .ai-factory/FIX_PLAN.md, поддерживая как немедленное исправление, так и подходы первого планирования с использованием файлов markdown.","ar":"يتمتع الوكيل بتمكين عمليات عمل تلقائية لتصحيح الأخطاء من خلال قراءة وتنفيذ خطط التصحيح من ملفات .ai-factory/FIX_PLAN.md، ودعم كلا النهجين التصحيح الفوري والتخطيط الأول باستخدام ملفات markdown."},"useCases":{"en":["Automating bug fixes based on existing fix plans","Generating step-by-step fix workflows","Debugging codebases with plan-first approaches"],"zh":["根据现有的修复计划自动修复 Bug","生成逐步修复工作流","使用计划优先方法调试代码库"],"ja":["既存の修正プランに基づいてバグを自動修正する","逐步の修正ワークフローを生成する","計画優先アプローチでコードベースをデバッグする"],"ko":["기존의 수정 계획을 기반으로 자동으로 버그를 수정하는 것","逐步의 수정 워크플ロー 생성","계획 우선 접근 방식으로 코드베이스 디버깅"],"es":["Automatizar la corrección de errores en función de planes de corrección existentes","Generar flujos de trabajo de corrección paso a paso","Depurar bases de código con enfoques de planificación previa"],"fr":["Automatiser la correction de bogue en fonction de plans de correction existants","Générer des flux de travail de correction étape par étape","Déboguer des bases de code avec des approches de planification préalable"],"de":["Automatisieren von Fehlern basierend auf vorhandenen Korrekturplänen","Generieren von schrittweisen Korrektur-Workflows","Debuggen von Codebasen mit Plan-erst-Ansätzen"],"pt":["Automatizar a correção de bugs com base em planos de correção existentes","Gerar fluxos de trabalho de correção passo a passo","Depurar código com abordagens de planejamento primeiro"],"ru":["Автоматизировать исправление ошибок на основе существующих планов исправления","Генерировать пошаговые рабочие процессы исправления","Отлаживать код с помощью подходов первого планирования"],"ar":["التحكم التلقائي في تصحيح الأخطاء بالاعتماد على خطط تصحيح موجودة","توليد عمليات عمل تصحيح خطوة بخطوة","تصحيح الشفرة باستخدام نهج التخطيط الأول"]},"limitations":{"en":["Requires .ai-factory/FIX_PLAN.md file for plan-first approach","Limited to fixing bugs with existing plans or immediate fix capabilities"],"zh":["需要.ai-factory/FIX_PLAN.md文件来支持计划优先方法","仅限于具有现有计划或即时修复功能的 Bug 修复"],"ja":["計画優先アプローチをサポートするために.ai-factory/FIX_PLAN.mdファイルが必要","既存のプランまたは即時修正機能を持つバグのみを修正可能"],"ko":["계획 우선 접근 방식을 지원하기 위해 .ai-factory/FIX_PLAN.md 파일이 필요","기존 계획이나 즉시 수정 기능이 있는 버그만 수정 가능"],"es":["Requiere un archivo .ai-factory/FIX_PLAN.md para el enfoque de planificación previa","Limitado a la corrección de errores con planes existentes o capacidades de corrección inmediata"],"fr":["Nécessite un fichier .ai-factory/FIX_PLAN.md pour l''approche de planification préalable","Limité à la correction de bogue avec des plans existants ou des capacités de correction immédiate"],"de":["Benötigt eine .ai-factory/FIX_PLAN.md-Datei für den Plan-erst-Ansatz","Begrenzt auf das Korrigieren von Fehlern mit vorhandenen Plänen oder Immediate-Fix-Funktionen"],"pt":["Exige arquivo .ai-factory/FIX_PLAN.md para abordagem de planejamento primeiro","Limitado à correção de bugs com planos existentes ou capacidades de correção imediata"],"ru":["Требует файла .ai-factory/FIX_PLAN.md для подхода первого планирования","Ограничен исправлением ошибок с существующими планами или возможностями немедленного исправления"],"ar":["يتطلب ملف .ai-factory/FIX_PLAN.md لنهج التخطيط الأول","محدود بتصحيح الأخطاء ذات الخطط الموجودة أو القدرات التصحيحية الفورية"]},"version":4},"contentHash":"1eb7bca83eb4dbeb86070e2fdb7f314da5b2ce2e0640a48e41d8af32203b1c28","qualityScore":60}');
