INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('batFormat/sancrm-docs/aif-fix', 'aif-fix', 'batFormat', 'sancrm-docs', 'community', 'aif-fix batFormat sancrm-docs community The aif-fix skill enables developers to fix specific bugs or problems in their codebase, supporting immediate fix or plan-first approaches. It benefits developers by automating the bug fixing workflow. aif-fix 是一个支持即时修复和计划优先的 Bug Fix Workflow 工具，通过检查 FIX_PLAN.md 文件来执行修复 aif-fix は即時修正と計画優先のバグ修正ワークフローをサポートするツールで、FIX_PLAN.md ファイルを確認して修正を実行する aif-fix는 즉시 修复과 계획 우선의 버그 수정 워크플로우를 지원하는 도구로 FIX_PLAN.md 파일을 확인하여 수정을 실행합니다 aif-fix es una herramienta de reparación de errores de AI que admite dos modos: solución inmediata o enfoque planificado aif-fix est un outil de correction de bogues d''IA qui prend en charge deux modes: correction immédiate ou approche planifiée aif-fix ist ein AI-Fehlerbehebungstool, das zwei Modi unterstützt: sofortige Lösung oder planbasierter Ansatz O aif-fix é uma ferramenta de correção de bugs que suporta dois modos: correção imediata ou abordagem planejada. Ele verifica se existe um plano de correção existente antes de iniciar o processo. ИИ Агент aif-fix - это инструмент для исправления ошибок, который поддерживает два режима: немедленное исправление или планируемый подход. Он проверяет наличие существующего плана исправления перед началом процесса. وكيل إصلاح aif-fix هو أداة لتصحيح أخطاء الكود تدعم نمطين: الإصلاح الفوري أو النهج المخطط. يقوم بفحص وجود خطة إصلاح موجودة قبل البدء في العملية. how to use aif-fix aif-fix setup guide what is aif-fix aif-fix alternative aif-fix vs competing bug fixing tools aif-fix install bug fix workflow automation codebase investigation techniques existing fix plan execution aif-fix AI 工具 Bug Fix Workflow FIX_PLAN.md 即时修复 计划优先 开发效率 自动化修复 Checks for existing fix plans in .ai-factory/FIX_PLAN.md files Executes fixes based on existing plans, skipping unnecessary steps Supports immediate fix or plan-first approaches for flexible bug fixing Investigates the codebase to identify and resolve bugs efficiently Reads and informs users about existing fix plans for transparency aif-fix is a skill that automates the bug fixing workflow, supporting two modes and utilizing files like .ai-factory/FIX_PLAN.md to guide the fixing process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rnwolfe/forge/sweep-issues', 'community', 'rnwolfe', 'forge', 'rnwolfe/forge', 'sweep-issues', 0, 0, 60, '2026-03-01T17:51:36Z', '2026-03-07T13:13:32.874Z', '115103cd4a1e1f7d20f4a55ed6d3a12c5274365d28daab20e27d7671f62bb415', '{"id":"rnwolfe/forge/sweep-issues","name":"sweep-issues","description":{"en":"The sweep-issues skill bootstraps any project with a full autonomous development lifecycle, helping disciplined issue triagers evaluate open issues and prioritize refinement. It benefits development teams seeking to streamline their workflow.","zh":"Sweep Issues是一种AIエージェント，能够自动化开发生命周期，优化项目质量和效率","ja":"Sweep Issuesは、プロジェクトを自動化し、品質と効率を向上させるAIエージェントです","ko":"Sweep Issues는 프로젝트 자동화 개발 생명주기를 개선하고 효율성을 높이는 AI 에이전트입니다","es":"Sweep-issues es una herramienta que permite automatizar el ciclo de vida de desarrollo de proyectos, evaluando problemas abiertos contra una lista de verificación de calidad","fr":"Sweep-issues est un outil qui permet d''automatiser le cycle de vie de développement de projets, en évaluant les problèmes ouverts contre une liste de vérification de qualité","de":"Sweep-issues ist ein Tool, das die Automatisierung des Entwicklungslebenszyklus von Projekten ermöglicht, indem es offene Probleme gegen eine Qualitätsprüfliste überprüft","pt":"O Sweep Issues é uma ferramenta que ajuda a garantir a qualidade do backlog de projetos, realizando uma auditoria de qualidade de issues e identificando aquelas que precisam de refinamento.","ru":"Sweep Issues — это инструмент, который помогает обеспечить качество бэклога проектов, проводя аудит качества задач и выявляя те, которые требуют доработки.","ar":"Sweep Issues هو أداة تساعد على ضمان جودة قائمة انتظار المشاريع، من خلال إجراء تدقيق جودة للمسائل وتحديد تلك التي تحتاج إلى تحسين."},"seo":{"title":{"en":"sweep-issues: Autonomous Development Lifecycle Setup Gui