INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('oriolrius/nifi-cluster/GitHub CLI', 'GitHub CLI', 'oriolrius', 'nifi-cluster', 'community', 'GitHub CLI oriolrius nifi-cluster community The GitHub CLI skill provides expert guidance for GitHub CLI operations and workflows, benefiting developers who want to automate tasks and improve their development workflow. GitHub CLI是GitHub的命令行界面，提供了安装、设置、PR创建等功能 GitHub CLIは、GitHubのコマンドラインインターフェースで、インストール、設定、PR作成などの機能を提供します GitHub CLI는 GitHub의 명령줄 인터페이스로, 설치, 설정, PR 생성 등 다양한 기능을 제공합니다 GitHub CLI es una herramienta de línea de comandos para interactuar con GitHub. Permite la autenticación y la creación de solicitudes de extracción GitHub CLI est un outil de ligne de commande pour interagir avec GitHub. Il permet l''authentification et la création de demandes d''extraction GitHub CLI ist ein Kommandozeilen-Tool, um mit GitHub zu interagieren. Es ermöglicht die Authentifizierung und die Erstellung von Pull-Requests O GitHub CLI é uma ferramenta de linha de comando para interagir com o GitHub. Ele permite criar e gerenciar pull requests, configuração de autenticação e muito mais. GitHub CLI — это инструмент командной строки для взаимодействия с GitHub. Он позволяет создавать и управлять запросами на включение, настраивать аутентификацию и многое другое. GitHub CLI هو أداة سطر الأوامر للتفاعل مع GitHub. يسمح بإنشاء وإدارة الطلبات السحابية، وإعداد التحقق والكثير غير ذلك. how to use GitHub CLI GitHub CLI setup guide GitHub CLI alternative GitHub CLI vs Git what is GitHub CLI GitHub CLI install GitHub CLI automation GitHub CLI workflow GitHub CLI tutorial GitHub CLI AIエージェント工具 GitHub开发 命令行界面 PR创建 git配置 TLS/SSL Mermaid文档 Automated provisioning with TLS/SSL Comprehensive testing with 31 validations and 32 tests Visual Mermaid documentation for clarity Interactive PR creation with gh pr create Configurable git setup with gh auth setup-git Unified CLI for streamlined workflows GitHub CLI is a production-ready multi-cluster Apache NiFi platform with unified CLI, automated provisioning, and Site-to-Site communication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('soliblue/cloude/video', 'community', 'soliblue', 'cloude', 'soliblue/cloude', 'video', 0, 0, 60, '2026-03-06T10:34:05Z', '2026-03-07T13:14:34.267Z', '8454d7190c5dd5adb7c025ea04950808aa1cbdacce5edb01f8a7f69353d2e596', '{"id":"soliblue/cloude/video","name":"video","description":{"en":"The video skill allows developers to control Claude Code from their phone using an iOS app and macOS agent over Tailscale. It utilizes fal.ai and Sora providers for video generation.","zh":"视频生成技能允许您控制Claude Code，使用fal.ai和Sora提供商，支持iOS和macOS集成","ja":"ビデオ生成スキルを使用すると、fal.aiとSoraプロバイダーを使用してClaude Codeを制御できます。iOSおよびmacOS統合が可能です","ko":"비디오 생성 스킬을 사용하면 fal.ai와 Sora 제공업체를 사용하여 Claude Code를 제어할 수 있습니다. iOS 및 macOS 통합 지원","es":"El skill de video permite generar contenido de video con proveedores como fal.ai y Sora, utilizando tecnologías como Tailscale y SwiftUI.","fr":"Le skill vidéo permet de générer du contenu vidéo avec des fournisseurs tels que fal.ai et Sora, en utilisant des technologies comme Tailscale et SwiftUI.","de":"Das Video-Skill ermöglicht die Generierung von Videoinhalten mit Anbietern wie fal.ai und Sora, unter Verwendung von Technologien wie Tailscale und SwiftUI.","pt":"O skill de vídeo permite controlar o Claude Code do seu telefone com o aplicativo iOS e agente macOS sobre Tailscale. Suporta dois provedores: fal.ai e Sora.","ru":"Сkill видео позволяет контролировать Claude Code с вашего телефона с помощью приложения iOS и агента macOS через Tailscale. Поддерживает два провайдера: fal.ai и Sora.","ar":"مهمة الفيديو تسمح بالتحكم في Claude Code من هاتفك باستخدام تطبيق iOS ووكيل macOS عبر Tailscale. تدعم مزودين: fal.ai و Sora."},"seo":{"title":{"en":"Video: Tailscale-Powered AI Agent Skill for iOS and macOS...","zh":"视频生成技能设置指南","ja":"ビデオ生成スキルセットアップガイド","ko":"비디오 생성 스킬 설정 가이드","es":"Guía de configuración de video con C