INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('soliblue/cloude/video', 'video', 'soliblue', 'cloude', 'community', 'video soliblue cloude community ai-agent anthropic claude claude-code ios macos swiftui The video skill allows developers to control Claude Code from their phone using an iOS app and macOS agent over Tailscale. It utilizes fal.ai and Sora providers for video generation. 视频生成技能允许您控制Claude Code，使用fal.ai和Sora提供商，支持iOS和macOS集成 ビデオ生成スキルを使用すると、fal.aiとSoraプロバイダーを使用してClaude Codeを制御できます。iOSおよびmacOS統合が可能です 비디오 생성 스킬을 사용하면 fal.ai와 Sora 제공업체를 사용하여 Claude Code를 제어할 수 있습니다. iOS 및 macOS 통합 지원 El skill de video permite generar contenido de video con proveedores como fal.ai y Sora, utilizando tecnologías como Tailscale y SwiftUI. Le skill vidéo permet de générer du contenu vidéo avec des fournisseurs tels que fal.ai et Sora, en utilisant des technologies comme Tailscale et SwiftUI. Das Video-Skill ermöglicht die Generierung von Videoinhalten mit Anbietern wie fal.ai und Sora, unter Verwendung von Technologien wie Tailscale und SwiftUI. O skill de vídeo permite controlar o Claude Code do seu telefone com o aplicativo iOS e agente macOS sobre Tailscale. Suporta dois provedores: fal.ai e Sora. Сkill видео позволяет контролировать Claude Code с вашего телефона с помощью приложения iOS и агента macOS через Tailscale. Поддерживает два провайдера: fal.ai и Sora. مهمة الفيديو تسمح بالتحكم في Claude Code من هاتفك باستخدام تطبيق iOS ووكيل macOS عبر Tailscale. تدعم مزودين: fal.ai و Sora. how to use video AI agent skill video AI agent setup guide Tailscale-powered AI agents SwiftUI AI agent development fal.ai video generation Sora provider alternative video AI agent vs Playwright install video AI agent video AI agent for iOS and macOS 视频生成技能 AI代理 fal.ai Sora Claude Code iOS开发 macOS开发 SwiftUI 视频生成工具 Utilizes fal.ai and Sora providers for video generation Supports Tailscale for secure networking Features default provider fal.ai with a $5/day budget Allows for explicit requests to use Sora provider Requires user confirmation before generating video content Includes a --budget command to check budget status Video is a Tailscale-powered AI agent skill for controlling Claude Code from iOS and macOS devices using SwiftUI.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cbemister/claude-code-utils/mobile-accessibility', 'community', 'cbemister', 'claude-code-utils', 'cbemister/claude-code-utils', 'mobile-accessibility', 0, 0, 60, '2026-03-07T12:46:33.451Z', '2026-03-07T12:54:29.316Z', 'eb025b3c4e0f417baba5fca0bae8ce31fe260365dc68689a845129748394f04f', '{"id":"cbemister/claude-code-utils/mobile-accessibility","name":"mobile-accessibility","description":{"en":"The mobile-accessibility skill provides a comprehensive mobile accessibility audit and implementation for VoiceOver, TalkBack, and touch-based screen reader navigation, benefiting developers and users alike.","zh":"移动无障碍技能提供了综合的移动界面审计和无障碍问题修复，支持VoiceOver和TalkBack","ja":"モバイルアクセシビリティスキルは、モバイルインターフェースの包括的なオーディットとアクセシビリティ問題の修復を提供し、VoiceOverとTalkBackをサポート","ko":"모바일 접근성 기능은 모바일 인터페이스의 종합적인 감지와 접근성 문제의 수정을 제공하며 VoiceOver와 TalkBack를 지원","es":"La accesibilidad móvil es fundamental para desarrolladores. Aprende a auditar y mejorar la accesibilidad en tus aplicaciones móviles","fr":"L''accessibilité mobile est essentielle pour les développeurs. Découvrez comment auditer et améliorer l''accessibilité de vos applications mobiles","de":"Die mobile Accessibility ist für Entwickler von entscheidender Bedeutung. Erfahren Sie, wie Sie die Accessibility in Ihren mobilen Anwendungen überprüfen und verbessern","pt":"A acessibilidade móvel é fundamental para garantir que os aplicativos sejam utilizáveis por todos. Nossa ferramenta de IA ajuda a auditar e implementar soluções de acessibilidade móvel.","ru":"Мобильная доступность необходима для того, чтобы приложения были доступны всем. Наш ИИ Агент помогает проводить аудит и реализовывать решения по мобильной доступности.","ar":"إمكانية الوصول المتنقلة ضرورية لضمان أن تكون التطبيقات قابلة للاستخدام من قبل الجميع. أداة الذكاء الاصطناعي لدينا تساعد في إجراء аудيتات وتنفيذ حلول إمكانية الوصول المتنقلة."},"seo":{"title":{"en":"Mobile-Accessibility: Comprehensive Audit and Implementat...","zh":"移动无障碍设置指南 - 实现VoiceOver和TalkBack支持","ja":"モバイルアクセシビリティセットアップガイド - VoiceOverとTalkBackのサポート","ko":"모바일 접근성 설정 가이드 - VoiceOver와 TalkBack 지원","es":"Guía de configuración de accesibilidad móvil para desarro...","fr":"Guide de configuration de l''accessibilité mobile pour les...","de":"Einrichtungsleitfaden für mobile Accessibility-Tools","pt":"Guia de Configuração de Acessibilidade Móvel para Ferrame...","ru":"Настройка мобильной доступности для ИИ Агентов","ar":"دليل إعداد إمكانية الوصول المتنقلة لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock mobile accessibility with our AI agent skill, featuring VoiceOver, TalkBack, and WCAG 2.1 compliance. Get started with our setup guide and ensure incl...","zh":"使用AIエージェント的移动无障碍技能，审计和修复移动界面的无障碍问题，支持VoiceOver和TalkBack","ja":"AIエージェントのモバイルアクセシビリティスキルを使用して、モバイルインターフェースのアクセシビリティ問題を診断して修復し、VoiceOverとTalkBackをサポート","ko":"AI 도구의 모바일 접근성 기능을 사용하여 모바일 인터페이스의 접근성 문제를 감지하고 수정하고 VoiceOver와 TalkBack를 지원","es":"Aprende a implementar la accesibilidad móvil en tus aplicaciones con VoiceOver, TalkBack y navegación por pantalla táctil","fr":"Découvrez comment mettre en œuvre l''accessibilité mobile dans vos applications avec VoiceOver, TalkBack et navigation tactile","de":"Erfahren Sie, wie Sie die mobile Accessibility in Ihren Anwendungen mit VoiceOver, TalkBack und Touchscreen-Navigation umsetzen","pt":"Aprenda a implementar auditorias e soluções de acessibilidade móvel para VoiceOver, TalkBack e navegação por leitor de tela","ru":"Узнайте, как реализовать мобильную доступность для VoiceOver, TalkBack и навигации с помощью экранного читателя","ar":"تعلم كيفية تنفيذ аудيتات و حلول إمكانية الوصول المتنقلة لبرامج VoiceOver و TalkBack و التصفح باللمس"},"definition":{"en":"Mobile-accessibility is a set of technologies and techniques ensuring that mobile interfaces are usable by everyone, including those with disabilities, through support for VoiceOver, TalkBack, and WCAG 2.1 guidelines.","zh":"移动无障碍是指使移动应用和网站对残障人士可访问的过程，包括支持VoiceOver和TalkBack","ja":"モバイルアクセシビリティとは、モバイルアプリとウェブサイトを障害者のために利用可能にするプロセスであり、VoiceOverとTalkBackのサポートを含む","ko":"모바일 접근성은 모바일 애플리케이션과 웹사이트를 장애인에게 접근할 수 있도록 하는 과정으로 VoiceOver와 TalkBack의 지원을 포함","es":"La accesibilidad móvil se refiere a la capacidad de las aplicaciones móviles para ser utilizadas por personas con discapacidades","fr":"L''accessibilité mobile fait référence à la capacité des applications mobiles à être utilisées par des personnes ayant des besoins spécifiques","de":"Die mobile Accessibility bezieht sich auf die Fähigkeit von mobilen Anwendungen, von Menschen mit Behinderungen genutzt zu werden","pt":"Acessibilidade móvel refere-se à capacidade de um aplicativo ser utilizado por pessoas com deficiência, utilizando tecnologias como VoiceOver e TalkBack","ru":"Мобильная доступность означает способность приложения быть использованным людьми с ограниченными возможностями, используя технологии như VoiceOver и TalkBack","ar":"إمكانية الوصول المتنقلة تعني قدرة التطبيق على أن يتم استخدامه من قبل الأشخاص ذوي الإعاقة، باستخدام تقنيات مثل برامج VoiceOver و TalkBack"},"features":{"en":["Audits mobile interfaces for accessibility issues using VoiceOver and TalkBack","Implements focus management in modals and bottom sheets for improved navigation","Adds screen reader announcements for dynamic content","Ensures touch targets meet WCAG 2.1 mobile criteria","Supports switch access for users with motor disabilities"],"zh":["支持VoiceOver（iOS）和TalkBack（Android）","修复焦点管理在模态窗口和底部表单中","添加屏幕阅读器公告用于动态内容","确保触摸目标符合WCAG 2.1移动标准","支持开关控制"],"ja":["VoiceOver（iOS）とTalkBack（Android）のサポート","モーダルウィンドウとボトムシートのフォーカス管理の修復","動的コンテンツのためのスクリーンリーダー発表の追加","タッチターゲットのWCAG 2.1モバイル基準の遵守","スイッチコントロールのサポート"],"ko":["VoiceOver（iOS）와 TalkBack（Android）的 지원","모달 창과 하단 시트의 포커스 관리 수정","동적 콘텐츠를 위한 스크린 리더 발표 추가","터치 대상의 WCAG 2.1 모바일 기준 준수","스위치 제어 지원"],"es":["Soporte para VoiceOver (iOS) y TalkBack (Android)","Navegación por pantalla táctil para personas con discapacidades","Auditoría de la interfaz móvil para detectar problemas de accesibilidad","Gestión de enfoque en modales y hojas inferiores","Anuncios de pantalla de contenido dinámico para lectores de pantalla"],"fr":["Prise en charge de VoiceOver (iOS) et TalkBack (Android)","Navigation tactile pour les personnes ayant des besoins spécifiques","Audit de l''interface mobile pour détecter les problèmes d''accessibilité","Gestion de la mise au point dans les modales et les feuilles inférieures","Annonces d''écran de contenu dynamique pour les lecteurs d''écran"],"de":["Unterstützung für VoiceOver (iOS) und TalkBack (Android)","Touchscreen-Navigation für Menschen mit Behinderungen","Überprüfung der mobilen Oberfläche auf Accessibility-Probleme","Fokusverwaltung in Modals und Bottom Sheets","Bildschirmansagen für dynamischen Inhalt für Screenreader"],"pt":["Auditoria de interface móvel para problemas de acessibilidade","Implementação de suporte a VoiceOver e TalkBack","Gestão de foco em modais e folhas inferiores","Adicionando anúncios de leitor de tela para conteúdo dinâmico","Garantindo que os alvos de toque atendam aos critérios móveis da WCAG 2.1","Suporte a comutação para facilitar a navegação"],"ru":["Аудит мобильного интерфейса для проблем доступности","Реализация поддержки VoiceOver и TalkBack","Управление фокусом в модальных окнах и нижних листах","Добавление объявлений экранного читателя для динамического контента","Обеспечение того, чтобы цели касания соответствовали мобильным критериям WCAG 2.1","Поддержка переключения для облегчения навигации"],"ar":["أداء аудيت لواجهة المستخدم المتنقلة لتحديد مشاكل إمكانية الوصول","تنفيذ دعم لبرامج VoiceOver و TalkBack","إدارة التركيز في النوافذ المتحركة و الأوراق السفلية","إضافة إعلانات برنامج القارئ الشاشي لل내용 الديناميكي","ضمان توافق أهداف اللمس مع معايير الويب المتنقلة WCAG 2.1","دعم التبديل لتسهيل التنقل"]},"keywords":{"en":["how to use mobile-accessibility","mobile-accessibility setup guide","what is mobile-accessibility","mobile-accessibility vs accessibility guidelines","mobile-accessibility install for iOS and Android","mobile-accessibility best practices for developers"],"zh":["移动无障碍","AIエージェント","VoiceOver","TalkBack","WCAG 2.1","移动应用开发","无障碍设计","屏幕阅读器","触摸目标"],"ja":["モバイルアクセシビリティ","AIエージェント","VoiceOver","TalkBack","WCAG 2.1","モバイルアプリ開発","アクセシビリティ設計","スクリーンリーダー","タッチターゲット"],"ko":["모바일 접근성","AI 도구","VoiceOver","TalkBack","WCAG 2.1","모바일 애플리케이션 개발","접근성 디자인","스크린 리더","터치 대상"],"es":["accesibilidad móvil","desarrollo de aplicaciones móviles","VoiceOver","TalkBack","navegación por pantalla táctil","auditoría de accesibilidad","WCAG 2.1","desarrollo de aplicaciones accesibles"],"fr":["accessibilité mobile","développement d''applications mobiles","VoiceOver","TalkBack","navigation tactile","audit d''accessibilité","WCAG 2.1","développement d''applications accessibles"],"de":["mobile Accessibility","Entwicklung von mobilen Anwendungen","VoiceOver","TalkBack","Touchscreen-Navigation","Accessibility-Audit","WCAG 2.1","Entwicklung von zugänglichen Anwendungen"],"pt":["acessibilidade móvel","auditoria de acessibilidade","implementação de VoiceOver","suporte a TalkBack","navegação por leitor de tela","WCAG 2.1","desenvolvimento de aplicativos acessíveis","ferramentas de IA para acessibilidade"],"ru":["мобильная доступность","аудит доступности","реализация VoiceOver","поддержка TalkBack","навигация с помощью экранного читателя","WCAG 2.1","разработка доступных приложений","инструменты ИИ для доступности"],"ar":["إمكانية الوصول المتنقلة","أداء аудيت لإمكانية الوصول","تنفيذ دعم لبرامج VoiceOver","دعم برنامج TalkBack","التنقل باستخدام برنامج القارئ الشاشي","معايير الويب المتنقلة WCAG 2.1","تنمية تطبيقات قابلة للاستخدام","أدوات الذكاء الاصطناعي لإمكانية الوصول"]}},"owner":"cbemister","repo":"claude-code-utils","repoPath":"cbemister/claude-code-utils","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.451Z","topics":[],"category":"community","skillMd":{"name":"mobile-accessibility","description":"Ensure mobile interfaces work with VoiceOver, TalkBack, and screen readers. Audits touch target sizes, focus management, and WCAG 2.1 mobile criteria.","bodyPreview":"# Mobile Accessibility Skill\n\nComprehensive mobile accessibility audit and implementation for VoiceOver (iOS), TalkBack (Android), and touch-based screen reader navigation.\n\n## When to Use\n\nUse `/mobile-accessibility` when you need to:\n- Audit mobile interface for accessibility issues\n- Implement VoiceOver/TalkBack support\n- Fix focus management in modals and bottom sheets\n- Add screen reader announcements for dynamic content\n- Ensure touch targets meet WCAG 2.1 mobile criteria\n- Support switch","body":"# Mobile Accessibility Skill\n\nComprehensive mobile accessibility audit and implementation for VoiceOver (iOS), TalkBack (Android), and touch-based screen reader navigation.\n\n## When to Use\n\nUse `/mobile-accessibility` when you need to:\n- Audit mobile interface for accessibility issues\n- Implement VoiceOver/TalkBack support\n- Fix focus management in modals and bottom sheets\n- Add screen reader announcements for dynamic content\n- Ensure touch targets meet WCAG 2.1 mobile criteria\n- Support switch control and alternative input methods\n\n## Instructions\n\n### Phase 1: Mobile Accessibility Audit\n\n**Goal**: Identify mobile-specific accessibility issues\n\n**WCAG 2.1 Mobile Criteria:**\n\n| Criterion | Level | Requirement |\n|-----------|-------|-------------|\n| **2.5.5 Target Size** | AAA | 44x44 CSS pixels minimum |\n| **2.5.1 Pointer Gestures** | A | Multi-point/path-based gestures have single-point alternative |\n| **2.5.2 Pointer Cancellation** | A | Completion on up-event, can abort |\n| **2.5.3 Label in Name** | A | Accessible name contains visible text |\n| **2.5.4 Motion Actuation** | A | Motion-triggered functions can be disabled |\n| **1.3.4 Orientation** | AA | Content works in portrait and landscape |\n| **1.4.10 Reflow** | AA | Content reflows to 320px without horizontal scroll |\n\n**I will:**\n1. Check all interactive element sizes (44x44px minimum)\n2. Verify screen reader labels are present and descriptive\n3. Test focus order and keyboard navigation\n4. Audit ARIA landmarks and roles\n5. Check color contrast ratios (4.5:1 for normal text)\n6. Verify form inputs have associated labels\n7. Check that dynamic content announces to screen readers\n\n**Audit bash commands:**\n\n```bash\n# Find small touch targets\ngrep -rn \"width:\\s*[0-3][0-9]px\\|height:\\s*[0-3][0-9]px\" --include=\"*.css\" src/\n\n# Find images without alt text\ngrep -rn \"<img\" --include=\"*.tsx\" --include=\"*.jsx\" src/ | grep -v \"alt=\"\n\n# Find buttons without accessible labels\ngrep -rn \"<button\" --include=\"*.tsx\" src/ | grep -v \"aria-label\\|>.*</\"\n\n# Find inputs without labels\ngrep -rn \"<input\" --include=\"*.tsx\" src/ | grep -v \"aria-label\\|id=\"\n```\n\n---\n\n### Phase 2: Screen Reader Support\n\n**Goal**: Ensure VoiceOver and TalkBack can navigate and understand content\n\n**ARIA Landmarks for Mobile:**\n\n```html\n<!-- Header with navigation -->\n<header role=\"banner\">\n  <nav role=\"navigation\" aria-label=\"Main navigation\">\n    <!-- Nav items -->\n  </nav>\n</header>\n\n<!-- Main content -->\n<main role=\"main\">\n  <h1>Page Title</h1>\n  <!-- Content -->\n</main>\n\n<!-- Search -->\n<div role=\"search\">\n  <label for=\"search\">Search</label>\n  <input type=\"search\" id=\"search\" />\n</div>\n\n<!-- Footer -->\n<footer role=\"contentinfo\">\n  <!-- Footer content -->\n</footer>\n```\n\n**Button Accessibility:**\n\n```html\n<!-- ❌ Bad - no label for icon-only button -->\n<button>\n  <svg><!-- icon --></svg>\n</button>\n\n<!-- ✅ Good - aria-label for screen readers -->\n<button aria-label=\"Close dialog\">\n  <svg aria-hidden=\"true\"><!-- icon --></svg>\n</button>\n\n<!-- ✅ Good - visually hidden text -->\n<button>\n  <svg aria-hidden=\"true\"><!-- icon --></svg>\n  <span class=\"visuallyHidden\">Close dialog</span>\n</button>\n```\n\n**Visually Hidden CSS:**\n\n```css\n.visuallyHidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border-width: 0;\n}\n```\n\n**Form Accessibility:**\n\n```html\n<!-- ❌ Bad - placeholder is not a label -->\n<input type=\"email\" placeholder=\"Email address\" />\n\n<!-- ✅ Good - proper label association -->\n<label for=\"email\">Email address</label>\n<input type=\"email\" id=\"email\" autocomplete=\"email\" />\n\n<!-- ✅ Good - error announcement -->\n<label for=\"password\">Password</label>\n<input\n  type=\"password\"\n  id=\"password\"\n  aria-invalid=\"true\"\n  aria-describedby=\"password-error\"\n/>\n<div id=\"password-error\" role=\"alert\">\n  Password must be at least 8 characters\n</div>\n```\n\n---\n\n### Phase 3: Focus Management\n\n**Goal**: Proper focus handling for modals, sheets, and navigation\n\n**Modal/Sheet Focus Management:**\n\n```javascript\nclass AccessibleModal {\n  constructor(modalElement) {\n    this.modal = modalElement;\n    this.focusableElements = null;\n    this.previousFocus = null;\n  }\n\n  open() {\n    // Store current focus\n    this.previousFocus = document.activeElement;\n\n    // Get all focusable elements in modal\n    this.focusableElements = this.modal.querySelectorAll(\n      ''a[href], button:not([disabled]), textarea, input, select, [tabindex]:not([tabindex=\"-1\"])''\n    );\n\n    // Focus first element\n    if (this.focusableElements.length > 0) {\n      this.focusableElements[0].focus();\n    }\n\n    // Trap focus within modal\n    this.modal.addEventListener(''keydown'', this.trapFocus.bind(this));\n\n    // Announce modal to screen readers\n    this.modal.setAttribute(''aria-modal'', ''true'');\n    this.modal.setAttribute(''role'', ''dialog'');\n  }\n\n  trapFocus(e) {\n    if (e.key !== ''Tab'') return;\n\n    const firstElement = this.focusableElements[0];\n    const lastElement = this.focusableElements[this.focusableElements.length - 1];\n\n    if (e.shiftKey && document.activeElement === firstElement) {\n      e.preventDefault();\n      lastElement.focus();\n    } else if (!e.shiftKey && document.activeElement === lastElement) {\n      e.preventDefault();\n      firstElement.focus();\n    }\n  }\n\n  close() {\n    this.modal.removeEventListener(''keydown'', this.trapFocus);\n\n    // Return focus to trigger element\n    if (this.previousFocus) {\n      this.previousFocus.focus();\n    }\n  }\n}\n```\n\n**Bottom Sheet Focus:**\n\n```css\n.bottomSheet {\n  position: fixed;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  background: var(--color-bg);\n  border-radius: 16px 16px 0 0;\n  padding: 24px;\n  transform: translateY(100%);\n  transition: transform 0.3s ease;\n}\n\n.bottomSheet.open {\n  transform: translateY(0);\n}\n\n/* Focus indicator for keyboard users */\n.bottomSheet *:focus {\n  outline: 2px solid var(--color-primary);\n  outline-offset: 2px;\n}\n\n/* Hide focus outline for mouse users, show for keyboard */\n.bottomSheet *:focus:not(:focus-visible) {\n  outline: none;\n}\n\n.bottomSheet *:focus-visible {\n  outline: 2px solid var(--color-primary);\n  outline-offset: 2px;\n}\n```\n\n---\n\n### Phase 4: Live Regions & Announcements\n\n**Goal**: Announce dynamic content changes to screen readers\n\n**Toast/Snackbar Announcements:**\n\n```html\n<!-- Polite announcement - doesn''t interrupt -->\n<div role=\"status\" aria-live=\"polite\" aria-atomic=\"true\" class=\"visuallyHidden\">\n  <!-- Announcement text injected here -->\n</div>\n\n<!-- Assertive announcement - interrupts immediately -->\n<div role=\"alert\" aria-live=\"assertive\" aria-atomic=\"true\" class=\"visuallyHidden\">\n  <!-- Error messages injected here -->\n</div>\n```\n\n```javascript\nfunction announce(message, priority = ''polite'') {\n  const liveRegion = document.querySelector(`[aria-live=\"${priority}\"]`);\n\n  // Clear and re-add to trigger announcement\n  liveRegion.textContent = '''';\n  setTimeout(() => {\n    liveRegion.textContent = message;\n  }, 100);\n\n  // Auto-clear after announcement\n  setTimeout(() => {\n    liveRegion.textContent = '''';\n  }, 5000);\n}\n\n// Usage\nsaveButton.addEventListener(''click'', async () => {\n  await saveData();\n  announce(''Changes saved successfully'', ''polite'');\n});\n\ndeleteButton.addEventListener(''click'', async () => {\n  try {\n    await deleteItem();\n    announce(''Item deleted'', ''polite'');\n  } catch (error) {\n    announce(''Error: Could not delete item'', ''assertive'');\n  }\n});\n```\n\n**Loading States:**\n\n```html\n<!-- Loading button with status -->\n<button\n  aria-label=\"Save changes\"\n  aria-busy=\"true\"\n  disabled\n>\n  <span aria-hidden=\"true\">\n    <!-- Spinner icon -->\n  </span>\n  <span>Saving...</span>\n</button>\n\n<!-- Completed state -->\n<button aria-label=\"Save changes\">\n  Save\n</button>\n```\n\n**Dynamic Content:**\n\n```html\n<!-- List that updates -->\n<ul role=\"list\" aria-live=\"polite\" aria-relevant=\"additions removals\">\n  <li>Item 1</li>\n  <li>Item 2</li>\n  <!-- New items announced automatically -->\n</ul>\n\n<!-- Pagination -->\n<nav aria-label=\"Pagination\">\n  <button aria-label=\"Previous page\" disabled>Previous</button>\n  <span aria-current=\"page\" aria-label=\"Page 1 of 5\">1</span>\n  <button aria-label=\"Next page, Page 2\">Next</button>\n</nav>\n```\n\n---\n\n### Phase 5: VoiceOver/TalkBack Testing\n\n**Goal**: Manual testing with actual screen readers\n\n**VoiceOver Gestures (iOS):**\n- Swipe right: Next item\n- Swipe left: Previous item\n- Double tap: Activate\n- Three-finger swipe: Scroll\n- Two-finger double tap: Magic Tap (primary action)\n- Rotor: Two-finger rotation to change navigation mode\n\n**TalkBack Gestures (Android):**\n- Swipe right: Next item\n- Swipe left: Previous item\n- Double tap: Activate\n- Swipe down then up: First item\n- Swipe up then down: Last item\n- Local context menu: Swipe up then right\n\n**Testing Checklist:**\n\n```markdown\n### VoiceOver Testing (iOS)\n\n- [ ] Can navigate through all interactive elements\n- [ ] Button labels are descriptive (\"Close\" not \"X\")\n- [ ] Form inputs announce their purpose and state\n- [ ] Images have meaningful alt text (or aria-hidden if decorative)\n- [ ] Modals trap focus and announce as dialogs\n- [ ] Page title announces on navigation\n- [ ] Headings create logical document outline\n- [ ] Custom controls have appropriate ARIA roles\n- [ ] Loading states announce to user\n- [ ] Error messages are announced immediately\n- [ ] Dynamic content updates are announced\n- [ ] Can dismiss modals with swipe gestures\n- [ ] Rotor navigation works (headings, links, form controls)\n\n### TalkBack Testing (Android)\n\n- [ ] All interactive elements are reachable\n- [ ] Touch exploration works (drag finger to explore)\n- [ ] Local context menu provides actions\n- [ ] Swipe gestures navigate correctly\n- [ ] Custom gestures have TalkBack equivalents\n- [ ] Reading order matches visual order\n- [ ] Lists announce item count\n- [ ] Expandable sections announce state (expanded/collapsed)\n\n### Switch Control Testing\n\n- [ ] Can navigate with single switch\n- [ ] All actions reachable via scanning\n- [ ] Scanning speed is reasonable\n- [ ] No focus traps for switch users\n```\n\n---\n\n### Phase 6: Reduced Motion & Preferences\n\n**Goal**: Respect user preferences for motion and accessibility\n\n```css\n/* Disable animations for users who prefer reduced motion */\n@media (prefers-reduced-motion: reduce) {\n  *,\n  *::before,\n  *::after {\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: 0.01ms !important;\n  }\n\n  .pullToRefresh .refreshIndicator,\n  .swipeableItem .swipeContent {\n    transition: none !important;\n  }\n}\n\n/* High contrast mode */\n@media (prefers-contrast: high) {\n  .button {\n    border: 2px solid currentColor;\n  }\n\n  .card {\n    border: 1px solid var(--color-text);\n  }\n}\n\n/* Dark mode preference */\n@media (prefers-color-scheme: dark) {\n  :root {\n    --color-bg: #121212;\n    --color-text: #ffffff;\n  }\n}\n```\n\n---\n\n## Mobile Accessibility Checklist\n\n### Touch Targets\n- [ ] All interactive elements ≥ 44x44px (WCAG AAA) or ≥ 48x48px (recommended)\n- [ ] Adequate spacing between targets (8px minimum)\n- [ ] Touch targets don''t overlap\n\n### Screen Reader Support\n- [ ] All images have alt text (or aria-hidden if decorative)\n- [ ] Icon-only buttons have aria-label\n- [ ] Form inputs have associated labels\n- [ ] Custom controls have appropriate ARIA roles\n- [ ] Page landmarks (header, nav, main, footer) are defined\n- [ ] Headings create logical document outline (h1 → h2 → h3)\n\n### Focus Management\n- [ ] Focus order matches visual order\n- [ ] All interactive elements are keyboard accessible\n- [ ] Focus indicators are clearly visible (2px outline minimum)\n- [ ] Modals trap focus and return focus on close\n- [ ] Skip links provided for navigation\n\n### Live Regions\n- [ ] Loading states announce with aria-busy or live region\n- [ ] Success messages use aria-live=\"polite\"\n- [ ] Error messages use role=\"alert\" or aria-live=\"assertive\"\n- [ ] Dynamic content updates are announced\n\n### Forms\n- [ ] All inputs have visible labels\n- [ ] Required fields are indicated (not just color)\n- [ ] Error messages are associated with inputs (aria-describedby)\n- [ ] Validation errors are announced\n- [ ] Autocomplete attributes for common fields\n\n### Motion & Preferences\n- [ ] Respects prefers-reduced-motion\n- [ ] Animations can be paused or disabled\n- [ ] Motion-triggered actions have static alternatives\n- [ ] High contrast mode supported\n\n### Mobile-Specific\n- [ ] Content reflows to 320px without horizontal scroll\n- [ ] Works in portrait and landscape orientation\n- [ ] No pinch-to-zoom disabled (allow zoom)\n- [ ] Text can be resized to 200% without loss of content\n\n---\n\n## Output Format\n\n```markdown\n## Mobile Accessibility Audit Results\n\n### Critical Issues (WCAG Level A)\n- [ ] **Touch Target Too Small** - Button at `[selector]` is 32x32px (requires 44x44px)\n- [ ] **Missing Label** - Input at `[selector]` has no associated label\n- [ ] **Focus Trap** - Modal does not return focus on close\n\n### Important Issues (WCAG Level AA)\n- [ ] **Insufficient Contrast** - Text on background is 3.2:1 (requires 4.5:1)\n- [ ] **Missing Landmark** - Page missing main landmark\n\n### Enhancements (WCAG Level AAA)\n- [ ] **Touch Target Enhancement** - Increase to 48x48px for better usability\n- [ ] **Enhanced Announcements** - Add more descriptive loading states\n\n### Files Modified\n- `[filepath]` - Touch target fixes\n- `[filepath]` - ARIA labels and landmarks\n- `[filepath]` - Focus management\n- `[filepath]` - Live region announcements\n\n### Testing Notes\n**VoiceOver (iOS):**\n- Navigation works correctly through all elements\n- Buttons announce purpose clearly\n- Modal focus trapping works\n\n**TalkBack (Android):**\n- All elements reachable via swipe\n- Local context menu provides expected actions\n- Reading order matches visual layout\n\n### Checklist Results\n✅ Touch targets ≥ 44px\n✅ Screen reader labels present\n✅ Focus management implemented\n✅ Live regions for dynamic content\n✅ Reduced motion respected\n⚠️ High contrast mode needs testing\n```\n\n---\n\n## Integration with Other Skills\n\n- **/mobile-patterns** - Ensure navigation patterns are accessible\n- **/touch-interactions** - Verify gestures have keyboard alternatives\n- **/component-states** - Add accessible focus and disabled states\n- **/accessibility-audit** - General accessibility (this skill is mobile-focused)\n\n---\n\n## Notes\n\n- Test with actual screen readers on real devices - simulators don''t fully replicate experience\n- VoiceOver and TalkBack have different behaviors - test both\n- Touch target size is the #1 mobile accessibility issue\n- Don''t rely on color alone to convey information\n- Keep forms short and use appropriate input types for mobile keyboards\n- Respect user preferences (reduced motion, dark mode, high contrast)\n- Live regions should be in DOM from page load, not dynamically added\n"},"lastSynced":"2026-03-07T12:54:29.316Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents focused on UI development, needing advanced mobile accessibility features for VoiceOver and TalkBack support","zh":"非常适合专注于UI开发、需要VoiceOver和TalkBack支持的先进移动无障碍功能的AI Agent","ja":"UI開発に焦点を当て、VoiceOverおよびTalkBackサポートのための高度なモバイルアクセシビリティ機能を必要とするAIエージェントに最適です","ko":"UI 개발에 중점을 둔 VoiceOver 및 TalkBack 지원을 위한 고급 모바일 접근성 기능이 필요한 AI 에이전트에 이상적입니다","es":"Ideal para AI Agents centrados en el desarrollo de UI, que necesitan funciones avanzadas de accesibilidad móvil para soporte de VoiceOver y TalkBack","fr":"Idéal pour les AI Agents axés sur le développement d''interface utilisateur, nécessitant des fonctionnalités avancées d''accessibilité mobile pour la prise en charge de VoiceOver et TalkBack","de":"Ideal für AI Agents, die sich auf die UI-Entwicklung konzentrieren und erweiterte mobile Barrierefreiheitsfunktionen für VoiceOver- und TalkBack-Unterstützung benötigen","pt":"Ideal para Agentes de IA focados no desenvolvimento de UI, necessitando de recursos avançados de acessibilidade móvel para suporte a VoiceOver e TalkBack","ru":"Идеально подходит для ИИ-агентов, ориентированных на разработку пользовательского интерфейса и нуждающихся в расширенных функциях мобильной доступности для поддержки VoiceOver и TalkBack","ar":"مثالي لوكلاء الذكاء الاصطناعي المركّزين على تطوير واجهة المستخدم، والذين يحتاجون إلى ميزات متقدمة لإمكانية الوصول على الأجهزة المحمولة لدعم VoiceOver وTalkBack"},"recommendation":{"en":"Empowers agents to implement WCAG 2.1 compliant touch targets, fix focus management issues in modals and bottom sheets, and add screen reader announcements for dynamic content using VoiceOver and TalkBack protocols","zh":"使Agent能够实现符合WCAG 2.1标准的触摸目标，修复模态框和底部工作表中的焦点管理问题，并使用VoiceOver和TalkBack协议为动态内容添加屏幕阅读器播报","ja":"エージェントがWCAG 2.1に準拠したタッチターゲットの実装、モーダルおよびボトムシートでのフォーカス管理問題の修正、VoiceOverおよびTalkBackプロトコルを使用した動的コンテンツのスクリーンリーダーアナウンスの追加を可能にします","ko":"에이전트가 WCAG 2.1을 준수하는 터치 대상을 구현하고, 모달 및 바닥 시트의 포커스 관리 문제를 수정하며, VoiceOver 및 TalkBack 프로토콜을 사용하여 동적 콘텐츠용 스크린 리더 발표를 추가할 수 있도록 지원합니다","es":"Permite a los agentes implementar objetivos táctiles compatibles con WCAG 2.1, corregir problemas de gestión del enfoque en modales y hojas inferiores, y agregar anuncios de lector de pantalla para contenido dinámico utilizando los protocolos VoiceOver y TalkBack","fr":"Permet aux agents de mettre en œuvre des cibles tactiles conformes WCAG 2.1, de corriger les problèmes de gestion du focus dans les modales et les feuilles inférieures, et d''ajouter des annonces de lecteur d''écran pour le contenu dynamique en utilisant les protocoles VoiceOver et TalkBack","de":"Ermöglicht Agents die Implementierung von WCAG 2.1-konformen Berührungszielen, die Behebung von Fokus-Management-Problemen in Modalen und Bottom Sheets sowie das Hinzufügen von Screenreader-Ankündigungen für dynamische Inhalte unter Verwendung der VoiceOver- und TalkBack-Protokolle","pt":"Capacita os agentes a implementar áreas de toque compatíveis com WCAG 2.1, corrigir problemas de gerenciamento de foco em modais e bottom sheets, e adicionar anúncios de leitor de tela para conteúdo dinâmico usando os protocolos VoiceOver e TalkBack","ru":"Позволяет агентам реализовывать области касания, соответствующие стандарту WCAG 2.1, устранять проблемы управления фокусом в модальных окнах и нижних панелях, а также добавлять объявления для скринридеров для динамического контента с использованием протоколов VoiceOver и TalkBack","ar":"يمكّن الوكلاء من تنفيذ أهداف اللمس المتوافقة مع WCAG 2.1، وإصلاح مشكلات إدارة التركيز في النوافذ المشروطة والألواح السفلية، وإضافة إعلانات قارئ الشاشة للمحتوى الديناميكي باستخدام بروتوكولات VoiceOver وTalkBack"},"useCases":{"en":["Auditing mobile interfaces for accessibility issues","Implementing VoiceOver and TalkBack support for improved user experience","Ensuring touch targets meet WCAG 2.1 mobile criteria"],"zh":["审核移动界面的无障碍问题","实施VoiceOver和TalkBack支持以改善用户体验","确保触摸目标符合WCAG 2.1移动标准"],"ja":["アクセシビリティ問題のためのモバイルインターフェースの監査","ユーザーエクスペリエンス向上のためのVoiceOverおよびTalkBackサポートの実装","タッチターゲットがWCAG 2.1モバイル基準を満たすことを確保"],"ko":["접근성 문제에 대한 모바일 인터페이스 감사","향상된 사용자 경험을 위한 VoiceOver 및 TalkBack 지원 구현","터치 대상이 WCAG 2.1 모바일 기준을 충족하는지 확인"],"es":["Auditoría de interfaces móviles para detectar problemas de accesibilidad","Implementación de soporte para VoiceOver y TalkBack para mejorar la experiencia de usuario","Garantizar que los objetivos táctiles cumplan con los criterios móviles de WCAG 2.1"],"fr":["Audit des interfaces mobiles pour détecter les problèmes d''accessibilité","Mise en œuvre de la prise en charge de VoiceOver et TalkBack pour une expérience utilisateur améliorée","Garantir que les cibles tactiles répondent aux critères mobiles WCAG 2.1"],"de":["Überprüfung mobiler Schnittstellen auf Barrierefreiheitsprobleme","Implementierung von VoiceOver- und TalkBack-Unterstützung für eine verbesserte Benutzererfahrung","Sicherstellen, dass Berührungsziele die mobilen WCAG 2.1-Kriterien erfüllen"],"pt":["Auditoria de interfaces móveis para problemas de acessibilidade","Implementação de suporte a VoiceOver e TalkBack para melhorar a experiência do usuário","Garantia de que as áreas de toque atendem aos critérios móveis da WCAG 2.1"],"ru":["Аудит мобильных интерфейсов на предмет проблем доступности","Реализация поддержки VoiceOver и TalkBack для улучшения пользовательского опыта","Обеспечение соответствия областей касания мобильным критериям WCAG 2.1"],"ar":["تدقيق واجهات الأجهزة المحمولة للكشف عن مشكلات إمكانية الوصول","تنفيذ دعم VoiceOver وTalkBack لتحسين تجربة المستخدم","ضمان استهداف اللمس لتلبية معايير WCAG 2.1 للأجهزة المحمولة"]},"limitations":{"en":["Requires knowledge of mobile development frameworks","Limited to VoiceOver and TalkBack screen readers"],"zh":["需要具备移动开发框架的知识","仅限于VoiceOver和TalkBack屏幕阅读器"],"ja":["モバイル開発フレームワークの知識が必要","VoiceOverおよびTalkBackスクリーンリーダーに限定されます"],"ko":["모바일 개발 프레임워크에 대한 지식 필요","VoiceOver 및 TalkBack 스크린 리더로 제한됨"],"es":["Requiere conocimiento de frameworks de desarrollo móvil","Limitado a los lectores de pantalla VoiceOver y TalkBack"],"fr":["Nécessite une connaissance des frameworks de développement mobile","Limité aux lecteurs d''écran VoiceOver et TalkBack"],"de":["Erfordert Kenntnisse in Mobile-Development-Frameworks","Beschränkt auf die Screenreader VoiceOver und TalkBack"],"pt":["Requer conhecimento de frameworks de desenvolvimento móvel","Limitado aos leitores de tela VoiceOver e TalkBack"],"ru":["Требует знания фреймворков для мобильной разработки","Ограничено скринридерами VoiceOver и TalkBack"],"ar":["يتطلب معرفة بأطر عمل تطوير الأجهزة المحمولة","يقتصر على قارئي الشاشة VoiceOver وTalkBack"]},"version":4},"contentHash":"eb025b3c4e0f417baba5fca0bae8ce31fe260365dc68689a845129748394f04f","qualityScore":60}');
