INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('github/awesome-copilot/gh-cli', 'gh-cli', 'github', 'awesome-copilot', 'community', 'gh-cli github awesome-copilot community The gh-cli skill provides community-contributed instructions for GitHub Copilot, enabling developers to work efficiently with GitHub from the command line. It supports version 2.85.0. gh-cli 是 GitHub 命令行工具，用于简化 GitHub 操作 gh-cli は GitHub CLI の機能を拡張する AI エージェントです gh-cli는 GitHub CLI를 최대한 활용할 수 있는 도구입니다 gh-cli es una herramienta de línea de comandos para GitHub que te permite trabajar de forma eficiente. Aprende a instalar y configurar gh-cli para aprovechar al máximo sus funcionalidades. gh-cli est un outil de ligne de commande pour GitHub qui vous permet de travailler de manière efficace. Apprenez à installer et à configurer gh-cli pour tirer parti de ses fonctionnalités. gh-cli ist ein Kommandozeilen-Tool für GitHub, mit dem Sie effizient arbeiten können. Erfahren Sie, wie Sie gh-cli installieren und konfigurieren können, um seine Funktionen optimal zu nutzen. O gh-cli é uma ferramenta de linha de comando para trabalhar com o GitHub. Aprenda a instalá-lo e configurá-lo para melhorar sua produtividade gh-cli - это инструмент командной строки для работы с GitHub. Узнайте, как его установить и настроить для повышения производительности gh-cli هو أداة سطر أوامر للعمل مع GitHub. تعلم كيفية تثبيته وإعداده لتحسين إنتاجيتك how to use gh-cli gh-cli install guide github cli alternative gh-cli vs github cli what is gh-cli gh-cli setup for linux github copilot integration gh-cli command line interface github cli version 2.85.0 gh-cli GitHub 命令行工具 GitHub CLI AI エージェント GitHub 开发 命令行操作 macOS Linux brew curl Installs via brew on macOS or curl on Linux Supports GitHub CLI version 2.85.0 Utilizes dpkg for architecture detection on Linux Employs GitHub archive keyring for secure package management Configures deb repository for seamless updates Works with GitHub Copilot for enhanced development experience gh-cli is a command-line interface for GitHub, allowing developers to interact with the platform from their terminal');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GBSOSS/skill-from-masters/skill-from-github', 'community', 'GBSOSS', 'skill-from-masters', 'GBSOSS/skill-from-masters', 'skill-from-github', 0, 0, 60, '2026-03-08T01:57:15.264Z', '2026-03-08T01:59:38.979Z', '3a5c1312f05fdf3e74e9edc2759cfb2ac7ecf61ce01b7ebe687853c1cf8ed156', '{"id":"GBSOSS/skill-from-masters/skill-from-github","name":"skill-from-github","description":{"en":"The skill-from-github AI agent skill enables developers to create custom skills by searching GitHub for quality projects, understanding them deeply, and then creating a skill based on that knowledge. It benefits developers who want to automate tasks by leveraging existing tools and projects.","zh":"skill-from-github技能允许开发者快速找到和集成GitHub上的高质量项目，用于构建AI技能","ja":"skill-from-githubスキルは、GitHub上的高品質プロジェクトを迅速に検索して統合し、AIエージェントを構築することを可能にします","ko":"skill-from-github 스킬은 GitHub上的 고 품질 프로젝트를迅速하게 검색하고 통합하여 AI 에이전트를 개발하는 것을 가능하게 합니다","es":"Skill from GitHub permite a los desarrolladores crear habilidades de IA personalizadas a partir de proyectos de calidad en GitHub","fr":"Skill from GitHub permet aux développeurs de créer des compétences d''IA personnalisées à partir de projets de qualité sur GitHub","de":"Skill from GitHub ermöglicht es Entwicklern, maßgeschneiderte IA-Fähigkeiten aus qualitativ hochwertigen Projekten auf GitHub zu erstellen","pt":"O Skill from GitHub permite criar habilidades de IA baseadas em projetos de qualidade do GitHub. Entenda a intenção do usuário e crie soluções personalizadas.","ru":"ИИ Агенты от GitHub позволяют создавать навыки на основе проектов с GitHub. Поймите намерения пользователя и создайте индивидуальные решения.","ar":"المركب من Skill from GitHub يسمح بإنشاء مهارات ذكية باستخدام مشاريع جودة عالية من GitHub. افهم نوايا المستخدم وإنشاء حلول مخصصة."},"seo":{"title":{"en":"Skill-From-Github: GitHub-Based AI Skill Development | AI...","zh":"GitHub技能集成指南：AI工具快速开发","ja":"GitHubスキルを活用したAIエージェントの構築方法","ko":"GitHub 스킬을 활용한 AI 에이전트 개발 가이드","es":"Guía de configuración de Skill from GitHub para desarroll...","fr":"Mise en place de Skill from GitHub pour les développeurs","de":"Einrichtungsleitfaden für Skill from GitHub für Entwickler","pt":"Guia de Configuração do Skill from GitHub para Desenvolve...","ru":"ИИ Агенты: Настройка Skill from GitHub для Решения Задач","ar":"دليل تنصيب Skill from GitHub لتحليل المشاريع على GitHub"},"description":{"en":"Discover how to create AI skills with proven methodologies from GitHub. Learn to search, understand, and implement quality projects for task automation.","zh":"利用GitHub上的开源项目和专业知识，快速构建AI技能，提高开发效率","ja":"GitHubのオープンソースプロジェクトと専門知識を活用して、AIエージェントを迅速に構築する","ko":"GitHub의 오픈소스 프로젝트와 전문 지식을 활용하여 AI 에이전트를 빠르게 개발하는 방법","es":"Aprende a crear habilidades de IA con Skill from GitHub, busca proyectos de calidad en GitHub y crea habilidades personalizadas","fr":"Découvrez comment créer des compétences d''IA avec Skill from GitHub, recherchez des projets de qualité sur GitHub et créez des compétences personnalisées","de":"Erfahren Sie, wie Sie mit Skill from GitHub IA-Fähigkeiten erstellen, suchen Sie nach qualitativ hochwertigen Projekten auf GitHub und erstellen Sie maßgesch...","pt":"Aprenda a criar habilidades de IA com base em projetos de qualidade do GitHub. Descubra como entender a intenção do usuário e criar soluções personalizadas.","ru":"Создавайте ИИ агенты на основе проверенных методологий с GitHub. Узнайте, как понять намерения пользователя и создать индивидуальные решения.","ar":"تعلم كيفية إنشاء مهارات ذكية باستخدام مشاريع جودة عالية من GitHub. اكتشف كيفية فهم نوايا المستخدم وإنشاء حلول مخصصة."},"definition":{"en":"skill-from-github is a technique for creating AI skills by leveraging proven methodologies from domain experts on GitHub, allowing for the automation of tasks through custom skill development.","zh":"skill-from-github是指利用GitHub上的开源项目和专业知识构建AI技能的技术","ja":"skill-from-githubは、GitHubのオープンソースプロジェクトと専門知識を活用してAIエージェントを構築する技術です","ko":"skill-from-github는 GitHub의 오픈소스 프로젝트와 전문 지식을 활용하여 AI 에이전트를 개발하는 기술입니다","es":"Skill from GitHub es una habilidad de IA que busca proyectos de calidad en GitHub para crear habilidades personalizadas","fr":"Skill from GitHub est une compétence d''IA qui recherche des projets de qualité sur GitHub pour créer des compétences personnalisées","de":"Skill from GitHub ist eine IA-Fähigkeit, die nach qualitativ hochwertigen Projekten auf GitHub sucht, um maßgeschneiderte Fähigkeiten zu erstellen","pt":"O Skill from GitHub é uma habilidade de IA que permite criar soluções personalizadas com base em projetos de qualidade do GitHub.","ru":"ИИ Агенты от GitHub - это навык, который позволяет создавать индивидуальные решения на основе проектов с GitHub.","ar":"المركب من Skill from GitHub هو مهارة ذكية تسمح بإنشاء حلول مخصصة باستخدام مشاريع جودة عالية من GitHub."},"features":{"en":["Searches GitHub for quality projects to solve user-described tasks","Understands project code deeply to inform skill development","Creates custom AI skills based on knowledge gained from GitHub projects","Supports task automation for activities like markdown to PDF conversion","Facilitates sentiment analysis in customer reviews","Generates API documentation from code"],"zh":["支持Markdown到PDF转换","集成了情感分析功能","能够生成API文档"],"ja":["MarkdownをPDFに変換する機能をサポート","感情分析機能を統合","APIドキュメントを生成する"],"ko":["Markdown을 PDF로 변환하는 기능을 지원","감정 분석 기능을 통합","API 문서를 생성하는 기능"],"es":["Búsqueda de proyectos de calidad en GitHub","Creación de habilidades de IA personalizadas","Análisis de sentimiento en reseñas de clientes","Generación de documentación de API a partir de código","Conversión de markdown a PDF"],"fr":["Recherche de projets de qualité sur GitHub","Création de compétences d''IA personnalisées","Analyse de sentiment dans les avis clients","Génération de documentation d''API à partir de code","Conversion de markdown en PDF"],"de":["Suche nach qualitativ hochwertigen Projekten auf GitHub","Erstellung maßgeschneiderter IA-Fähigkeiten","Sentiment-Analyse in Kundenbewertungen","Generierung von API-Dokumentation aus Code","Konvertierung von markdown in PDF"],"pt":["Criação de habilidades de IA com base em projetos do GitHub","Entendimento da intenção do usuário para criar soluções personalizadas","Análise de projetos de qualidade do GitHub para resolver problemas","Geração de API documentation a partir de código","Análise de sentimentos em comentários de clientes"],"ru":["Создание ИИ агентов на основе проектов с GitHub","Понимание намерений пользователя для создания индивидуальных решений","Анализ проектов с GitHub для решения задач","Генерация документации API из кода","Анализ настроений в комментариях клиентов"],"ar":["إنشاء مهارات ذكية باستخدام مشاريع جودة عالية من GitHub","فهم نوايا المستخدم لإنشاء حلول مخصصة","تحليل مشاريع جودة عالية من GitHub لحل المشكلات","توليد توثيق واجهة برمجة التطبيقات من الكود","تحليل المشاعر في التعليقات العملاء"]},"keywords":{"en":["how to use skill-from-github","what is skill-from-github","skill-from-github alternative","skill-from-github vs custom development","skill-from-github install guide","skill-from-github setup for AI agents","github based ai skill development","automating tasks with skill-from-github"],"zh":["AI工具开发","GitHub技能集成","快速开发AI技能","Markdown转PDF","情感分析","API文档生成"],"ja":["AIエージェント開発","GitHubスキル統合","迅速にAIエージェントを構築","MarkdownをPDFに変換","感情分析","APIドキュメント生成"],"ko":["AI 에이전트 개발","GitHub 스킬 통합","빠르게 AI 에이전트를 개발","Markdown을 PDF로 변환","감정 분석","API 문서 생성"],"es":["Skill from GitHub","habilidades de IA","proyectos de calidad en GitHub","creación de habilidades personalizadas","análisis de sentimiento","generación de documentación de API","conversión de markdown a PDF","desarrollo de IA","herramientas de IA para desarrolladores"],"fr":["Skill from GitHub","compétences d''IA","projets de qualité sur GitHub","création de compétences personnalisées","analyse de sentiment","génération de documentation d''API","conversion de markdown en PDF","développement d''IA","outils d''IA pour les développeurs"],"de":["Skill from GitHub","IA-Fähigkeiten","qualitativ hochwertige Projekte auf GitHub","Erstellung maßgeschneiderter Fähigkeiten","Sentiment-Analyse","Generierung von API-Dokumentation","Konvertierung von markdown in PDF","IA-Entwicklung","IA-Tools für Entwickler"],"pt":["skill from github","criação de habilidades de ia","análise de projetos do github","entendimento da intenção do usuário","geração de api documentation","análise de sentimentos em comentários de clientes","desenvolvimento de ia","projetos de qualidade do github"],"ru":["ИИ агенты от github","создание навыков ии","анализ проектов с github","понимание намерений пользователя","генерация документации api","анализ настроений в комментариях клиентов","разработка ии","проекты с github"],"ar":["المركب من skill from github","إنشاء مهارات ذكية","تحليل مشاريع جودة عالية من github","فهم نوايا المستخدم","توليد توثيق واجهة برمجة التطبيقات","تحليل المشاعر في التعليقات العملاء","تطوير الذكاء الاصطناعي","مشاريع جودة عالية من github"]}},"owner":"GBSOSS","repo":"skill-from-masters","repoPath":"GBSOSS/skill-from-masters","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.264Z","topics":[],"category":"community","skillMd":{"name":"skill-from-github","description":"Create skills by learning from high-quality GitHub projects","bodyPreview":"# Skill from GitHub\n\nWhen users want to accomplish something, search GitHub for quality projects that solve the problem, understand them deeply, then create a skill based on that knowledge.\n\n## When to Use\n\nWhen users describe a task and you want to find existing tools/projects to learn from:\n\n- \"I want to be able to convert markdown to PDF\"\n- \"Help me analyze sentiment in customer reviews\"\n- \"I need to generate API documentation from code\"\n\n## Workflow\n\n### Step 1: Understand User Intent\n\nClari","body":"# Skill from GitHub\n\nWhen users want to accomplish something, search GitHub for quality projects that solve the problem, understand them deeply, then create a skill based on that knowledge.\n\n## When to Use\n\nWhen users describe a task and you want to find existing tools/projects to learn from:\n\n- \"I want to be able to convert markdown to PDF\"\n- \"Help me analyze sentiment in customer reviews\"\n- \"I need to generate API documentation from code\"\n\n## Workflow\n\n### Step 1: Understand User Intent\n\nClarify what the user wants to achieve:\n- What is the input?\n- What is the expected output?\n- Any constraints (language, framework, etc.)?\n\n### Step 2: Search GitHub\n\nSearch for projects that solve this problem:\n\n```\n{task keywords} language:{preferred} stars:>100 sort:stars\n```\n\n**Search tips:**\n- Start broad, then narrow down\n- Try different keyword combinations\n- Include \"cli\", \"tool\", \"library\" if relevant\n\n**Quality filters (must meet ALL):**\n- Stars > 100 (community validated)\n- Updated within last 12 months (actively maintained)\n- Has README with clear documentation\n- Has actual code (not just awesome-list)\n\n### Step 3: Present Options to User\n\nShow top 3-5 candidates:\n\n```markdown\n## Found X projects that can help\n\n### Option 1: [project-name](github-url)\n- Stars: xxx | Last updated: xxx\n- What it does: one-line description\n- Why it''s good: specific strength\n\n### Option 2: ...\n\nWhich one should I dive into? Or should I search differently?\n```\n\n**Wait for user confirmation before proceeding.**\n\n### Step 4: Deep Dive into Selected Project\n\nOnce user selects a project, thoroughly understand it:\n\n1. **Read README** - Understand purpose, features, usage\n2. **Read core source files** - Understand how it works\n3. **Check examples** - See real usage patterns\n4. **Note dependencies** - What it relies on\n5. **Identify key concepts** - The mental model behind it\n\nExtract:\n- Core algorithm/approach\n- Input/output formats\n- Error handling patterns\n- Best practices encoded in the code\n\n### Step 5: Summarize Understanding\n\nPresent what you learned to user:\n\n```markdown\n## Understanding [project-name]\n\n### Core Approach\nHow it solves the problem...\n\n### Key Techniques\n1. ...\n2. ...\n\n### Limitations\n- ...\n\n### What I''ll encode in the skill\n- ...\n\nDoes this look right? Should I proceed to create the skill?\n```\n\n**Wait for user confirmation.**\n\n### Step 6: Create Skill via skill-creator\n\nHand off to skill-creator with:\n\n1. **Clear purpose** - What the skill does\n2. **Methodology** - The approach learned from the project\n3. **Step-by-step process** - Concrete instructions\n4. **Quality criteria** - What good output looks like\n5. **Common pitfalls** - What to avoid (learned from project issues/docs)\n\n**Important:** The skill should encode the *knowledge* from the project, not just wrap the tool. The skill should work even without the original project installed.\n\n## Example\n\n**User:** \"I want to write better commit messages\"\n\n**Step 2 - Search:**\n```\ncommit message convention stars:>100 sort:stars\n```\n\n**Step 3 - Present:**\n```\n## Found 4 projects\n\n### Option 1: conventional-commits/conventionalcommits.org (4.2k ⭐)\n- Specification for human and machine readable commit messages\n- Why: Industry standard, used by Angular, Vue, etc.\n\n### Option 2: commitizen/cz-cli (15k ⭐)\n- CLI tool for creating conventional commits\n- Why: Battle-tested, lots of adapters\n\n### Option 3: carloscuesta/gitmoji (14k ⭐)\n- Emoji guide for commit messages\n- Why: Visual, fun approach\n\nWhich one interests you?\n```\n\n**User:** \"Let''s go with conventional commits\"\n\n**Step 4 - Deep dive:**\n- Read the specification\n- Understand types (feat, fix, docs, etc.)\n- Learn about scopes, breaking changes\n- Study real-world examples\n\n**Step 5 - Summarize:**\n```\n## Understanding Conventional Commits\n\n### Core Approach\nStructured format: <type>(<scope>): <description>\n\n### Key Types\n- feat: new feature\n- fix: bug fix\n- docs: documentation\n- ...\n\n### Benefits Learned\n- Automated changelog generation\n- Semantic versioning\n- Clear history\n\nReady to create a commit message skill based on this?\n```\n\n**Step 6 - Create skill with these principles encoded**\n\n## Important Notes\n\n1. **Always get user confirmation** - At step 3 (project selection) and step 5 (before creating)\n2. **Prefer learning over wrapping** - Encode the knowledge, not just \"run this tool\"\n3. **Check license** - Mention if project has restrictive license\n4. **Credit the source** - Include attribution in generated skill\n5. **Quality over speed** - Take time to truly understand the project\n\n## What This Skill is NOT\n\n- NOT a package installer\n- NOT a tool wrapper\n- It''s about **learning from the best projects** and encoding that knowledge into a reusable skill\n"},"lastSynced":"2026-03-08T01:59:38.979Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing automated task creation from existing GitHub projects.","zh":"非常适合需要从现有 GitHub 项目自动创建任务的开发者代理。","ja":"既存の GitHub プロジェクトから自動タスク作成を必要とする Developer エージェントに最適です。","ko":"기존 GitHub 프로젝트에서 자동 작업 생성이 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan la creación automática de tareas desde proyectos de GitHub existentes.","fr":"Parfait pour les Agents de Développeur ayant besoin de la création automatisée de tâches à partir de projets GitHub existants.","de":"Perfekt für Developer-Agents, die die automatisierte Erstellung von Aufgaben aus bestehenden GitHub-Projekten benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de criação automática de tarefas a partir de projetos existentes no GitHub.","ru":"Идеально подходит для агентов-разработчиков, которым требуется автоматизированное создание задач из существующих проектов GitHub.","ar":"مثالي لعميل المطور الذي يحتاج إلى إنشاء مهام آلي من مشاريع GitHub الحالية."},"recommendation":{"en":"Empowers agents to search GitHub for quality projects, understand them deeply, and create custom skills based on that knowledge, leveraging existing tools and projects, and automating tasks through markdown, sentiment analysis, and API documentation generation.","zh":"赋予代理搜索 GitHub 的高质量项目、深入了解它们、并根据这些知识创建自定义技能的能力，利用现有的工具和项目，并通过 markdown、情感分析和 API 文档生成自动执行任务。","ja":"エージェントが GitHub で高品質のプロジェクトを検索し、深く理解し、その知識に基づいてカスタム スキルを作成する能力を与え、既存のツールやプロジェクトを利用し、markdown、感情分析、API ドキュメントの生成を通じてタスクを自動化します。","ko":"에이전트가 GitHub에서 고품질 프로젝트를 검색하고, 깊이 이해하고, 그 지식에 기반하여 커스텀 스킬을 생성할 수 있는 능력을 부여하며, 기존 도구와 프로젝트를 활용하고, markdown, 감정 분석, API 문서 생성 등을 통해 작업을 자동화합니다.","es":"Habilita a los agentes a buscar en GitHub proyectos de calidad, comprenderlos profundamente y crear habilidades personalizadas en función de ese conocimiento, aprovechando herramientas y proyectos existentes, y automatizando tareas a través de markdown, análisis de sentimiento y generación de documentación de API.","fr":"Permet aux agents de rechercher des projets de qualité sur GitHub, de les comprendre en profondeur et de créer des compétences personnalisées sur la base de ces connaissances, en exploitant les outils et les projets existants, et en automatisant les tâches via markdown, l''analyse de sentiments et la génération de documentation d''API.","de":"Ermächtigt Agenten, GitHub nach qualitativ hochwertigen Projekten zu durchsuchen, diese tiefgreifend zu verstehen und auf dieser Grundlage benutzerdefinierte Fähigkeiten zu erstellen, indem bestehende Werkzeuge und Projekte genutzt und Aufgaben durch Markdown, Sentiment-Analyse und API-Dokumentationsgenerierung automatisiert werden.","pt":"Habilita os agentes a procurar no GitHub por projetos de qualidade, compreendê-los profundamente e criar habilidades personalizadas com base nesse conhecimento, aproveitando ferramentas e projetos existentes e automatizando tarefas por meio de markdown, análise de sentimentos e geração de documentação de API.","ru":"Наделяет агентов возможностью искать в GitHub качественные проекты, глубоко понимать их и создавать на основе этих знаний индивидуальные навыки, используя существующие инструменты и проекты, а также автоматизировать задачи посредством markdown, анализа настроений и генерации документации API.","ar":"يمنح الوكيل khảية البحث في GitHub عن مشاريع جيدة، وفهمها بعمق، وإنشاء مهارات مخصصة بناءً على هذا المعرفة، واستخدام الأدوات والمشاريع الحالية، وتحسين المهام من خلال markdown، وتحليل المشاعر، وإنشاء وثائق API."},"useCases":{"en":["Automating markdown to PDF conversions","Generating sentiment analysis tools for customer reviews","Creating API documentation from code repositories"],"zh":["自动将 markdown 转换为 PDF","为客户评论生成情感分析工具","从代码仓库生成 API 文档"],"ja":["markdown を PDF に自動変換する","顧客レビューの感情分析ツールを生成する","コード リポジトリから API ドキュメントを生成する"],"ko":["markdown를 PDF로 자동 변환하는 것","고객 리뷰에 대한 감정 분석 도구 생성","코드 저장소에서 API 문서 생성"],"es":["Automatización de conversión de markdown a PDF","Generación de herramientas de análisis de sentimiento para reseñas de clientes","Creación de documentación de API a partir de repositorios de código"],"fr":["Automatisation de la conversion de markdown en PDF","Génération d''outils d''analyse de sentiments pour les avis clients","Création de documentation d''API à partir de dépôts de code"],"de":["Automatisierung von Markdown-zu-PDF-Konversionen","Generierung von Sentiment-Analyse-Tools für Kundenbewertungen","Erstellung von API-Dokumentationen aus Code-Repositorys"],"pt":["Automatizar conversões de markdown para PDF","Gerar ferramentas de análise de sentimentos para avaliações de clientes","Criar documentação de API a partir de repositórios de código"],"ru":["Автоматизировать преобразование markdown в PDF","Генерировать инструменты анализа настроений для обзоров клиентов","Создавать документацию API из кодовых репозиториев"],"ar":["تحويل markdown إلى PDF آليا","إنشاء أدوات تحليل المشاعر لمراجعات العملاء","إنشاء وثائق API من مستودعات الشفرة"]},"limitations":{"en":["Requires GitHub access","Dependent on quality and relevance of GitHub projects","Limited to projects with accessible and understandable codebases"],"zh":["需要 GitHub 访问","依赖于 GitHub 项目的质量和相关性","仅限于具有可访问和可理解代码库的项目"],"ja":["GitHub アクセスが必要","GitHub プロジェクトの品質と関連性に依存する","アクセス可能で理解可能なコードベースを持つプロジェクトに限定される"],"ko":["GitHub 액세스가 필요","GitHub 프로젝트의 품질 및 관련성에 의존","액세스 가능하고 이해 가능한 코드베이스를 가진 프로젝트에만 제한"],"es":["Requiere acceso a GitHub","Dependiente de la calidad y relevancia de los proyectos de GitHub","Limitado a proyectos con bases de código accesibles y comprensibles"],"fr":["Nécessite un accès à GitHub","Dépendant de la qualité et de la pertinence des projets GitHub","Limité aux projets avec des bases de code accessibles et compréhensibles"],"de":["Benötigt Zugriff auf GitHub","Abhängig von der Qualität und Relevanz der GitHub-Projekte","Begrenzt auf Projekte mit zugänglichen und verständlichen Codebasen"],"pt":["Exige acesso ao GitHub","Depende da qualidade e relevância dos projetos do GitHub","Limitado a projetos com bases de código acessíveis e compreensíveis"],"ru":["Требует доступа к GitHub","Зависит от качества и релевантности проектов GitHub","Ограничен проектами с доступными и понятными кодовыми базами"],"ar":["يتطلب الوصول إلى GitHub","يعتمد على جودة وأهمية مشاريع GitHub","محدود بمشاريع ذات قواعد شفرة يمكن الوصول إليها وفهما"]},"version":4},"contentHash":"3a5c1312f05fdf3e74e9edc2759cfb2ac7ecf61ce01b7ebe687853c1cf8ed156","qualityScore":60}');
