INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GBSOSS/skill-from-masters/skill-from-github', 'skill-from-github', 'GBSOSS', 'skill-from-masters', 'community', 'skill-from-github GBSOSS skill-from-masters community The skill-from-github AI agent skill enables developers to create custom skills by searching GitHub for quality projects, understanding them deeply, and then creating a skill based on that knowledge. It benefits developers who want to automate tasks by leveraging existing tools and projects. skill-from-github技能允许开发者快速找到和集成GitHub上的高质量项目，用于构建AI技能 skill-from-githubスキルは、GitHub上的高品質プロジェクトを迅速に検索して統合し、AIエージェントを構築することを可能にします skill-from-github 스킬은 GitHub上的 고 품질 프로젝트를迅速하게 검색하고 통합하여 AI 에이전트를 개발하는 것을 가능하게 합니다 Skill from GitHub permite a los desarrolladores crear habilidades de IA personalizadas a partir de proyectos de calidad en GitHub Skill from GitHub permet aux développeurs de créer des compétences d''IA personnalisées à partir de projets de qualité sur GitHub Skill from GitHub ermöglicht es Entwicklern, maßgeschneiderte IA-Fähigkeiten aus qualitativ hochwertigen Projekten auf GitHub zu erstellen O Skill from GitHub permite criar habilidades de IA baseadas em projetos de qualidade do GitHub. Entenda a intenção do usuário e crie soluções personalizadas. ИИ Агенты от GitHub позволяют создавать навыки на основе проектов с GitHub. Поймите намерения пользователя и создайте индивидуальные решения. المركب من Skill from GitHub يسمح بإنشاء مهارات ذكية باستخدام مشاريع جودة عالية من GitHub. افهم نوايا المستخدم وإنشاء حلول مخصصة. how to use skill-from-github what is skill-from-github skill-from-github alternative skill-from-github vs custom development skill-from-github install guide skill-from-github setup for AI agents github based ai skill development automating tasks with skill-from-github AI工具开发 GitHub技能集成 快速开发AI技能 Markdown转PDF 情感分析 API文档生成 Searches GitHub for quality projects to solve user-described tasks Understands project code deeply to inform skill development Creates custom AI skills based on knowledge gained from GitHub projects Supports task automation for activities like markdown to PDF conversion Facilitates sentiment analysis in customer reviews Generates API documentation from code skill-from-github is a technique for creating AI skills by leveraging proven methodologies from domain experts on GitHub, allowing for the automation of tasks through custom skill development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('adaptationio/Skrillz/skill-researcher', 'community', 'adaptationio', 'Skrillz', 'adaptationio/Skrillz', 'skill-researcher', 0, 0, 60, '2026-03-08T01:57:15.264Z', '2026-03-08T01:59:42.999Z', 'a8db4f446b24f0a61ddb3da8be92315e30b122ede1222c10637aaf3a0d00a267', '{"id":"adaptationio/Skrillz/skill-researcher","name":"skill-researcher","description":{"en":"The skill-researcher provides systematic research operations for gathering information from multiple sources, enabling comprehensive exploration of technologies and best practices for AI agent skill development.","zh":"skill-researcher提供系统化的研究操作，用于从多个来源收集信息，实现对技术、模式和最佳实践的全面探索","ja":"skill-researcherは、Web、MCPサーバー、GitHubリポジトリ、公式ドキュメントの技術、パターン、ベストプラクティスを包括的に調査するためのシステム化された研究操作を提供","ko":"skill-researcher는 체계적인 연구 작업을 제공하여 웹, MCP 서버, 깃허브 리포지토리, 공식 문서의 기술, 패턴, 최선의 관행을 종합적으로 탐색","es":"Skill-researcher proporciona operaciones de investigación sistemáticas para recopilar información de múltiples fuentes como Web, servidores MCP y GitHub","fr":"Skill-researcher fournit des opérations de recherche systématiques pour collecter des informations de multiples sources comme le Web, les serveurs MCP et GitHub","de":"Skill-researcher bietet systematische Recherchen für die Erfassung von Informationen aus mehreren Quellen wie dem Web, MCP-Servern und GitHub","pt":"O skill-researcher fornece operações de pesquisa sistemáticas para reunir informações de várias fontes, permitindo uma exploração abrangente de tecnologias e padrões","ru":"ИИ Агент skill-researcher обеспечивает систематические исследования для сбора информации из нескольких источников, позволяя всестороннее изучение технологий и шаблонов","ar":"_skill-researcher_ يوفر عمليات بحث منهجية لجمع المعلومات من مصادر متعددة، مما يسمح بالاستكشاف الشامل للتكنولوجيا والأنماط"},"seo":{"title":{"en":"skill-researcher: Comprehensive Research Setup Guide | AI...","zh":"skill-researcher_SETUP GUIDE: 全面研究和开发","ja":"skill-researcherベストプラクティス: AIエージェントによる研究と開発","ko":"skill-researcher 시작하기: 종합적인 연구와 개발을 위한 안내","es":"Guía de configuración de skill-researcher para desarrolla...","fr":"Configurer skill-researcher : Guide pour les développeurs","de":"Einrichtungsleitfaden für skill-researcher: Entwickler-Re...","pt":"Guia de Configuração do Skill Researcher para Desenvolved...","ru":"Настройка ИИ Агента Skill Researcher для Разработчиков","ar":"دليل إعداد_skill-researcher_للمطورين"},"description":{"en":"Unlock informed skill development with skill-researcher. Explore multiple sources, including Web search, MCP servers, and GitHub repositories. Get started now!","zh":"使用skill-researcher进行系统化的研究操作，全面探索Web、MCP服务器、GitHub仓库和官方文档中的技术、模式和最佳实践","ja":"AIエージェントのskill-researcherを使用して、Web、MCPサーバー、GitHubリポジトリ、公式ドキュメントの技術、パターン、ベストプラクティスを包括的に調査","ko":"skill-researcher를 사용하여 체계적인 연구 작업을 수행하고 웹, MCP 서버, 깃허브 리포지토리, 공식 문서의 기술, 패턴, 최선의 관행을 종합적으로 탐색","es":"Descubre cómo configurar skill-researcher para investigaciones sistemáticas y obtener información de múltiples fuentes como GitHub y servidores MCP","fr":"Découvrez comment configurer skill-researcher pour des opérations de recherche systématiques et obtenir des informations de multiples sources comme GitHub et...","de":"Erfahren Sie, wie Sie skill-researcher für systematische Recherchen einrichten und Informationen aus mehreren Quellen wie GitHub und MCP-Servern erhalten","pt":"Aprenda a configurar o skill-researcher para pesquisas sistemáticas em múltiplas fontes, incluindo Web search, MCP servers, GitHub e documentação oficial","ru":"Узнайте, как настроить ИИ Агент skill-researcher для систематических исследований в нескольких источниках, включая поиск в Интернете, серверы MCP, GitHub и о...","ar":"تعرف على كيفية إعداد _skill-researcher_ لعمليات البحث المنهجية من مصادر متعددة، بما في ذلك بحث الويب، خوادم MCP، مستودعات GitHub، والوثائق الرسمية"},"definition":{"en":"skil