INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('adaptationio/Skrillz/skill-researcher', 'skill-researcher', 'adaptationio', 'Skrillz', 'community', 'skill-researcher adaptationio Skrillz community The skill-researcher provides systematic research operations for gathering information from multiple sources, enabling comprehensive exploration of technologies and best practices for AI agent skill development. skill-researcher提供系统化的研究操作，用于从多个来源收集信息，实现对技术、模式和最佳实践的全面探索 skill-researcherは、Web、MCPサーバー、GitHubリポジトリ、公式ドキュメントの技術、パターン、ベストプラクティスを包括的に調査するためのシステム化された研究操作を提供 skill-researcher는 체계적인 연구 작업을 제공하여 웹, MCP 서버, 깃허브 리포지토리, 공식 문서의 기술, 패턴, 최선의 관행을 종합적으로 탐색 Skill-researcher proporciona operaciones de investigación sistemáticas para recopilar información de múltiples fuentes como Web, servidores MCP y GitHub Skill-researcher fournit des opérations de recherche systématiques pour collecter des informations de multiples sources comme le Web, les serveurs MCP et GitHub Skill-researcher bietet systematische Recherchen für die Erfassung von Informationen aus mehreren Quellen wie dem Web, MCP-Servern und GitHub O skill-researcher fornece operações de pesquisa sistemáticas para reunir informações de várias fontes, permitindo uma exploração abrangente de tecnologias e padrões ИИ Агент skill-researcher обеспечивает систематические исследования для сбора информации из нескольких источников, позволяя всестороннее изучение технологий и шаблонов _skill-researcher_ يوفر عمليات بحث منهجية لجمع المعلومات من مصادر متعددة، مما يسمح بالاستكشاف الشامل للتكنولوجيا والأنماط how to use skill-researcher what is skill-researcher skill-researcher alternative skill-researcher vs competitor skill-researcher install skill-researcher setup guide github repository research mcp server research web search research tool skill-researcher AI工具 研究操作 多源研究 Web搜索 MCP服务器 GitHub仓库 官方文档 Enables comprehensive exploration of technologies and patterns across Web search Supports research operations on MCP servers for informed skill development Facilitates exploration of GitHub repositories for best practices and code examples Provides access to official documentation for accurate and up-to-date information Performs task-based research operations with 5 independent research tasks skill-researcher is a systematic research operation tool that gathers information from multiple sources, including Web search, MCP servers, GitHub repositories, and official documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lekman/cdn/github-mcp', 'community', 'lekman', 'cdn', 'lekman/cdn', 'github-mcp', 0, 0, 60, '2026-03-08T01:57:15.265Z', '2026-03-08T01:59:49.947Z', 'de8ef5e53ff95d6f10b1f36ddb165aaf206d28deeecd37cdf1460754710b9d1a', '{"id":"lekman/cdn/github-mcp","name":"github-mcp","description":{"en":"The github-mcp skill enables developers to access GitHub repositories, issues, and workflows directly from Claude Code, using secure token management via 1Password. It facilitates content-addressed image storage and distribution using Cloudflare CDN with Azure backend.","zh":"github-mcp是一个使用Cloudflare CDN和Azure后端的内容地址图像存储和分发技能，通过1Password CLI安全地管理GitHub令牌","ja":"github-mcpはCloudflare CDNとAzureバックエンドを使用したコンテンツアドレスタイメージストレージと配布スキルで、1Password CLIを使用してGitHubトークンを安全に管理","ko":"github-mcp는 Cloudflare CDN과 Azure 백엔드를 사용한 콘텐츠 주소 이미지 저장 및 분산 스킬로, 1Password CLI를 사용하여 GitHub 토큰을 안전하게 관리","es":"El skill github-mcp permite la integración segura con GitHub utilizando 1Password CLI para la gestión de tokens. Ideal para configurar servidores MCP y acceder a repositorios, problemas y solicitudes de extracción de GitHub.","fr":"Le skill github-mcp permet une intégration sécurisée avec GitHub en utilisant 1Password CLI pour la gestion des tokens. Idéal pour configurer des serveurs MCP et accéder aux référentiels, problèmes et demandes d''extraction de GitHub.","de":"Das Skill github-mcp ermöglicht eine sichere Integration mit GitHub unter Verwendung von 1Password CLI für die Tokenverwaltung. Ideal für die Konfiguration von MCP-Servern und den Zugriff auf GitHub-Repositorys, Probleme und Pull-Requests.","pt":"O github-mcp é uma habilidade que permite a integração segura com o GitHub, utilizando o 1Password CLI para gerenciar tokens de forma segura","ru":"github-mcp - это навык, который обеспечивает безопасную интеграцию с GitHub, используя 1Password CLI для управления токенами","ar":"github-mcp هو مهارة تسمح بالتكامل الآمن مع GitHub، باستخدام 1Password CLI لإدارة الرموز بشكل آمن"},"seo":{"title":{"en":"github-mcp: Secure GitHub Integration Setup Guide | AI Ag...","zh":"github-mcp Setup Guide: 使用Cloudflare CDN和Azure后端的内容地址图像存储和分发","ja":"github-mcp セットアップガイド: Cloudflare CDNとAzureバックエンドを使用したコンテン...","ko":"github-mcp 설정 가이드: Cloudflare CDN과 Azure 백엔드의 콘텐츠 주소 이미지 ...","es":"Guía de configuración de github-mcp para Claude Code","fr":"Guide de configuration github-mcp pour Claude Code","de":"Konfigurationsleitfaden für github-mcp mit Claude Code","pt":"Guia de Configuração do github-mcp para Integração com Gi...","ru":"Настройка github-mcp: интеграция с GitHub и ИИ Агенты","ar":"دليل إعداد github-mcp لتحسين أداء GitHub مع أدوات الذكاء ..."},"description":{"en":"Unlock seamless GitHub repository access with github-mcp. Learn how to set up secure token management via 1Password and integrate with Cloudflare CDN and Azu...","zh":"了解github-mcp的技术细节，使用1Password CLI安全地管理GitHub令牌，实现内容地址图像存储和分发","ja":"github-mcpの技術的な詳細を学び、1Password CLIを使用してGitHubトークンを安全に管理し、コンテンツアドレスタイメージストレージと配布を実現","ko":"github-mcp의 기술적인 세부 사항을 배우고, 1Password CLI를 사용하여 GitHub 토큰을 안전하게 관리하여 콘텐츠 주소 이미지 저장 및 분산을 구현","es":"Aprende a configurar github-mcp con Claude Code y aprovecha la gestión segura de tokens con 1Password CLI","fr":"Découvrez comment configurer github-mcp avec Claude Code et profitez d''une gestion sécurisée des tokens avec 1Password CLI","de":"Erfahren Sie, wie Sie github-mcp mit Claude Code konfigurieren und die sichere Tokenverwaltung mit 1Password CLI nutzen","pt":"Aprenda a configurar o github-mcp para acessar repositórios, issues, pull requests e workflows do GitHub de forma segura","ru":"Узнайте, как настроить github-mcp для интеграции с GitHub и безопасного управления токенами","ar":"اكتشف كيفية إعداد github-mcp لتحسين أداء GitHub وضمان أمان البيانات مع أدوات الذكاء الاصطناعي"},"definition":{"en":"github-mcp is a skill that provides secure GitHub integration for AI agents, enabling access to repositories, issues, and workflows via 1Password token management.","zh":"github-mcp是一个使用Cloudflare CDN和Azure后端的内容地址图像存储和分发技能","ja":"github-mcpはCloudflare CDNとAzureバックエンドを使用したコンテンツアドレスタイメージストレージと配布スキル","ko":"github-mcp는 Cloudflare CDN과 Azure 백엔드를 사용한 콘텐츠 주소 이미지 저장 및 분산 스킬","es":"github-mcp es un skill que permite la integración segura con GitHub utilizando 1Password CLI para la gestión de tokens","fr":"github-mcp est un skill qui permet une intégration sécurisée avec GitHub en utilisant 1Password CLI pour la gestion des tokens","de":"github-mcp ist ein Skill, der eine sichere Integration mit GitHub unter Verwendung von 1Password CLI für die Tokenverwaltung ermöglicht","pt":"O que é github-mcp? É uma habilidade que permite a integração segura com o GitHub","ru":"Что такое github-mcp? Это навык, который обеспечивает безопасную интеграцию с GitHub","ar":"ما هو github-mcp؟ هو مهارة تسمح بالتكامل الآمن مع GitHub"},"features":{"en":["Configures GitHub MCP server for secure repository access","Utilizes 1Password CLI for secure token management","Enables direct access to GitHub issues, pull requests, and workflows","Supports content-addressed image storage and distribution via Cloudflare CDN","Integrates with Azure backend for scalable storage and distribution"],"zh":["使用Cloudflare CDN进行内容分发","使用Azure后端进行内容存储","通过1Password CLI安全地管理GitHub令牌","支持GitHub仓库、问题、拉取请求和工作流","使用内容地址进行图像存储和分发","支持AIエージェント的集成"],"ja":["Cloudflare CDNを使用したコンテンツ配布","Azureバックエンドを使用したコンテンツストレージ","1Password CLIを使用してGitHubトークンを安全に管理","GitHubリポジトリ、問題、プルリクエスト、ワークフローをサポート","コンテンツアドレスを使用したイメージストレージと配布","AIエージェントの統合をサポート"],"ko":["Cloudflare CDN을 사용한 콘텐츠 분산","Azure 백엔드를 사용한 콘텐츠 저장","1Password CLI를 사용하여 GitHub 토큰을 안전하게 관리","GitHub 저장소, 문제, 풀 요청, 워크플ロー 지원","콘텐츠 주소를 사용한 이미지 저장 및 분산","AI 에이전트의 통합을 지원"],"es":["Integración segura con GitHub","Gestión de tokens con 1Password CLI","Acceso a repositorios de GitHub","Acceso a problemas y solicitudes de extracción de GitHub","Configuración de servidores MCP"],"fr":["Intégration sécurisée avec GitHub","Gestion des tokens avec 1Password CLI","Accès aux référentiels de GitHub","Accès aux problèmes et demandes d''extraction de GitHub","Configuration des serveurs MCP"],"de":["Sichere Integration mit GitHub","Tokenverwaltung mit 1Password CLI","Zugriff auf GitHub-Repositorys","Zugriff auf Probleme und Pull-Requests von GitHub","Konfiguration von MCP-Servern"],"pt":["Integração segura com o GitHub","Gerenciamento de tokens via 1Password CLI","Acesso a repositórios, issues, pull requests e workflows do GitHub","Utilização do Cloudflare CDN com backend Azure","Armazenamento e distribuição de imagens com endereçamento de conteúdo"],"ru":["Безопасная интеграция с GitHub","Управление токенами через 1Password CLI","Доступ к репозиториям, issues, pull requests и workflows GitHub","Использование Cloudflare CDN с backend Azure","Хранение и распределение изображений с адресацией контента"],"ar":["التكامل الآمن مع GitHub","إدارة الرموز عبر 1Password CLI","الوصول إلى المستودعات و issues و pull requests و workflows على GitHub","استخدام Cloudflare CDN مع الخلفية Azure","تخزين وتوزيع الصور مع عنونة المحتوى"]},"keywords":{"en":["github-mcp setup guide","github-mcp alternative","github-mcp vs gitlab","how to use github-mcp","what is github-mcp","github-mcp install","github-mcp cloudflare integration","github-mcp azure backend","github-mcp 1password token management"],"zh":["github-mcp","Cloudflare CDN","Azure后端","内容地址图像存储","1Password CLI","GitHub令牌管理","AIエージェント","内容分发","图像存储","github-mcp设置"],"ja":["github-mcp","Cloudflare CDN","Azureバックエンド","コンテンツアドレスタイメージストレージ","1Password CLI","GitHubトークン管理","AIエージェント","コンテンツ配布","イメージストレージ","github-mcp設定"],"ko":["github-mcp","Cloudflare CDN","Azure 백엔드","콘텐츠 주소 이미지 저장","1Password CLI","GitHub 토큰 관리","AI 에이전트","콘텐츠 분산","이미지 저장","github-mcp 설정"],"es":["github-mcp","integración con GitHub","gestión de tokens","1Password CLI"," Claude Code","servidores MCP","desarrollo de software","herramientas de desarrollo","agentes de IA"],"fr":["github-mcp","intégration avec GitHub","gestion des tokens","1Password CLI"," Claude Code","serveurs MCP","développement de logiciels","outils de développement","agents d''IA"],"de":["github-mcp","Integration mit GitHub","Tokenverwaltung","1Password CLI"," Claude Code","MCP-Server","Softwareentwicklung","Entwicklungstools","KI-Agents"],"pt":["github-mcp","integração com GitHub","segurança de tokens","1Password CLI","Cloudflare CDN","Azure backend","armazenamento de imagens","distribuição de conteúdo"],"ru":["github-mcp","интеграция с GitHub","безопасность токенов","1Password CLI","Cloudflare CDN","Azure backend","хранение изображений","распределение контента","ИИ Агенты"],"ar":["github-mcp","التكامل مع GitHub","أمان الرموز","1Password CLI","Cloudflare CDN","Azure backend","تخزين الصور","توزيع المحتوى","أدوات الذكاء الاصطناعي"]}},"owner":"lekman","repo":"cdn","repoPath":"lekman/cdn","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.265Z","topics":[],"category":"community","skillMd":{"name":"github-mcp","description":"Configure and manage GitHub MCP server with 1Password token management. Use when working with GitHub repositories, issues, pull requests, and workflows.","bodyPreview":"<!-- This skill follows the Agent Skills open standard: https://agentskills.io -->\n\n# GitHub MCP Setup\n\nConfigure the GitHub MCP server to access GitHub repositories, issues, pull requests, and workflows directly from Claude Code using secure token management via 1Password.\n\n**IMPORTANT:** This skill uses 1Password CLI to securely fetch GitHub tokens. Tokens are NEVER hardcoded.\n\n## When to Use This Skill\n\nUse this skill when:\n\n- Setting up MCP server integration for GitHub\n- Working with GitHub","body":"<!-- This skill follows the Agent Skills open standard: https://agentskills.io -->\n\n# GitHub MCP Setup\n\nConfigure the GitHub MCP server to access GitHub repositories, issues, pull requests, and workflows directly from Claude Code using secure token management via 1Password.\n\n**IMPORTANT:** This skill uses 1Password CLI to securely fetch GitHub tokens. Tokens are NEVER hardcoded.\n\n## When to Use This Skill\n\nUse this skill when:\n\n- Setting up MCP server integration for GitHub\n- Working with GitHub repositories, issues, or pull requests\n- Automating GitHub workflows\n- Troubleshooting GitHub MCP connection\n- Reauthenticating with different GitHub token\n- Configuring organization-specific tokens per repository\n\n## Configuration Scopes\n\nGitHub MCP supports two configuration scopes:\n\n### Global Configuration (User-wide)\n\n- **Config file**: `~/.claude.json`\n- **Use when**: Single GitHub account across all projects\n- **Token**: Shared across all repositories\n- **Command**: `bun .claude/skills/github-mcp/configure-mcp.ts --global`\n\n### Local Configuration (Project-specific)\n\n- **Config file**: `.claude/mcp.json` (gitignored)\n- **Use when**: Different GitHub organizations or accounts per repository\n- **Token**: Specific to this project only\n- **Command**: `bun .claude/skills/github-mcp/configure-mcp.ts --local`\n- **Auto-detection**: Script uses local config if `.env` file exists\n\n**Recommended approach**: Use local configuration when working with organization-specific tokens.\n\n## Automated Setup Workflow\n\nWhen this skill is invoked, follow these steps in order:\n\n### Step 1: Check if MCP Tools Are Available\n\nAttempt to use a GitHub MCP tool:\n\n```text\nUse: mcp__github__search_repositories\nInput: { \"query\": \"test\" }\n```\n\n- **If successful**: MCP is ready. Skip to usage section.\n- **If fails with \"No such tool available\"**: Continue to Step 2.\n\n### Step 2: Check if MCP Server Is Configured\n\nRun check to see server status:\n\n```bash\nclaude mcp list\n```\n\n**Possible outcomes:**\n\n**A) Server not listed:**\n\n- Run configuration script: `bun .claude/skills/github-mcp/configure-mcp.ts`\n- Script will auto-detect scope (local if `.env` exists, otherwise global)\n- Script will prompt for 1Password authentication (30 second timeout)\n- Instruct user: \"The GitHub MCP server has been configured. Please restart Claude Code with `claude -c` to continue this conversation.\"\n- **STOP HERE** - Wait for user to restart and continue\n\n**B) Server listed with \"✓ Connected\":**\n\n- MCP should be available but tools aren''t loading\n- Instruct user: \"Please restart Claude Code with `claude -c` to reload MCP servers.\"\n- **STOP HERE** - Wait for user to restart and continue\n\n**C) Server connected but using wrong/expired token:**\n\n- User reports authentication errors or wrong repository access\n- Run reauthentication: `bun .claude/skills/github-mcp/configure-mcp.ts --reauth`\n- Follow reauthentication workflow (see Reauthentication section below)\n- **STOP HERE** - Wait for user to complete reauth flow\n\n### Step 3: Add Global Allow Patterns (Optional)\n\nTo avoid permission prompts for GitHub MCP tools:\n\n```bash\nbun .claude/skills/github-mcp/configure-mcp.ts --allow-patterns\n```\n\nThis adds `mcp__github__*` to `~/.claude/settings.json` allowed tools.\n\n### Step 4: Verify Connection\n\nAfter user restarts, repeat Step 1 to verify tools are now available.\n\n## Prerequisites\n\n### Required: Bun Runtime\n\nCheck if installed:\n\n```bash\nwhich bun\n```\n\nIf not installed:\n\n```bash\ncurl -fsSL https://bun.sh/install | bash\n```\n\n### Required: 1Password CLI\n\nCheck if installed:\n\n```bash\nwhich op\n```\n\nIf not installed:\n\n```bash\nbrew install 1password-cli\n```\n\n### Required: .env File with 1Password Reference\n\nThe `.env` file must contain:\n\n```bash\nGITHUB_TOKEN=op://Private/GitHub.com/GITHUB_TOKEN\n```\n\n**Format:** `op://vault/item/field`\n\n- `vault`: 1Password vault name (e.g., \"Private\")\n- `item`: Item name in vault (e.g., \"GitHub.com\")\n- `field`: Field name (e.g., \"GITHUB_TOKEN\")\n\n### 1Password Authentication\n\nWhen running the script, 1Password will prompt for authentication:\n\n- **Timeout:** 30 seconds\n- **Action required:** Approve 1Password access request\n- **Failure:** Script exits with timeout error\n\n## Available MCP Tools\n\nOnce connected, you''ll have access to GitHub MCP tools including:\n\n**Repository Operations:**\n\n- `mcp__github__search_repositories` - Search GitHub repositories\n- `mcp__github__get_repository` - Get repository details\n- `mcp__github__list_commits` - List repository commits\n- `mcp__github__get_file_contents` - Read file contents\n\n**Issue Operations:**\n\n- `mcp__github__search_issues` - Search issues across repositories\n- `mcp__github__create_issue` - Create new issue\n- `mcp__github__update_issue` - Update issue details\n- `mcp__github__list_issues` - List repository issues\n\n**Pull Request Operations:**\n\n- `mcp__github__search_pull_requests` - Search pull requests\n- `mcp__github__create_pull_request` - Create new PR\n- `mcp__github__list_pull_requests` - List repository PRs\n- `mcp__github__merge_pull_request` - Merge a PR\n\n**Workflow Operations:**\n\n- `mcp__github__list_workflows` - List GitHub Actions workflows\n- `mcp__github__get_workflow_run` - Get workflow run details\n- `mcp__github__trigger_workflow` - Trigger workflow dispatch\n\n## Usage Examples\n\n**Search Your Pull Requests (Recommended):**\n\n```typescript\nUse: mcp__github__search_pull_requests\nInput: { \"query\": \"is:open is:pr author:@me\" }\n```\n\n**Why use `author:@me`?**\n\n- Searches content created by the authenticated user\n- Avoids permission errors when searching specific usernames\n- Works across all repositories you have access to\n\n**Search Repositories:**\n\n```typescript\nUse: mcp__github__search_repositories\nInput: { \"query\": \"language:typescript stars:>1000\" }\n```\n\n**Search Your Issues:**\n\n```typescript\nUse: mcp__github__search_issues\nInput: { \"query\": \"is:open is:issue author:@me\" }\n```\n\n**Create Issue:**\n\n```typescript\nUse: mcp__github__create_issue\nInput: {\n  \"owner\": \"northbridge-security\",\n  \"repo\": \"ai-toolkit\",\n  \"title\": \"Bug: Fix data pipeline timeout\",\n  \"body\": \"Pipeline times out after 5 minutes...\"\n}\n```\n\n**List Pull Requests (Specific Repository):**\n\n```typescript\nUse: mcp__github__list_pull_requests\nInput: {\n  \"owner\": \"northbridge-security\",\n  \"repo\": \"ai-toolkit\",\n  \"state\": \"open\"\n}\n```\n\n**Note:** Repository-specific operations (list, create, update) require exact owner/repo names. If repository names are unclear or custom git remotes are used, use search APIs with `author:@me` first to discover accessible repositories.\n\n## Best Practices\n\n### Use Search APIs for Discovery\n\n**Recommended pattern:**\n\n1. Use search APIs with `author:@me` to discover content\n2. Extract exact owner/repo names from results\n3. Use repository-specific APIs for detailed operations\n\n**Example workflow:**\n\n```typescript\n// Step 1: Find your repositories\nUse: mcp__github__search_repositories\nInput: { \"query\": \"user:@me\" }\n\n// Step 2: Use exact names from results\nUse: mcp__github__list_pull_requests\nInput: {\n  \"owner\": \"username\",\n  \"repo\": \"my-repo\",\n  \"state\": \"open\"\n}\n```\n\n### Common Search Patterns\n\n**Your open PRs across all repos:**\n\n```text\nis:open is:pr author:@me\n```\n\n**Your issues assigned to you:**\n\n```text\nis:open is:issue assignee:@me\n```\n\n**PRs you reviewed:**\n\n```text\nis:pr reviewed-by:@me\n```\n\n**Recent activity:**\n\n```text\nis:pr author:@me updated:>2025-01-01\n```\n\n### Avoiding Permission Errors\n\n**Don''t use:** `user:my-username` (may fail with 422 validation error)\n\n**Use instead:** `author:@me` (always works for authenticated user)\n\n**Why:** GitHub''s search API has different permission models for username searches vs authenticated user searches. Using `@me` ensures the token''s permissions are correctly applied.\n\n## Reauthentication\n\nIf you need to switch tokens or reauthenticate:\n\n**Run reauthentication script:**\n\n```bash\nbun .claude/skills/github-mcp/configure-mcp.ts --reauth\n```\n\nThis will:\n\n1. Remove existing MCP server configuration\n2. Fetch fresh token from 1Password (30 second timeout)\n3. Reconfigure server with new token\n\n**After running reauthentication:**\n\n1. Restart Claude Code with `claude -c`\n2. GitHub MCP tools should now use new token\n\n**Use cases:**\n\n- Token expired or rotated\n- Need to switch between GitHub accounts\n- Repository access permissions changed\n- Testing with different token scopes\n\n## Troubleshooting\n\n### 1Password CLI Not Found\n\n**Error:** `1Password CLI (op) is not installed`\n\n**Solution:**\n\n```bash\nbrew install 1password-cli\n```\n\nVerify installation:\n\n```bash\nop --version\n```\n\n### 1Password Authentication Timeout\n\n**Error:** `Timeout: 1Password authentication not completed within 30 seconds`\n\n**Causes:**\n\n- User didn''t approve 1Password prompt in time\n- 1Password app not running\n- 1Password CLI not authenticated\n\n**Solutions:**\n\n1. Ensure 1Password app is running\n2. Authenticate 1Password CLI:\n\n   ```bash\n   op account list\n   op signin\n   ```\n\n3. Run configure script again\n4. Approve 1Password prompt within 30 seconds\n\n### GITHUB_TOKEN Not Found in .env\n\n**Error:** `GITHUB_TOKEN not found in .env file`\n\n**Solution:**\n\nCreate or update `.env` file in project root:\n\n```bash\nGITHUB_TOKEN=op://Private/GitHub.com/GITHUB_TOKEN\n```\n\nVerify 1Password reference is correct:\n\n```bash\nop read op://Private/GitHub.com/GITHUB_TOKEN\n```\n\n### Invalid 1Password Reference\n\n**Error:** `1Password CLI failed: [error message]`\n\n**Solutions:**\n\n1. **Check vault name:** Ensure vault exists in 1Password\n\n   ```bash\n   op vault list\n   ```\n\n2. **Check item name:** Verify item exists in vault\n\n   ```bash\n   op item list --vault Private\n   ```\n\n3. **Check field name:** Confirm field exists in item\n\n   ```bash\n   op item get \"GitHub.com\" --vault Private\n   ```\n\n4. **Test reference directly:**\n\n   ```bash\n   op read op://Private/GitHub.com/GITHUB_TOKEN\n   ```\n\n### Tools Not Appearing After Configuration\n\n**Solutions:**\n\n1. Verify server shows \"✓ Connected\" in `claude mcp list`\n2. Restart Claude Code completely (not just terminal)\n3. Check `~/.claude.json` contains GitHub server config with headers\n4. Verify token has correct GitHub API permissions\n\n### \"No such tool available\" Error\n\n**Solutions:**\n\n1. Run pre-flight check (Step 1)\n2. Verify MCP server is configured: `claude mcp list`\n3. Check token validity: `op read op://...` and test with GitHub API\n4. Restart Claude Code after configuration\n\n### Plain Text Token Warning\n\n**Warning:** `Using plain text token from .env file`\n\n**Risk:** Token stored in plain text, visible to anyone with file access\n\n**Solution:**\n\nConvert to 1Password reference:\n\n1. Store token in 1Password\n2. Update .env:\n\n   ```bash\n   GITHUB_TOKEN=op://Private/GitHub.com/GITHUB_TOKEN\n   ```\n\n3. Run configure script again\n\n## Security Best Practices\n\n1. **NEVER commit .env file** - Add to `.gitignore`\n2. **NEVER commit .claude/mcp.json** - Already gitignored, contains tokens\n3. **Use 1Password references** - Never plain text tokens\n4. **Use local config for org-specific tokens** - Prevents cross-org token leakage\n5. **Rotate tokens regularly** - Use `--reauth` after rotation\n6. **Limit token scopes** - Grant only necessary permissions\n7. **Audit token usage** - Review GitHub token activity logs\n8. **Add allow patterns** - Use `--allow-patterns` to avoid accidental permission grants\n\n## Configuration Details\n\n### MCP Server Configuration\n\nThe script configures GitHub MCP as a remote HTTP server with bearer token authentication:\n\n**Global configuration (`~/.claude.json`):**\n\n```json\n{\n  \"mcpServers\": {\n    \"github\": {\n      \"type\": \"http\",\n      \"url\": \"https://api.githubcopilot.com/mcp/\",\n      \"headers\": {\n        \"Authorization\": \"Bearer ghp_xxxxxxxxxxxx\"\n      }\n    }\n  }\n}\n```\n\n**Local configuration (`.claude/mcp.json`):**\n\n```json\n{\n  \"mcpServers\": {\n    \"github\": {\n      \"type\": \"http\",\n      \"url\": \"https://api.githubcopilot.com/mcp/\",\n      \"headers\": {\n        \"Authorization\": \"Bearer ghp_organization_token\"\n      }\n    }\n  }\n}\n```\n\n**Server Details:**\n\n- **Type:** Remote HTTP MCP server\n- **Host:** GitHub-managed (official)\n- **Authentication:** Bearer token in Authorization header\n- **Endpoint:** `https://api.githubcopilot.com/mcp/`\n- **Token Source:** 1Password CLI (`op read`)\n\n### Allow Patterns Configuration\n\nThe `--allow-patterns` flag adds GitHub MCP tools to `~/.claude/settings.json`:\n\n```json\n{\n  \"allowedTools\": [\"mcp__github__*\"]\n}\n```\n\n**Benefits:**\n\n- No permission prompts for GitHub MCP tools\n- Faster workflow when using MCP tools frequently\n- Consistent experience across sessions\n\n## Related Skills\n\n- `atlassian-mcp` - Atlassian/Jira MCP integration (OAuth-based)\n- `secureai-mcp` - SecureAI task management and security controls\n\n## References\n\n- [GitHub MCP Server Repository](https://github.com/github/github-mcp-server)\n- [1Password CLI Documentation](https://developer.1password.com/docs/cli/)\n- [Model Context Protocol Specification](https://modelcontextprotocol.io)\n"},"lastSynced":"2026-03-08T01:59:49.947Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring seamless GitHub repository integration and secure token management via 1Password.","zh":"适用于需要无缝集成GitHub仓库和通过1Password安全令牌管理的开发人员代理。","ja":"GitHubリポジトリのシームレスな統合と1Passwordによるセキュアなトークン管理を必要とする開発者エージェントに適しています。","ko":"GitHub 리포지토리와 1Password를 통한 보안 토큰 관리가 필요한 개발자 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollador que requieren una integración de repositorio de GitHub sin problemas y una gestión de tokens segura a través de 1Password.","fr":"Idéal pour les agents de développement nécessitant une intégration de référentiel GitHub transparente et une gestion de jetons sécurisée via 1Password.","de":"Ideal für Entwicklungsagenten, die eine nahtlose GitHub-Repository-Integration und eine sichere Tokenverwaltung über 1Password erfordern.","pt":"Ideal para Agentes de Desenvolvedor que requerem integração de repositório do GitHub sem interrupções e gerenciamento de token seguro via 1Password.","ru":"Идеально для агентов разработчиков, требующих бесшовной интеграции с репозиторием GitHub и безопасного управления токенами через 1Password.","ar":"مثالي لعميل المطور الذي يتطلب تكامل مستودع GitHub بدون انقطاع وإدارة رموز آمنة عبر 1Password."},"recommendation":{"en":"Empowers agents to access GitHub repositories, issues, and workflows directly from Claude Code, utilizing secure token management via 1Password and facilitating content-addressed image storage through Cloudflare CDN with Azure backend, leveraging GitHub APIs and 1Password CLI for enhanced security.","zh":"赋予代理访问GitHub仓库、问题和工作流的能力，直接从Claude Code利用1Password的安全令牌管理，并通过Cloudflare CDN与Azure后端实现内容寻址的图像存储，利用GitHub API和1Password CLI增强安全性。","ja":"エージェントがGitHubリポジトリ、問題、ワークフローにアクセスできるようにし、Claude Codeから直接1Passwordのセキュアなトークン管理を利用し、Cloudflare CDNとAzureバックエンドを使用してコンテンツアドレッシングされたイメージのストレージを実現し、GitHub APIと1Password CLIを使用してセキュリティを強化します。","ko":"에이전트가 GitHub 리포지토리, 문제, 워크플ロー에 접근할 수 있도록 하며, Claude Code에서 직접 1Password의 보안 토큰 관리를 활용하고, Cloudflare CDN과 Azure 백엔드를 사용하여 콘텐츠 주소 지정된 이미지의 저장소를 구현하며, GitHub API와 1Password CLI를 사용하여 보안을 강화합니다.","es":"Habilita a los agentes para acceder a los repositorios, problemas y flujos de trabajo de GitHub directamente desde Claude Code, utilizando una gestión de tokens segura a través de 1Password y facilitando el almacenamiento de imágenes con direcciones de contenido a través de Cloudflare CDN con backend de Azure, aprovechando las GitHub APIs y la CLI de 1Password para una mayor seguridad.","fr":"Permet aux agents d''accéder aux référentiels, problèmes et flux de travail GitHub directement depuis Claude Code, en utilisant une gestion de jetons sécurisée via 1Password et en facilitant le stockage d''images à adresses de contenu via Cloudflare CDN avec un backend Azure, en exploitant les GitHub APIs et la CLI 1Password pour une sécurité renforcée.","de":"Ermöglicht es Agenten, auf GitHub-Repositorys, -Probleme und -Workflows direkt von Claude Code aus zuzugreifen, indem es eine sichere Tokenverwaltung über 1Password nutzt und den Speicher von inhaltsadressierten Bildern via Cloudflare CDN mit Azure-Backend erleichtert, wodurch GitHub-APIs und 1Password-CLI für erhöhte Sicherheit genutzt werden.","pt":"Habilita os agentes a acessar repositórios do GitHub, problemas e fluxos de trabalho diretamente do Claude Code, utilizando gerenciamento de token seguro via 1Password e facilitando o armazenamento de imagens com endereço de conteúdo por meio do Cloudflare CDN com backend do Azure, aproveitando as APIs do GitHub e 1Password CLI para segurança reforçada.","ru":"Наделяет агентов возможностью доступа к репозиториям GitHub, проблемам и рабочим процессам直接 из Claude Code, используя безопасное управление токенами через 1Password и облегчая хранение изображений с адресацией контента через Cloudflare CDN с бэкэндом Azure, используя API GitHub и 1Password CLI для повышения безопасности.","ar":"يمنح الوكلاء الوصول إلى مستودعات GitHub والقضايا والتدفقات العمل مباشرة من Claude Code، ويستخدم إدارة الرموز الآمنة عبر 1Password ويتسهل تخزين الصور المخاطب بالمحتوى عبر Cloudflare CDN مع خلفية Azure، ويستفيد من واجهات برمجة التطبيقات GitHub و1Password CLI لتعزيز الأمان."},"useCases":{"en":["Configuring MCP server integration for GitHub","Managing GitHub issues and pull requests programmatically","Deploying content-addressed images via Cloudflare CDN"],"zh":["为GitHub配置MCP服务器集成","程序化管理GitHub问题和拉取请求","通过Cloudflare CDN部署内容寻址的图像"],"ja":["GitHub用のMCPサーバー統合を構成する","GitHubの問題とプルリクエストをプログラム的に管理する","Cloudflare CDNを使用したコンテンツアドレッシングされたイメージのデプロイ"],"ko":["GitHub용 MCP 서버 통합 구성","GitHub 문제와 풀 리퀘스트를 프로그래밍 방식으로 관리","Cloudflare CDN을 사용한 콘텐츠 주소 지정된 이미지 배포"],"es":["Configuración de la integración del servidor MCP para GitHub","Administración de problemas y solicitudes de extracción de GitHub de forma programática","Implementación de imágenes con direcciones de contenido a través de Cloudflare CDN"],"fr":["Configuration de l''intégration du serveur MCP pour GitHub","Gestion des problèmes et des demandes d''extraction GitHub de manière programmatique","Déploiement d''images à adresses de contenu via Cloudflare CDN"],"de":["Konfiguration der MCP-Server-Integration für GitHub","Verwaltung von GitHub-Problemen und Pull-Requests programmgesteuert","Bereitstellung von inhaltsadressierten Bildern über Cloudflare CDN"],"pt":["Configurando a integração do servidor MCP para o GitHub","Gerenciando problemas e solicitações de pull do GitHub de forma programática","Implantando imagens com endereço de conteúdo via Cloudflare CDN"],"ru":["Настройка интеграции сервера MCP с GitHub","Управление проблемами и запросами на pull в GitHub программно","Развертывание изображений с адресацией контента через Cloudflare CDN"],"ar":["تكوين تكامل خادم MCP مع GitHub","إدارة القضايا والطلبات السحابية لجيت هاب بالبرمجة","نشر الصور المخاطب بالمحتوى عبر Cloudflare CDN"]},"limitations":{"en":["Requires 1Password CLI for secure token fetching","Dependent on GitHub API availability","Needs Azure backend for content storage"],"zh":["需要1Password CLI进行安全令牌获取","依赖于GitHub API的可用性","需要Azure后端进行内容存储"],"ja":["セキュアなトークンの取得には1Password CLIが必要","GitHub APIの可用性に依存","コンテンツストレージにはAzureバックエンドが必要"],"ko":["보안 토큰 가져오기에는 1Password CLI가 필요","GitHub API 가용성에 의존","콘텐츠 저장소에는 Azure 백엔드가 필요"],"es":["Requiere la CLI de 1Password para la recuperación segura de tokens","Dependiente de la disponibilidad de la API de GitHub","Necesita un backend de Azure para el almacenamiento de contenido"],"fr":["Nécessite la CLI 1Password pour la récupération sécurisée de jetons","Dépend de la disponibilité de l''API GitHub","Nécessite un backend Azure pour le stockage de contenu"],"de":["Benötigt die 1Password-CLI für die sichere Tokenabfrage","Hängt von der Verfügbarkeit der GitHub-API ab","Benötigt ein Azure-Backend für den Inhaltspeicher"],"pt":["Requer 1Password CLI para busca de token seguro","Depende da disponibilidade da API do GitHub","Necessita de backend do Azure para armazenamento de conteúdo"],"ru":["Требует 1Password CLI для безопасной загрузки токенов","Зависит от доступности API GitHub","Требует бэкэнда Azure для хранения контента"],"ar":["يتطلب 1Password CLI لاسترجاع الرموز الآمنة","يعتمد على توفر واجهة برمجة التطبيقات GitHub","يحتاج إلى خلفية Azure لتخزين المحتوى"]},"version":4},"contentHash":"de8ef5e53ff95d6f10b1f36ddb165aaf206d28deeecd37cdf1460754710b9d1a","qualityScore":60}');
