INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chandima/opencode-config/github-ops', 'github-ops', 'chandima', 'opencode-config', 'community', 'github-ops chandima opencode-config community The github-ops skill provides full GitHub MCP Server parity using the gh CLI, allowing developers to perform various operations such as repository management and issue tracking. This skill benefits developers who need to automate GitHub tasks. GitHub Ops 提供了使用 gh CLI 实现全功能 GitHub MCP 服务器的能力，支持存储库和问题管理 GitHub Ops は、gh CLI を使用してトークンオーバーヘッドのない完全な GitHub MCP サーバーを実現します GitHub Ops는 gh CLI를 사용하여 전체 GitHub MCP 서버를 제공합니다. 저장소 및 문제 관리 기능을 지원합니다 github-ops es una habilidad que proporciona funcionalidad de servidor MCP de GitHub utilizando el CLI de GitHub github-ops est une compétence qui fournit la fonctionnalité du serveur MCP GitHub en utilisant le CLI GitHub github-ops ist eine Fähigkeit, die die Funktionalität des GitHub-MCP-Servers mithilfe des GitHub-CLI bereitstellt O github-ops é uma habilidade que fornece paridade total com o servidor MCP do GitHub usando o CLI gh. Ele permite automatizar tarefas como gerenciamento de repositórios e issues. Github-ops - это навык, который обеспечивает полную паритетность с сервером MCP GitHub с помощью CLI gh. Он позволяет автоматизировать задачи, такие как управление репозиториями и проблемами. github-ops هو مهارة توفر مساواة كاملة مع خادم MCP لجيت هاب باستخدام CLI gh. يسمح بتحسين المهام مثل إدارة المستودعات والقضايا github-ops setup guide github-ops alternative how to use github-ops github-ops vs git github-ops install what is github-ops github-ops documentation github-ops tutorial github-ops benefits github-ops use cases GitHub Ops gh CLI GitHub MCP 服务器 存储库管理 问题管理 身份验证管理 AI代理 AI工具 Provides repository management capabilities using the repos.sh script Supports issue tracking and management using the issues.sh script Enables viewing, cloning, forking, listing, creating, and deleting repositories Allows listing, viewing, creating, closing, reopening, and commenting on issues Requires gh CLI installation and authentication using gh auth login Offers full GitHub MCP Server parity without token overhead github-ops is a skill that provides full GitHub MCP Server parity using the gh CLI, enabling developers to perform various GitHub operations without token overhead.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('taiyousan15/taisun_agent/world-research', 'community', 'taiyousan15', 'taisun_agent', 'taiyousan15/taisun_agent', 'world-research', 0, 0, 60, '2026-03-08T01:57:15.265Z', '2026-03-08T01:59:53.595Z', '53008d2b6185c6e9a7362285a86e40d8c9bfc35b6506b41343dba109180c56ef', '{"id":"taiyousan15/taisun_agent/world-research","name":"world-research","description":{"en":"The world-research skill provides a comprehensive research system, covering academic papers, community, and SNS research. It benefits researchers and developers seeking a complete research solution.","zh":"全球研究系统v2.0是一种完全网罗型的研究系统，涵盖论文、社区和SNS。它提供了一个全面的研究平台","ja":"ワールドリサーチシステムv2.0は、論文、コミュニティ、SNSを完全に網羅するリサーチシステムです","ko":"월드 리서치 시스템 v2.0은 논문, 커뮤니티, SNS를 완전하게 포함하는 리서치 시스템입니다","es":"World Research es un sistema de investigación integral que abarca artículos, comunidades y redes sociales. Ofrece una plataforma para la investigación completa.","fr":"World Research est un système de recherche complet qui couvre les articles, les communautés et les réseaux sociaux. Il propose une plateforme pour la recherche intégrale.","de":"World Research ist ein vollständiges Forschungssystem, das Artikel, Communities und soziale Netzwerke abdeckt. Es bietet eine Plattform für die umfassende Forschung.","pt":"O World Research é um sistema de pesquisa completo que integra papel, comunidade e mídias sociais. Ele oferece uma abordagem abrangente para a pesquisa.","ru":"World Research - это полная система исследования, объединяющая статью, сообщество и социальные сети. Она предоставляет комплексный подход к исследованию.","ar":"نظام البحث العالمي هو نظام بحث شامل يدمج البحث وال社区 والوسائط الاجتماعية. يقدم نهجًا شاملاً للبحث."},"seo":{"title":{"en":"world-research: Comprehensive Research System Setup Guide...","zh":"全球研究系统v2.0配置指南 - World Research Setup Guide","ja":"ワールドリサーチシステムv2.0のベストプラクティス - World Research Best Practices","ko":"월드 리서치 시스템 v2.0 설정 가이드 - World Research Setup Guide","es":"Guía de configuración de World Research - Sistema de inve...","fr":"Guide d''installation de World Research - Système de reche...","de":"Einrichtungsleitfaden für World Research - Vollständiges ...","pt":"Guia de Configuração do World Research - Sistema de Pesqu...","ru":"Настройка World Research - Полная Система Исследования v2.0","ar":"دليل إعداد نظام البحث العالمي - نظام بحث شامل v2.0"},"description":{"en":"Unlock the full potential of world-research, a complete research system. Discover how to leverage its features for your research needs and get started today!","zh":"了解全球研究系统v2.0的技术细节，包括论文、社区和SNS的完全网罗型研究","ja":"ワールドリサーチシステムv2.0の技術的な概要を紹介。論文、コミュニティ、SNSを網羅するリサーチ","ko":"월드 리서치 시스템 v2.0의 기술적인 세부 사항을 알아보세요. 논문, 커뮤니티, SNS를 포함한 완전한 리서치","es":"Descubre cómo configurar World Research, un sistema de investigación que abarca artículos, comunidades y redes sociales. Mejora tus habilidades de investigac...","fr":"Découvrez comment installer World Research, un système de recherche qui couvre les articles, les communautés et les réseaux sociaux. Améliorez vos compétence...","de":"Erfahren Sie, wie Sie World Research einrichten, ein Forschungssystem, das Artikel, Communities und soziale Netzwerke abdeckt. Verbessern Sie Ihre Forschungs...","pt":"Aprenda a configurar o World Research, um sistema de pesquisa completo que integra papel, comunidade e mídias sociais. Descubra como otimizar seu uso.","ru":"Узнайте, как настроить World Research, полную систему исследования, объединяющую статью, сообщество и социальные сети. Откройте для себя, как оптимизировать ...","ar":"تعرف على كيفية إعداد نظام البحث العالمي، نظام بحث شامل يدمج البحث وال社区 والوسائط الاجتماعية. اكتشف كيفية تحسين استخدامه."},"definition":{"en":"world-research is a fully comprehensive research system that integrates academic papers, community, and SNS research capabilities.","zh":"全球研究系统v2.0是一种AIエージェント，用于进行全面的研究和分析","ja":"ワールドリサーチシステムv2.0は、AIエージェントの一種で、総合的なリサーチと分析を行う","ko":"월드 리서치 시스템 v2.0은 AI 툴의 일종으로, 완전한 리서치와 분석을 수행한다","es":"World Research es un sistema de investigación que combina artículos, comunidades y redes sociales para ofrecer una plataforma de investigación integral.","fr":"World Research est un système de recherche qui combine les articles, les communautés et les réseaux sociaux pour proposer une plateforme de recherche complète.","de":"World Research ist ein Forschungssystem, das Artikel, Communities und soziale Netzwerke kombiniert, um eine Plattform für die umfassende Forschung zu bieten.","pt":"O que é World Research? É um sistema de pesquisa completo que integra papel, comunidade e mídias sociais para uma abordagem abrangente.","ru":"Что такое World Research? Это полная система исследования, объединяющая статью, сообщество и социальные сети для комплексного подхода.","ar":"ما هو نظام البحث العالمي؟ هو نظام بحث شامل يدمج البحث وال社区 والوسائط الاجتماعية لنهج شامل."},"features":{"en":["Integrates academic papers for in-depth research","Covers community research for diverse perspectives","Supports SNS research for real-time data collection","Provides a complete research solution for researchers and developers","Includes a comprehensive research system v2.0","Enables complete network coverage for thorough research"],"zh":["论文网罗型研究","社区分析功能","SNS数据收集","完全网罗型研究平台","支持多种数据格式","高性能的数据处理能力"],"ja":["論文を網羅するリサーチ","コミュニティ分析機能","SNSデータの収集","完全網羅型のリサーチプラットフォーム","多種のデータ形式をサポート","高性能のデータ処理能力"],"ko":["논문을 포함한 완전한 리서치","커뮤니티 분석 기능","SNS 데이터 수집","완전한 리서치 플랫폼","다양한 데이터 형식을 지원","고성능의 데이터 처리 능력"],"es":["Cobertura completa de artículos y publicaciones","Análisis de comunidades y redes sociales","Plataforma integral para la investigación","Compatibilidad con múltiples fuentes de datos","Interfaz de usuario intuitiva y personalizable"],"fr":["Couverture complète des articles et des publications","Analyse des communautés et des réseaux sociaux","Plateforme intégrale pour la recher