INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('taiyousan15/taisun_agent/world-research', 'world-research', 'taiyousan15', 'taisun_agent', 'community', 'world-research taiyousan15 taisun_agent community The world-research skill provides a comprehensive research system, covering academic papers, community, and SNS research. It benefits researchers and developers seeking a complete research solution. 全球研究系统v2.0是一种完全网罗型的研究系统，涵盖论文、社区和SNS。它提供了一个全面的研究平台 ワールドリサーチシステムv2.0は、論文、コミュニティ、SNSを完全に網羅するリサーチシステムです 월드 리서치 시스템 v2.0은 논문, 커뮤니티, SNS를 완전하게 포함하는 리서치 시스템입니다 World Research es un sistema de investigación integral que abarca artículos, comunidades y redes sociales. Ofrece una plataforma para la investigación completa. World Research est un système de recherche complet qui couvre les articles, les communautés et les réseaux sociaux. Il propose une plateforme pour la recherche intégrale. World Research ist ein vollständiges Forschungssystem, das Artikel, Communities und soziale Netzwerke abdeckt. Es bietet eine Plattform für die umfassende Forschung. O World Research é um sistema de pesquisa completo que integra papel, comunidade e mídias sociais. Ele oferece uma abordagem abrangente para a pesquisa. World Research - это полная система исследования, объединяющая статью, сообщество и социальные сети. Она предоставляет комплексный подход к исследованию. نظام البحث العالمي هو نظام بحث شامل يدمج البحث وال社区 والوسائط الاجتماعية. يقدم نهجًا شاملاً للبحث. how to use world-research world-research alternative world-research setup guide what is world-research world-research vs research tools world-research install comprehensive research system academic paper research SNS research tools community research methods 全球研究系统 AIエージェント 论文网罗型研究 社区分析 SNS数据收集 完全网罗型研究平台 数据处理 高性能计算 Integrates academic papers for in-depth research Covers community research for diverse perspectives Supports SNS research for real-time data collection Provides a complete research solution for researchers and developers Includes a comprehensive research system v2.0 Enables complete network coverage for thorough research world-research is a fully comprehensive research system that integrates academic papers, community, and SNS research capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brenbuilds1/copilot-ralph/prd-generator', 'community', 'brenbuilds1', 'copilot-ralph', 'brenbuilds1/copilot-ralph', 'prd-generator', 0, 0, 60, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:10.565Z', '7305fe677f6548f915aab760770e1a11628ccd95c2b903a33ba37ef6ade8ae3f', '{"id":"brenbuilds1/copilot-ralph/prd-generator","name":"prd-generator","description":{"en":"The prd-generator skill creates detailed Product Requirements Documents for autonomous implementation by Ralph. It receives feature descriptions, asks clarifying questions, and generates structured PRDs saved to prd.json.","zh":"prd-generator 是一个自动化的 AI 代理循环，生成详细的产品需求文档，以实现自动化的开发流程","ja":"prd-generator は、自動化された AI エージェント ループであり、自動実装可能な詳細な PRD を生成します","ko":"prd-generator는 자동화된 AI 에이전트 루프로自動구현 가능한 상세한 제품 요구 사항 문서를 생성합니다","es":"El generador de PRD de Copilot es un agente de inteligencia artificial que crea documentos de requisitos de producto claros y detallados. Recibe descripciones de funciones y genera PRD estructurados","fr":"Le générateur de PRD de Copilot est un agent d''intelligence artificielle qui crée des documents de spécifications de produit clairs et détaillés. Il reçoit des descriptions de fonctionnalités et génère des PRD structurés","de":"Der PRD-Generator von Copilot ist ein künstlicher Intelligenzagent, der klare und detaillierte Produktanforderungsdokumente erstellt. Er erhält Funktionsbeschreibungen und generiert strukturierte PRD","pt":"O PRD Generator é um agente de inteligência artificial que cria documentos de requisitos de produto detalhados e executáveis de forma autônoma.","ru":"PRD Генератор - это ИИ Агент, создающий подробные технические требования к продукту, пригодные для автономной реализации.","ar":"مولد مواصفات المنتج هو أداة ذكاء اصطناعي تنتج وثائق متطلبات المنتج المفصلة والقابلة للتنفيذ بطريقة tự động"},"seo":{"title":{"en":"prd-generator: Automated PRD Creation for AI Agents | AI ...","zh":"prd-generator 设置指南：自动化产品需求文档生成","ja":"prd-generator セットアップガイド：AIエージェントによる自動化PRD生成","ko":"prd-generator 설정 가이드: 자동화된 제품 요구 사항 문서 생성","es":"Guía de configuración del generador de PRD de Copilot","fr":"Guide d''installation du générateur de PRD de Copilot","de":"Einrichtungsanleitung für den PRD-Generator von Copilot","pt":"Guia de Configuração do PRD Generator - Crie Documentos d...","ru":"Настройка PRD Генератора - Создайте Подробные Технические...","ar":"دليل إعداد مولد مواصفات المنتج - إنشاء وثائق متطلبات المن..."},"description":{"en":"Discover how prd-generator simplifies Product Requirements Document creation. Learn to set up and use this AI agent skill to streamline your development work...","zh":"使用 prd-generator 自动生成详细的产品需求文档，实现自动化和高效的开发流程","ja":"prd-generator を使用して詳細な PRD を自動生成し、開発プロセスを自動化して効率化します","ko":"prd-generator를 사용하여 자동으로 상세한 제품 요구 사항 문서를 생성하여 개발 프로세스를 자동화하고 효율화합니다","es":"Aprende a configurar el generador de PRD de Copilot para crear documentos de requisitos de producto detallados y claros","fr":"Découvrez comment installer le générateur de PRD de Copilot pour créer des documents de spécifications de produit détaillés et clairs","de":"Erfahren Sie, wie Sie den PRD-Generator von Copilot einrichten, um detaillierte und klare Produktanforderungsdokumente zu erstellen","pt":"Aprenda a configurar o PRD Generator para criar documentos de requisitos de produto claros e executáveis de forma autônoma com o auxílio de ferramentas de in...","ru":"Узнайте, как настроить PRD Генератор для создания подробных технических требований к продукту, пригодных для автономной реализации с помощью ИИ Агентов","ar":"تعلم كيفية إعداد مولد مواصفات المنتج لإنشاء وثائق متطلبات المنتج الواضحة والقابلة للتنفيذ بطريقة tự động مع أدوات الذكاء الاصطناعي"},"definition":{"en":"prd-generator is an autonomous AI agent loop that creates detailed Product Requirements Documents based on user input and clarifying questions.","zh":"prd-generator 是一种自动化工具，用于生成详细的产品需求文档","ja":"prd-generator は、詳細な PRD を自動生成する AI エージェントです","ko":"prd-generator는 상세한 제품 요구 사항 문서를 자동으로 생성하는 도구입니다","es":"Un generador de PRD es una herramienta de inteligencia artificial que crea documentos de requisitos de producto","fr":"Un générateur de PRD est un outil d''intelligence artificielle qui crée des documents de spécifications de produit","de":"Ein PRD-Generator ist ein künstlicher Intelligenzagent, der Produktanforderungsdokumente erstellt","pt":"O que é PRD Generator? É um agente de inteligência artificial que cria documentos de requisitos de produto autônomos.","ru":"Что такое PRD Генератор? Это ИИ Агент, создающий технические требования к продукту для автономной реализации.","ar":"ما هو مولد مواصفات المنتج? هو أداة ذكاء اصطناعي لإنشاء وثائق متطلبات المنتج المحددة"},"features":{"en":["Receives feature descriptions from users","Asks 3-5 essential clarifying questions with lettered options","Generates structured PRDs based on user answers","Saves PRDs to prd.json in the project root","Creates PRDs suitable for autonomous implementation by Ralph"],"zh":["接收用户的功能描述","提出 3-5 个关键的澄清问题","生成结构化的 PRD 文档","保存到项目根目录的 prd.json 文件中"],"ja":["ユーザーからの機能説明を受け取る","3-5 個の重要な明確化質問を出す","構造化された PRD ドキュメントを生成する","プロジェクトルートの prd.json ファイルに保存する"],"ko":["사용자의 기능 설명을 받습니다","3-5개의 중요한澄清 질문을 합니다","구조화된 제품 요구 사항 문서를 생성합니다","프로젝트 루트의 prd.json 파일에 저장합니다"],"es":["Recibe descripciones de funciones del usuario","Hace 3-5 preguntas esenciales para aclarar","Genera PRD estructurados en función de las respuestas","Guarda el PRD en un archivo `prd.json` en la raíz del proyecto","No implementa, solo crea el PRD"],"fr":["Reçoit des descriptions de fonctionnalités de l''utilisateur","Pose 3-5 questions essentielles pour clarifier","Génère des PRD structurés en fonction des réponses","Enregistre le PRD dans un fichier `prd.json` à la racine du projet","Ne met pas en œuvre, crée seulement le PRD"],"de":["Erhält Funktionsbeschreibungen vom Benutzer","Stellt 3-5 essentielle Fragen zur Klarstellung","Generiert strukturierte PRD basierend auf den Antworten","Speichert die PRD in einer Datei `prd.json` im Projektverzeichnis","Implementiert nicht, erstellt nur die PRD"],"pt":["Recebe descrição de recurso do usuário","Faz 3-5 perguntas essenciais de esclarecimento","Gera documento de requisitos de produto estruturado","Salva em `prd.json` na raiz do projeto"],"ru":["Получает описание функции от пользователя","Задает 3-5 важных вопросов для уточнения","Генерирует структурированный документ требований к продукту","Сохраняет в `prd.json` в корне проекта"],"ar":["يستقبل وصف الميزة من المستخدم","يطرح 3-5 أسئلة أساسية لتوضيح","ينتج وثيقة متطلبات المنتج المنظمة","يحفظ في `prd.json` في جذور المشروع"]},"keywords":{"en":["how to use prd-generator","prd-generator setup guide","what is prd-generator","prd-generator alternative","prd-generator vs manual PRD creation","prd-generator install","automated PRD creation","AI agent skills for development","Product Requirements Document generation"],"zh":["prd-generator","AI 代理","自动化开发","产品需求文档","prd.json","自动化工具","开发流程"],"ja":["prd-generator","AIエージェント","自動化開発","PRD","prd.json","自動化ツール","開発プロセス"],"ko":["prd-generator","AI 에이전트","자동화 개발","제품 요구 사항 문서","prd.json","자동화 도구","개발 프로세스"],"es":["generador de PRD","herramientas de inteligencia artificial","documentos de requisitos de producto","desarrollo de software","ingeniería de software","prd generator","ai tools","product requirements document"],"fr":["générateur de PRD","outils d''intelligence artificielle","documents de spécifications de produit","développement de logiciels","ingénierie de logiciels","prd generator","ai tools","product requirements document"],"de":["PRD-Generator","künstliche Intelligenztools","Produktanforderungsdokumente","Softwareentwicklung","Softwareingenieurwesen","prd generator","ai tools","product requirements document"],"pt":["prd generator","ferramentas de inteligência artificial","documentos de requisitos de produto","automação de processo","desenvolvimento de software","prd json"],"ru":["prd генератор","ИИ Агенты","технические требования к продукту","автоматизация процесса","разработка программного обеспечения","prd json"],"ar":["مولد مواصفات المنتج","أدوات الذكاء الاصطناعي","وثائق متطلبات المنتج","تأتمة العملية","تطوير البرمجيات","prd json"]}},"owner":"brenbuilds1","repo":"copilot-ralph","repoPath":"brenbuilds1/copilot-ralph","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.270Z","topics":[],"category":"community","skillMd":{"name":"prd-generator","description":"Generate a Product Requirements Document (prd.json) for the Ralph autonomous agent loop. Use when planning a feature, starting a new project, or preparing work for Ralph to implement. Triggers on: create a prd, write prd for, plan this feature, generate user stories, set up ralph for, spec out.","bodyPreview":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for autonomous implementation by Ralph.\n\n---\n\n## The Job\n\n1. Receive a feature description from the user\n2. Ask 3-5 essential clarifying questions (with lettered options)\n3. Generate a structured PRD based on answers\n4. Save to `prd.json` in project root\n\n**Important:** Do NOT start implementing. Just create the PRD.\n\n---\n\n## Step 1: Clarifying Questions\n\nAsk only critical questions where the","body":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for autonomous implementation by Ralph.\n\n---\n\n## The Job\n\n1. Receive a feature description from the user\n2. Ask 3-5 essential clarifying questions (with lettered options)\n3. Generate a structured PRD based on answers\n4. Save to `prd.json` in project root\n\n**Important:** Do NOT start implementing. Just create the PRD.\n\n---\n\n## Step 1: Clarifying Questions\n\nAsk only critical questions where the initial prompt is ambiguous. Focus on:\n\n- **Problem/Goal:** What problem does this solve? Why build this?\n- **Core Functionality:** What are the key user actions?\n- **Scope/Boundaries:** What should it NOT do?\n- **Technology:** What stack/framework to use?\n- **Success Criteria:** How do we know it''s done?\n\n### Format Questions Like This:\n\n```\n1. What is the primary goal of this feature?\n   A. Improve user onboarding experience\n   B. Increase user retention\n   C. Reduce support burden\n   D. Other: [please specify]\n\n2. Who is the target user?\n   A. New users only\n   B. Existing users only\n   C. All users\n   D. Admin users only\n\n3. What is the scope?\n   A. Minimal viable version (MVP)\n   B. Full-featured implementation\n   C. Just the backend/API\n   D. Just the UI/frontend\n\n4. What technology stack?\n   A. React + Node.js\n   B. Next.js\n   C. Plain HTML/CSS/JS\n   D. Other: [please specify]\n\n5. What''s explicitly OUT of scope?\n   A. Authentication/login\n   B. Database persistence\n   C. Mobile responsiveness\n   D. None of the above - include everything\n```\n\nThis lets users respond with \"1A, 2C, 3A, 4B, 5A\" for quick iteration.\n\n---\n\n## Step 2: Break Down Into User Stories\n\nAfter gathering answers, break the feature into small, focused user stories.\n\n### Story Size Rule\n\nEach story must be **small enough to complete in one Ralph iteration** (one agent context window, ~15-30 minutes of focused work).\n\n**Good story sizes:**\n- Add a single component\n- Create one API endpoint\n- Add form validation\n- Create a database migration\n- Wire up frontend to API\n\n**Too large (must split):**\n- \"Build the dashboard\" → Split into: layout, sidebar, header, each widget\n- \"Add authentication\" → Split into: login form, API endpoint, session handling, protected routes\n- \"Create the API\" → Split into: one endpoint per story\n\n### Story Format\n\nEach story needs:\n- **id:** Unique identifier (US-001, US-002, etc.)\n- **title:** Short action-oriented name\n- **priority:** Order of implementation (1 = first)\n- **description:** Context for implementation - what and why\n- **acceptanceCriteria:** Verifiable checklist of \"done\"\n\n### Writing Good Acceptance Criteria\n\nCriteria must be **specific and verifiable**, not vague.\n\n**Bad (too vague):**\n- \"Works correctly\"\n- \"Handles errors\"\n- \"Is responsive\"\n- \"Looks good\"\n\n**Good (specific and testable):**\n- \"Form shows red border and error message when email format is invalid\"\n- \"API returns 400 status with `{ error: ''Invalid email'' }` for malformed input\"\n- \"Button is disabled and shows spinner while request is in flight\"\n- \"Cards stack vertically on screens < 768px wide\"\n\n### Standard Criteria to Include\n\nFor every story, include relevant items from:\n- \"Typecheck passes\" (if using TypeScript)\n- \"Lint passes\"\n- \"No console errors in browser\"\n\nFor UI stories, always include:\n- \"Visually verified in browser\"\n- Specific responsive behavior if applicable\n\nFor API stories, always include:\n- Success response format\n- Error response format\n- Edge cases (duplicate, not found, etc.)\n\n---\n\n## Step 3: Define Non-Goals\n\nExplicitly state what this PRD will NOT include. This prevents scope creep and sets clear boundaries.\n\nExamples:\n- \"No user authentication - assumes public access\"\n- \"No email notifications\"\n- \"No mobile app - web only\"\n- \"No analytics tracking\"\n\n---\n\n## Step 4: Order by Dependencies\n\nArrange stories so foundations come first:\n\n1. **Priority 1-2:** Setup, scaffolding, database schema\n2. **Priority 3-5:** Core functionality, main features\n3. **Priority 6+:** Enhancements, polish, nice-to-haves\n\nA story cannot depend on a higher-numbered story.\n\n---\n\n## Writing for Junior Developers and AI Agents\n\nThe PRD reader may be a junior developer or AI agent (Ralph). Therefore:\n\n- Be explicit and unambiguous\n- Avoid jargon or explain technical terms\n- Provide enough detail to understand purpose and implementation approach\n- Use concrete examples where helpful\n- Each acceptance criterion should be independently verifiable\n\n---\n\n## Output Format\n\nSave as `prd.json` in the project root:\n\n```json\n{\n  \"projectName\": \"Feature Name\",\n  \"branchName\": \"ralph/feature-name\",\n  \"description\": \"Brief description of the feature and problem it solves\",\n  \"userStories\": [\n    {\n      \"id\": \"US-001\",\n      \"title\": \"Short action-oriented title\",\n      \"priority\": 1,\n      \"description\": \"Detailed context: what to build and why. Include relevant technical details.\",\n      \"acceptanceCriteria\": [\n        \"Specific verifiable criterion\",\n        \"Another specific criterion\",\n        \"Typecheck passes\"\n      ],\n      \"passes\": false\n    }\n  ]\n}\n```\n\n**Fields:**\n- `projectName`: Human-readable feature name\n- `branchName`: Git branch (convention: `ralph/kebab-case-name`)\n- `description`: Overview of the feature and problem it solves\n- `userStories`: Array of stories, ordered by priority\n- `passes`: Always `false` initially (Ralph sets to `true` when complete)\n\n---\n\n## Example PRD\n\n```json\n{\n  \"projectName\": \"Task Priority System\",\n  \"branchName\": \"ralph/task-priority\",\n  \"description\": \"Add priority levels to tasks so users can focus on what matters most. Tasks can be marked as high, medium, or low priority with visual indicators and filtering.\",\n  \"userStories\": [\n    {\n      \"id\": \"US-001\",\n      \"title\": \"Add priority field to database schema\",\n      \"priority\": 1,\n      \"description\": \"Add a priority column to the tasks table to persist priority across sessions. Priority should be an enum of ''high'', ''medium'', or ''low'' with ''medium'' as the default.\",\n      \"acceptanceCriteria\": [\n        \"Migration adds priority column to tasks table\",\n        \"Column type is enum: ''high'' | ''medium'' | ''low''\",\n        \"Default value is ''medium''\",\n        \"Migration runs without errors\",\n        \"Existing tasks get ''medium'' priority\"\n      ],\n      \"passes\": false\n    },\n    {\n      \"id\": \"US-002\",\n      \"title\": \"Display priority badge on task cards\",\n      \"priority\": 2,\n      \"description\": \"Show a colored badge on each task card indicating its priority level. Users should see priority at a glance without hovering or clicking.\",\n      \"acceptanceCriteria\": [\n        \"Each task card shows a priority badge\",\n        \"High priority: red badge with ''High'' text\",\n        \"Medium priority: yellow badge with ''Medium'' text\",\n        \"Low priority: gray badge with ''Low'' text\",\n        \"Badge is visible without interaction\",\n        \"Typecheck passes\",\n        \"Visually verified in browser\"\n      ],\n      \"passes\": false\n    },\n    {\n      \"id\": \"US-003\",\n      \"title\": \"Add priority selector to task edit form\",\n      \"priority\": 3,\n      \"description\": \"Allow users to change a task''s priority when editing it. The selector should show the current priority and save changes immediately.\",\n      \"acceptanceCriteria\": [\n        \"Priority dropdown appears in task edit modal\",\n        \"Dropdown shows all three options: High, Medium, Low\",\n        \"Current priority is pre-selected\",\n        \"Selection change saves to database immediately\",\n        \"UI updates to reflect new priority without page reload\",\n        \"Typecheck passes\",\n        \"Visually verified in browser\"\n      ],\n      \"passes\": false\n    },\n    {\n      \"id\": \"US-004\",\n      \"title\": \"Add priority filter to task list\",\n      \"priority\": 4,\n      \"description\": \"Add a filter dropdown to the task list header so users can view only tasks of a specific priority level.\",\n      \"acceptanceCriteria\": [\n        \"Filter dropdown in task list header\",\n        \"Options: All, High, Medium, Low\",\n        \"Selecting a filter shows only matching tasks\",\n        \"Filter state persists in URL query params\",\n        \"Shows ''No tasks found'' when filter has no matches\",\n        \"Typecheck passes\",\n        \"Visually verified in browser\"\n      ],\n      \"passes\": false\n    }\n  ]\n}\n```\n\n---\n\n## After Generation\n\nTell the user:\n\n```\nPRD saved to prd.json\n\nTo start Ralph:\n  ./ralph.sh\n\nTo check story status:\n  cat prd.json | jq ''.userStories[] | {id, title, passes}''\n```\n\n---\n\n## Checklist\n\nBefore saving the PRD:\n\n- [ ] Asked 3-5 clarifying questions with lettered options\n- [ ] Incorporated user''s answers into the PRD\n- [ ] Each user story is small enough for one iteration\n- [ ] Stories are ordered by dependency (foundations first)\n- [ ] Acceptance criteria are specific and verifiable (not vague)\n- [ ] Non-goals/scope boundaries are clear from description\n- [ ] Branch name follows `ralph/feature-name` convention\n- [ ] All stories have `\"passes\": false`\n- [ ] Saved to `prd.json`\n"},"lastSynced":"2026-03-08T02:00:10.565Z","agentAnalysis":{"suitability":{"en":"Perfect for Autonomous Agents needing structured Product Requirements Document generation for Ralph implementation.","zh":"适合需要为Ralph实现生成结构化产品需求文档的自主代理。","ja":"Ralphの実装のために構造化された製品要件文書を生成する必要がある自律エージェントに適しています。","ko":"Ralph 구현을 위한 구조화된 제품 요구 사항 문서를 생성해야 하는 자율 에이전트에 적합합니다.","es":"Perfecto para Agentes Autónomos que necesitan generar documentos de requisitos de producto estructurados para la implementación de Ralph.","fr":"Parfait pour les Agents Autonomes ayant besoin de générer des documents de spécifications de produit structurés pour la mise en œuvre de Ralph.","de":"Perfekt für autonome Agenten, die strukturierte Produktanforderungsdokumente für die Implementierung von Ralph benötigen.","pt":"Perfeito para Agentes Autônomos que necessitam de geração de Documento de Requisitos de Produto estruturado para implementação do Ralph.","ru":"Идеально подходит для автономных агентов, которым требуется генерация структурированного документа требований продукта для реализации Ralph.","ar":"مثالي للوكلاء الأوتوماتيكيين الذين يحتاجون إلى توليد وثيقة متطلبات المنتج المحددة لتنفيذ رالف."},"recommendation":{"en":"Empowers agents to generate clear, actionable PRDs in JSON format, utilizing feature descriptions and clarifying questions to create comprehensive project requirements, saved to prd.json.","zh":"赋予代理生成清晰、可行的PRD，采用JSON格式，利用功能描述和澄清问题创建全面项目需求，保存到prd.json。","ja":"エージェントがJSON形式で明確で実行可能なPRDを生成できるようにします。機能説明と明確化する質問を使用して、包括的なプロジェクト要件を作成し、prd.jsonに保存します。","ko":"에이전트가 JSON 형식으로 명확하고 실행 가능한 PRD를 생성 할 수 있도록 합니다. 기능 설명과 澄清하는 질문을 사용하여 포괄적인 프로젝트 요구 사항을 생성하고 prd.json에 저장합니다.","es":"Habilita a los agentes a generar PRDs claros y ejecutables en formato JSON, utilizando descripciones de características y preguntas aclaratorias para crear requisitos de proyecto comprehensivos, guardados en prd.json.","fr":"Permet aux agents de générer des PRDs clairs et exécutables au format JSON, en utilisant des descriptions de fonctionnalités et des questions de clarification pour créer des exigences de projet complètes, enregistrées dans prd.json.","de":"Ermächtigt die Agenten, klare und ausführbare PRDs im JSON-Format zu generieren, indem sie Beschreibungen von Funktionen und Klarstellungsfragen verwenden, um umfassende Projektanforderungen zu erstellen, die in prd.json gespeichert werden.","pt":"Habilita os agentes a gerar PRDs claros e funcionais no formato JSON, utilizando descrições de recursos e perguntas esclarecedoras para criar requisitos de projeto abrangentes, salvos em prd.json.","ru":"Наделяет агентов возможностью генерировать четкие и действенные PRD в формате JSON, используя описания функций и уточняющие вопросы для создания всесторонних требований проекта, сохраняемых в prd.json.","ar":"يتمكن الوكلاء من توليد وثائق متطلبات المنتج واضحة و قابلة للتنفيذ بصيغة JSON، باستخدام وصفات الميزات و الأسئلة التوضيحية لإنشاء متطلبات مشروع شاملة، محفوظة في prd.json."},"useCases":{"en":["Generating detailed PRDs for autonomous implementation","Creating structured project requirements from feature descriptions","Automating PRD creation with clarifying questions"],"zh":["为自主实现生成详细的PRD","从功能描述创建结构化的项目需求","使用澄清问题自动化PRD创建"],"ja":["自律実装のための詳細なPRDを生成する","機能説明から構造化されたプロジェクト要件を作成する","明確化する質問を使用してPRDの作成を自動化する"],"ko":["자율 구현을 위한詳細한 PRD 생성","기능 설명에서 구조화된 프로젝트 요구 사항 생성"," 澄清하는 질문을 사용하여 PRD 생성 자동화"],"es":["Generar PRDs detallados para implementación autónoma","Crear requisitos de proyecto estructurados a partir de descripciones de características","Automatizar la creación de PRD con preguntas aclaratorias"],"fr":["Générer des PRDs détaillés pour la mise en œuvre autonome","Créer des exigences de projet structurées à partir de descriptions de fonctionnalités","Automatiser la création de PRD avec des questions de clarification"],"de":["Erstellen detaillierter PRDs für autonome Implementierung","Erstellen strukturierter Projektanforderungen aus Funktionsbeschreibungen","Automatisieren der PRD-Erstellung mit Klarstellungsfragen"],"pt":["Geração de PRDs detalhados para implementação autônoma","Criação de requisitos de projeto estruturados a partir de descrições de recursos","Automação da criação de PRD com perguntas esclarecedoras"],"ru":["Генерация подробных PRD для автономной реализации","Создание структурированных требований проекта на основе описаний функций","Автоматизация создания PRD с помощью уточняющих вопросов"],"ar":["توليد وثائق متطلبات المنتج مفصلة للتنفيذ الأوتوماتيكي","إنشاء متطلبات مشروع منظم من وصفات الميزات","آليّة إنشاء وثائق متطلبات المنتج باستخدام الأسئلة التوضيحية"]},"limitations":{"en":["Requires feature descriptions as input","Limited to generating PRDs for Ralph implementation","Does not support implementation, only PRD generation"],"zh":["需要功能描述作为输入","仅限于为Ralph实现生成PRD","不支持实现，只支持PRD生成"],"ja":["機能説明を入力として必要とする","Ralphの実装のためのPRDの生成のみに限定される","実装はサポートせず、PRDの生成のみサポートする"],"ko":["기능 설명을 입력으로 필요로 함","Ralph 구현을 위한 PRD 생성만 제한함","구현은 지원하지 않고, PRD 생성만 지원함"],"es":["Requiere descripciones de características como entrada","Limitado a la generación de PRDs para la implementación de Ralph","No admite la implementación, solo la generación de PRD"],"fr":["Nécessite des descriptions de fonctionnalités comme entrée","Limité à la génération de PRDs pour la mise en œuvre de Ralph","Ne prend pas en charge la mise en œuvre, uniquement la génération de PRD"],"de":["Benötigt Funktionsbeschreibungen als Eingabe","Begrenzt auf die Generierung von PRDs für die Implementierung von Ralph","Unterstützt keine Implementierung, nur die PRD-Generierung"],"pt":["Requer descrições de recursos como entrada","Limitado a gerar PRDs para implementação do Ralph","Não suporta implementação, apenas geração de PRD"],"ru":["Требует описаний функций в качестве входных данных","Ограничен генерацией PRD для реализации Ralph","Не поддерживает реализацию, только генерацию PRD"],"ar":["يتطلب وصفات الميزات كمدخلات","محدود بتوليد وثائق متطلبات المنتج لتنفيذ رالف","لا يدعم التنفيذ، بل توليد وثائق متطلبات المنتج فقط"]},"version":4},"contentHash":"7305fe677f6548f915aab760770e1a11628ccd95c2b903a33ba37ef6ade8ae3f","qualityScore":60}');
