INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brenbuilds1/copilot-ralph/prd-generator', 'prd-generator', 'brenbuilds1', 'copilot-ralph', 'community', 'prd-generator brenbuilds1 copilot-ralph community The prd-generator skill creates detailed Product Requirements Documents for autonomous implementation by Ralph. It receives feature descriptions, asks clarifying questions, and generates structured PRDs saved to prd.json. prd-generator 是一个自动化的 AI 代理循环，生成详细的产品需求文档，以实现自动化的开发流程 prd-generator は、自動化された AI エージェント ループであり、自動実装可能な詳細な PRD を生成します prd-generator는 자동화된 AI 에이전트 루프로自動구현 가능한 상세한 제품 요구 사항 문서를 생성합니다 El generador de PRD de Copilot es un agente de inteligencia artificial que crea documentos de requisitos de producto claros y detallados. Recibe descripciones de funciones y genera PRD estructurados Le générateur de PRD de Copilot est un agent d''intelligence artificielle qui crée des documents de spécifications de produit clairs et détaillés. Il reçoit des descriptions de fonctionnalités et génère des PRD structurés Der PRD-Generator von Copilot ist ein künstlicher Intelligenzagent, der klare und detaillierte Produktanforderungsdokumente erstellt. Er erhält Funktionsbeschreibungen und generiert strukturierte PRD O PRD Generator é um agente de inteligência artificial que cria documentos de requisitos de produto detalhados e executáveis de forma autônoma. PRD Генератор - это ИИ Агент, создающий подробные технические требования к продукту, пригодные для автономной реализации. مولد مواصفات المنتج هو أداة ذكاء اصطناعي تنتج وثائق متطلبات المنتج المفصلة والقابلة للتنفيذ بطريقة tự động how to use prd-generator prd-generator setup guide what is prd-generator prd-generator alternative prd-generator vs manual PRD creation prd-generator install automated PRD creation AI agent skills for development Product Requirements Document generation prd-generator AI 代理 自动化开发 产品需求文档 prd.json 自动化工具 开发流程 Receives feature descriptions from users Asks 3-5 essential clarifying questions with lettered options Generates structured PRDs based on user answers Saves PRDs to prd.json in the project root Creates PRDs suitable for autonomous implementation by Ralph prd-generator is an autonomous AI agent loop that creates detailed Product Requirements Documents based on user input and clarifying questions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('skobak/pix/pix', 'community', 'skobak', 'pix', 'skobak/pix', 'pix', 0, 0, 60, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:12.315Z', '99f87aabcde18ed5a6fa23dd4c802fb46963a0c934922fb7d09e9036c3a26353', '{"id":"skobak/pix/pix","name":"pix","description":{"en":"The pix skill implements pixel-perfect designs from Figma links, benefiting developers and designers alike. It utilizes MCP configurations for tool variation.","zh":"pix 技术实现像素级自动化循环，用户提供 Figma 链接即可","ja":"pix 技術はピクセルパーフェクトな自動ループを実現します。ユーザーは Figma リンクを提供するだけです","ko":"pix 기술은 픽셀 퍼펙트한 자동 루프를 구현합니다. 사용자는 피그마 링크를 제공하기만 하면 됩니다","es":"pix es una herramienta que implementa diseños de Figma de manera pixel-perfect. Aprende a configurarla para un desarrollo eficiente","fr":"pix est un outil qui met en œuvre des conceptions Figma pixel-parfait. Découvrez comment la configurer pour un développement efficace","de":"pix ist ein Tool, das Figma-Designs pixel-perfect implementiert. Erfahren Sie, wie Sie es konfigurieren, um eine effiziente Entwicklung zu ermöglichen","pt":"O Pix é uma ferramenta que permite implementações pixel-perfeitas a partir de links do Figma. Com ele, você pode usar ferramentas como get_metadata e get_variable_defs para obter metadados e definições de variáveis de design.","ru":"Pix - это инструмент, который позволяет создавать пиксельно совершенные реализации из ссылок Figma. С его помощью вы можете использовать инструменты, такие как get_metadata и get_variable_defs, для получения метаданных и определений переменных дизайна.","ar":"Pix هو أداة تمكنك من تنفيذ التصاميم بدقة عالية من روابط Figma. يمكنك استخدام أدوات مثل get_metadata و get_variable_defs لاستخراج البيانات الوصفية وتعريفات المتغيرات التصميمية."},"seo":{"title":{"en":"pix: Pixel-Perfect Implementation for AI Agents | AI Agen...","zh":"pix Setup Guide: 实现像素级自动化循环","ja":"pix セットアップガイド: ピクセルパーフェクトな自動ループの実現","ko":"pix 설정 가이드: 픽셀 퍼펙트한 자동 루프 구현","es":"Guía de configuración de pix: Implementación de diseños p...","fr":"Guide de configuration de pix : Mise en œuvre de concepti...","de":"Konfigurationsleitfaden für pix: Implementierung von pixe...","pt":"Guia de Configuração do Pix: Implementação Pixel-Perfeita...","ru":"Настройка Pix: Автономный Цикл с ИИ Агентами для Figma","ar":"دليل إعداد Pix: الحلقات الذكية مع فيجما"},"description":{"en":"Unlock pixel-perfect design implementation with pix. Learn how to use Figma links and MCP configurations for seamless integration.","zh":"了解 pix 技术，实现像素级自动化循环。获取 Figma 链接并将其转换为像素完美的设计","ja":"pix 技術を使用してピクセルパーフェクトな自動ループを実現します。Figma リンクを取得してピクセルパーフェクトな設計に変換します","ko":"pix 기술을 사용하여 픽셀 퍼펙트한 자동 루프를 구현합니다. 피그마 링크를 가져와 픽셀 퍼펙트한 디자인으로 변환합니다","es":"Aprende a configurar pix para implementar diseños de Figma de manera pixel-perfect. Descubre las mejores prácticas y herramientas para un desarrollo eficiente","fr":"Découvrez comment configurer pix pour mettre en œuvre des conceptions Figma pixel-parfait. Consultez les meilleures pratiques et les outils pour un développe...","de":"Erfahren Sie, wie Sie pix konfigurieren, um Figma-Designs pixel-perfect zu implementieren. Entdecken Sie die besten Praktiken und Tools für eine effiziente E...","pt":"Aprenda a configurar o Pix para implementações pixel-perfeitas a partir de links do Figma. Descubra como usar ferramentas como get_metadata e get_variable_defs.","ru":"Узнайте, как настроить Pix для создания пиксельно совершенных реализаций из ссылок Figma. Откройте для себя инструменты, такие как get_metadata и get_variabl...","ar":"تعرف على كيفية 설정 Pix لتنفيذ التصاميم بدقة عالية من روابط Figma. اكتشف كيفية استخدام أدوات مثل get_metadata و get_variable_defs."},"definition":{"en":"pix is a skill that enables autonomous loop implementation of pixel-perfect designs from Figma links using MCP configurations.","zh":"pix 是一种实现像素级自动化循环的技术","ja":"pix はピクセルパーフェクトな自動ループを実現する技術です","ko":"pix 는 픽셀 퍼펙트한 자동 루프를 구현하는 기술입니다","es":"pix es un agente de inteligencia artificial que implementa diseños de Figma de manera automática y pixel-perfect","fr":"pix est un agent d''intelligence artificielle qui met en œuvre des conceptions Figma de manière automatique et pixel-parfait","de":"pix ist ein künstlicher Intelligenzagent, der Figma-Designs automatisch und pixel-perfect implementiert","pt":"O Pix é uma ferramenta de implementação pixel-perfeita que usa links do Figma para criar designs precisos.","ru":"Pix - это инструмент пиксельно совершенной реализации, который использует ссылки Figma для создания точных дизайнов.","ar":"Pix هو أداة لتنفيذ التصاميم بدقة عالية تستخدم روابط Figma لإنشاء تصاميم دقيقة."},"features":{"en":["Implements pixel-perfect designs from Figma links","Utilizes MCP configurations for tool variation (e.g., `figma__get_screenshot` or `mcp__figma__get_screenshot`)","Provides node tree with child IDs, positions, sizes using `get_metadata` tool","Offers design token definitions with `get_variable_defs` tool","Supports resource strategy with tool costs (e.g., `Cheap` for `get_metadata` and `get_variable_defs`)"],"zh":["支持 Figma 链接转换为像素完美的设计","使用 get_metadata 和 get_variable_defs 工具获取设计元数据","实现像素级自动化循环","支持多种工具配置（例如 figma__get_screenshot 或 mcp__figma__get_screenshot）"],"ja":["Figma リンクをピクセルパーフェクトな設計に変換する機能","get_metadata と get_variable_defs ツールを使用して設計メタデータを取得する","ピクセルパーフェクトな自動ループを実現する","多種のツール設定（例：figma__get_screenshot または mcp__figma__get_screenshot）をサポートする"],"ko":["피그마 링크를 픽셀 퍼펙트한 디자인으로 변환하는 기능","get_metadata와 get_variable_defs 툴을 사용하여 디자인 메타데이터를 가져오는 기능","픽셀 퍼펙트한 자동 루프를 구현하는 기능","여러 가지 툴 설정（예：figma__get_screenshot 또는 mcp__figma__get_screenshot）을 지원하는 기능"],"es":["Implementación de diseños de Figma de manera pixel-perfect","Uso de herramientas como get_metadata y get_variable_defs","Compatibilidad con herramientas como Figma","Costos de herramientas personalizables","Soporte para desarrollo eficiente"],"fr":["Mise en œuvre de conceptions Figma pixel-parfait","Utilisation d''outils tels que get_metadata et get_variable_defs","Compatibilité avec des outils tels que Figma","Coûts d''outils personnalisables","Prise en charge du développement efficace"],"de":["Implementierung von Figma-Designs in pixel-perfect-Qualität","Verwendung von Tools wie get_metadata und get_variable_defs","Kompatibilität mit Tools wie Figma","Anpassbare Toolkosten","Unterstützung für effiziente Entwicklung"],"pt":["Implementação pixel-perfeita a partir de links do Figma","Uso de ferramentas como get_metadata e get_variable_defs","Obtenção de metadados e definições de variáveis de design","Integração com outras ferramentas de design","Suporte a configurações personalizadas"],"ru":["Пиксельно совершенная реализация из ссылок Figma","Использование инструментов, таких как get_metadata и get_variable_defs","Получение метаданных и определений переменных дизайна","Интеграция с другими инструментами дизайна","Поддержка настраиваемых конфигураций"],"ar":["تنفيذ التصاميم بدقة عالية من روابط Figma","استخدام أدوات مثل get_metadata و get_variable_defs","استخراج البيانات الوصفية وتعريفات المتغيرات التصميمية","التكامل مع أدوات تصميم أخرى","دعم التهيئة المخصصة"]},"keywords":{"en":["how to use pix","pix setup guide","pix alternative","pix vs Figma","pix implementation","MCP configuration for pix","pix install","what is pix","pix AI agent skill","pix Figma integration"],"zh":["pix 技术","像素级自动化循环","Figma 链接转换","get_metadata","get_variable_defs","AI エージェント","设计自动化"],"ja":["pix 技術","ピクセルパーフェクトな自動ループ","Figma リンク変換","get_metadata","get_variable_defs","AI エージェント","設計自動化"],"ko":["pix 기술","픽셀 퍼펙트한 자동 루프","피그마 링크 변환","get_metadata","get_variable_defs","AI 에이전트","디자인 자동화"],"es":["pix","agente de inteligencia artificial","diseño de Figma","implementación pixel-perfect","desarrollo eficiente","herramientas de desarrollo","get_metadata","get_variable_defs"],"fr":["pix","agent d''intelligence artificielle","conception Figma","mise en œuvre pixel-parfait","développement efficace","outils de développement","get_metadata","get_variable_defs"],"de":["pix","künstlicher Intelligenzagent","Figma-Design","Implementierung in pixel-perfect-Qualität","effiziente Entwicklung","Entwicklungstools","get_metadata","get_variable_defs"],"pt":["pix","figma","implementação pixel-perfeita","get_metadata","get_variable_defs","design de interface","ferramentas de design","configuração personalizada"],"ru":["pix","figma","пиксельно совершенная реализация","get_metadata","get_variable_defs","дизайн интерфейса","инструменты дизайна","настраиваемая конфигурация","ИИ Агенты"],"ar":["pix","figma","تنفيذ التصاميم بدقة عالية","get_metadata","get_variable_defs","تصميم الواجهة","أدوات التصميم","التهيئة المخصصة","أدوات الذكاء الاصطناعي"]}},"owner":"skobak","repo":"pix","repoPath":"skobak/pix","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.270Z","topics":[],"category":"community","skillMd":{"name":"pix","description":"Launches an autonomous, pixel-perfect UI implementation loop using Figma MCP and Chrome.","bodyPreview":"# /pix: The Pixel-Perfect Autonomous Loop\n\nUser provides a Figma link. You implement it pixel-perfect. That''s it.\n\n> Tool names may vary based on your MCP configuration (e.g., `figma__get_screenshot` or `mcp__figma__get_screenshot`). Run `/mcp` to see available tools.\n\n## Resource Strategy\n\n### Tool Costs\n\n| Tool | Cost | Use For |\n|------|------|---------|\n| `get_metadata` | **Cheap** | Node tree with child IDs, positions, sizes. No styling. |\n| `get_variable_defs` | **Cheap** | All design toke","body":"# /pix: The Pixel-Perfect Autonomous Loop\n\nUser provides a Figma link. You implement it pixel-perfect. That''s it.\n\n> Tool names may vary based on your MCP configuration (e.g., `figma__get_screenshot` or `mcp__figma__get_screenshot`). Run `/mcp` to see available tools.\n\n## Resource Strategy\n\n### Tool Costs\n\n| Tool | Cost | Use For |\n|------|------|---------|\n| `get_metadata` | **Cheap** | Node tree with child IDs, positions, sizes. No styling. |\n| `get_variable_defs` | **Cheap** | All design tokens (colors, spacing, radii) as name→value. |\n| `get_code_connect_map` | **Cheap** | Check which Figma nodes map to existing code components. |\n| `get_screenshot` | **Medium** | Visual image of a specific node. Target a `nodeId` to crop/zoom. |\n| `get_design_context` | **Expensive** | Full code + styling + assets. NEVER call on a large parent — call on individual sections. |\n\n**Core rule**: Cheap calls first to build a map, then expensive calls only on the smallest necessary nodes.\n\n### Image Budget\n\nClaude API limits images to 2000px per dimension when >20 images are in a conversation. Old images cannot be individually removed.\n\n- **~20 screenshots per conversation** before the resolution limit kicks in\n- **3-image working set**: Figma layout (overview), Figma detail (current section), Chrome state (rendered result)\n- **Never re-screenshot a static Figma node** — designs don''t change mid-session\n- **Use `getComputedStyle` for numerical properties** — zero image cost\n- **Recovery**: `/compact` drops old images from context (see Recovery section)\n\n---\n\n## Phase 1: Reconnaissance\n\nWhen the user provides a Figma link, extract `fileKey` and `nodeId` from the URL and immediately start working. If any MCP call or Chrome interaction fails, run the [Doctor Check](#doctor-check) to diagnose and fix, then resume.\n\n### Step 1: Get the Node Tree\n\nCall `get_metadata(nodeId, fileKey)`:\n\n```xml\n<Frame id=\"45:1\" name=\"Header\" type=\"FRAME\" x=\"0\" y=\"0\" width=\"1440\" height=\"80\">\n  <Component id=\"45:10\" name=\"Logo\" x=\"20\" y=\"16\" width=\"120\" height=\"48\"/>\n  <Frame id=\"45:15\" name=\"NavLinks\" x=\"400\" y=\"20\" width=\"600\" height=\"40\">\n    <Text id=\"45:16\" name=\"Home\" x=\"0\" y=\"0\" width=\"60\" height=\"40\"/>\n  </Frame>\n</Frame>\n```\n\nBuild a **mental map**:\n- Identify every major section and note each `nodeId`\n- Note positions and sizes to understand the layout grid\n- Identify components vs frames vs text vs icons\n\n### Step 2: Extract All Design Tokens (Once)\n\nCall `get_variable_defs(nodeId, fileKey)`. Save the result — do NOT call this again.\n\n### Step 3: Check Existing Components\n\nCall `get_code_connect_map(nodeId, fileKey)`. For matched components, follow this priority:\n1. **Reuse as-is** — if it covers the Figma design exactly\n2. **Extend minimally** — add a prop or variant if close but not exact\n3. **Compose** — combine existing components\n4. **Create new** — only if nothing existing fits\n\n### Step 4: Visual Overview\n\nCall `get_screenshot(nodeId, fileKey)` on the root selection. This is Image 1 of your budget — your layout reference. Do NOT retake it.\n\n**At this point you have NOT called `get_design_context` at all.** You have a complete structural map, all tokens, reusable component info, and a visual reference — all from cheap calls.\n\n---\n\n## Phase 2: Study & Implement (Code in the Dark)\n\nStudy the design deeply, memorize every detail, then code from memory.\n\n### Step 1: Layout Shell\n\nUsing the metadata tree, implement the outer layout:\n- Container dimensions and positioning (flex, grid)\n- Major section placement\n- Background colors from tokens\n- Borders and dividers\n\nThe metadata + visual overview are usually sufficient. Only call `get_design_context` if you need specific properties you can''t infer.\n\n### Step 2: Study Every Section\n\nFor each major section:\n\n1. **Figma Detail**: `get_screenshot(sectionNodeId, fileKey)` — zoomed-in visual reference.\n\n2. **Design Context**: `get_design_context(sectionNodeId, fileKey)` — text only, no image cost. If truncated, use child node IDs from `get_metadata` and fetch children individually.\n\n3. **Absorb every detail**: fonts, sizes, weights, colors, spacing, borders, shadows, icon shapes. Burn it into memory.\n\n4. **Color sanity check**: Compare `get_design_context` colors against the Figma screenshot. If the screenshot reveals opacity layering, overlapping fills, or gradients — the raw token values will be wrong. Use the visual truth, not the raw token.\n\n**No Chrome screenshots during this phase.** You are studying, not checking.\n\n**Key rule**: NEVER call `get_design_context` on the root selection. Always target the smallest meaningful node.\n\n### Step 3: Code from Memory\n\nImplement everything using what you memorized:\n- Design context output for exact properties\n- Tokens from Phase 1 (do not re-extract)\n- Reusable components from Phase 1\n- **Respect project rules**: Check for `.claude/rules`, `CLAUDE.md`, and project instruction files. Follow established patterns for component structure, file placement, naming, and styling. Figma MCP output is a design representation — translate it into your project''s conventions, don''t paste it verbatim.\n\n**Frontend only.** Don''t touch backend, API routes, or database unless the user explicitly asks. Use mock/placeholder data if APIs don''t exist yet.\n\n**Minimize screenshots during coding.** You studied the design — use what you memorized. But if you''re missing crucial data for a specific element (exact icon shape, a nested layout you didn''t drill into, a subtle gradient), take a targeted `get_screenshot` on that Figma node rather than guessing. Getting it right the first time is cheaper than a refinement round.\n\n### Step 4: Design System Sync\n\nNEVER hardcode values. Sync to the project''s design system:\n\n- **Tailwind**: Update `tailwind.config.*` if a token is missing. Never `text-[#f3f3f3]`.\n- **CSS-in-JS**: Add tokens to the theme object. Never inline hex.\n- **Component Library**: Map to existing theme tokens. Never bypass the theme.\n- **CSS/SCSS**: Add custom properties to `:root`. Never scatter magic values.\n\n### Step 5: Icons & Assets\n\n**Icons**: Find a match in the project''s existing icon library first — by name, then by visual shape. Match `stroke-width` and `size` exactly.\n\n**Fallback**: If the layer name doesn''t map, `get_screenshot(iconNodeId)` and identify visually. Match by shape, not name.\n\n**Images/illustrations**: Download from the Figma MCP assets endpoint and save to the project''s public/static folder. Don''t create inline SVG blobs for complex illustrations. Don''t import new icon packages without asking.\n\n### Property Checklist\n\nBefore writing code for ANY element, verify ALL applicable properties:\n\n- **Text**: font-family, font-size, font-weight, line-height, letter-spacing, color, opacity, text-align, text-decoration, text-transform\n- **Container**: width, height, min/max-width, padding (all 4), margin, background-color, border-radius, border-width/color/style, box-shadow, opacity, overflow\n- **Icon**: size, fill, stroke, stroke-width, color (independent from parent text)\n- **Button/Link**: All text + container props + cursor, hover/active/disabled states\n- **Image**: width, height, object-fit, border-radius, border, aspect-ratio\n- **Spacing**: gap, row-gap, column-gap\n\n**Layout Principle**: Avoid hardcoded sizes. With correct font-size, line-height, padding, and parent width, elements render correctly. Hardcoded dimensions are a symptom of wrong upstream layout.\n\n**Responsive**: Consider how the component adapts to different screen sizes. Use the project''s responsive approach (Tailwind breakpoints, media queries, container queries).\n\n**Never use approximate Tailwind classes** (like `text-zinc-500`) when exact hex values are available from tokens.\n\n---\n\n## Phase 3: Refinement Loop\n\nYou think you''re done. Now prove it. Keep cycling until the result is perfect.\n\n### The Loop\n\n**Step 1: Chrome screenshot (1 image)**\n\nFirst look at what you built. Compare against Figma screenshots in context. Be extremely picky:\n- Visual alignment issues\n- Missing elements or wrong proportions\n- Layout shifts, spacing that looks off\n- Wrong icon shapes\n- Color or weight mismatches\n- **Color comparison**: Sample dominant colors from Figma vs Chrome. Flag anything that looks off — opacity/layering can cause perceived differences even when hex values match.\n\n**Step 2: Numerical audit (zero images)**\n\nRun `getComputedStyle` on every element and compare against Figma values:\n\n```js\nconst el = document.querySelector(''.target-element'');\nconst s = getComputedStyle(el);\nJSON.stringify({\n  padding: s.padding, margin: s.margin, gap: s.gap,\n  backgroundColor: s.backgroundColor, color: s.color,\n  fontSize: s.fontSize, fontWeight: s.fontWeight,\n  lineHeight: s.lineHeight, letterSpacing: s.letterSpacing,\n  borderRadius: s.borderRadius, borderWidth: s.borderWidth,\n  borderColor: s.borderColor, boxShadow: s.boxShadow\n});\n```\n\n12px is not 10px. #f97316 is not #ff611c.\n\n**CSS specificity check**: Icons inside wrapper components (Button, Link) often get wrong colors from parent overrides. Run `getComputedStyle` on the SVG itself. If the computed color doesn''t match, use the Tailwind important modifier (prefix with !) to force it.\n\n**Step 3: Picky mismatch list**\n\nCombine visual + numerical issues into one list. No issue is too small. 2px off? List it.\n\n**Step 4: Fix everything**\n\nBatch all fixes. No screenshots between individual fixes.\n\n**Step 5: Repeat from Step 1**\n\n**Exit condition**: Retake `get_screenshot` on the Figma root node. Place side-by-side with your latest Chrome screenshot. Compare colors directly. Only move on when both screenshots match AND numerical audit shows zero mismatches.\n\n### Icon & Shape Verification\n\nIf an icon looks wrong during any loop iteration:\n- `get_screenshot(iconNodeId, fileKey)` on the Figma icon\n- Screenshot Chrome icon at 3x zoom\n- Compare the SILHOUETTE — stroke count, shape, proportions\n\nCommon mismatches:\n- \"filter\" → often lines-with-circles, NOT a funnel\n- \"calendar\" → many variants (with/without dots)\n- \"mail\" → open vs closed envelope\n\nIf it doesn''t match: try another icon from the library, or use the Figma SVG inline.\n\n### Anti-Pattern: \"Looks Good Enough\"\n\nThis ALWAYS misses: 2-4px spacing differences, wrong icon variant, slightly wrong color, missing shadow, font weight mismatch.\n\n**RULE**: Not done until zero visual mismatches AND zero numerical mismatches.\n\n---\n\n## Recovery: Compact & Resume\n\nIf you hit the image limit (or proactively after ~15 screenshots):\n\n1. **Run `/compact`** — summarizes conversation, drops old images. Notes and progress are preserved.\n2. **Retake 3 reference images**: Figma overview, Figma detail (current section), Chrome state.\n3. **Continue the refinement loop** — you still know everything from the compacted history. ~17 more image slots available.\n\nRepeatable: compact → retake 3 → continue → compact again if needed.\n\n---\n\n## Phase 4: User Review\n\n**Stop and ask**:\n- \"Here''s the final result. Are you happy with it?\"\n- \"If something looks off, paste a Figma ''Link to Selection'' for the specific area.\"\n\nIf the user provides a new link, re-run Phases 1-3 scoped to that selection.\n\n---\n\n## Doctor Check\n\nRun this ONLY when something fails. Not at startup.\n\n**Figma MCP not working?**\n- Call `whoami` to check authentication\n- Not connected → alert user to configure Figma MCP\n- Not authenticated → guide through Figma OAuth\n\n**Chrome not responding?**\n- Ensure Claude Chrome extension is active\n- Navigate to the correct localhost page\n\n**Dev server not running?**\n- Check lockfile: `package-lock.json` (npm), `yarn.lock` (yarn), `pnpm-lock.yaml` (pnpm), `bun.lockb` (bun)\n- Read `package.json` for dev command and port\n- Default ports: 5173 (Vite), 3000 (Next/CRA), 8080 (Vue CLI)\n- `lsof -i :<PORT>` — if not running, start in background\n\n**Unknown design system or icon library?**\n- Scan `package.json`: `tailwindcss`, `styled-components`, `@emotion/*`, `@chakra-ui/*`, `@mui/*`, `@mantine/*`\n- Icon libraries: `lucide-react`, `@heroicons/react`, `react-icons`, `@radix-ui/react-icons`, `@fortawesome/*`, `@phosphor-icons/react`, `@tabler/icons-react`\n\n---\n\n## Examples\n\n**Invocation:**\n```\n/pix\n> Paste Figma link: https://figma.com/design/abc123/MyApp?node-id=42-100\n```\n\n**What happens:**\n1. Recon: `get_metadata` + `get_variable_defs` + `get_code_connect_map` (0 images)\n2. Figma overview: `get_screenshot` on root (image 1)\n3. Study section 1: `get_screenshot` (image 2) + `get_design_context` (text). Memorize.\n4. Study section 2: `get_screenshot` (image 3) + `get_design_context` (text). Memorize.\n5. Code everything from memory (0 images)\n6. **Loop round 1**: Chrome screenshot (image 4) + audit → 4 mismatches + 1 bad icon\n7. Fix mismatches. Icon check: `get_screenshot` on Figma icon (image 5) — swap it.\n8. **Loop round 2**: Chrome screenshot (image 6) + audit → 1 spacing issue\n9. Fix spacing.\n10. **Loop round 3**: Chrome screenshot (image 7) + audit → zero mismatches.\n11. **Final check**: Retake Figma `get_screenshot` (image 8) side-by-side with Chrome → match.\n12. Done. Total: 8 images.\n\n**Bad patterns:**\n- Screenshotting every element individually (budget killer)\n- Re-screenshotting the same Figma node (it''s static)\n- Chrome screenshots after every small CSS tweak\n- Using screenshots to verify what `getComputedStyle` gives for free\n- Not running `/compact` when approaching image limit\n- `get_design_context` on root (token waste)\n- `get_variable_defs` more than once (redundant)\n- Hardcoded hex in Tailwind (`text-[#f3f3f3]`)\n- Magic width numbers (`w-[247px]`)\n- Saying \"looks close\" without numerical verification\n"},"lastSynced":"2026-03-08T02:00:12.315Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing pixel-perfect design implementation from Figma links.","zh":"非常适合需要从 Figma 链接实现像素级设计的前端代理。","ja":"Figma リンクからのピクセルパーフェクトなデザイン実装が必要なフロントエンドエージェントに最適です。","ko":"피그마 링크에서 픽셀 퍼펙트한 디자인 구현이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes Frontend que necesitan implementación de diseño perfecta en píxeles a partir de enlaces de Figma.","fr":"Parfait pour les agents Frontend ayant besoin d''une mise en œuvre de conception parfaite en pixels à partir de liens Figma.","de":"Perfekt für Frontend-Agents, die eine pixelgenaue Designimplementierung aus Figma-Links benötigen.","pt":"Perfeito para Agentes Frontend que precisam de implementação de design perfeita em pixels a partir de links do Figma.","ru":"Идеально подходит для агентов Frontend, которым необходима реализация дизайна с точностью до пикселя из ссылок Figma.","ar":"مثالي لعميل الواجهة الأمامية الذي يحتاج إلى تنفيذ تصميم دقيق بالنقاط من روابط Figma."},"recommendation":{"en":"Empowers agents to implement Figma designs with precision, utilizing MCP configurations for tool variation and protocols like get_metadata and get_variable_defs for comprehensive content analysis.","zh":"赋予代理实现 Figma 设计的精确度，利用 MCP 配置进行工具变异和协议，如 get_metadata 和 get_variable_defs 进行全面内容分析。","ja":"エージェントが Figma デザインを精密に実装できるようにし、MCP 構成を使用してツールのバリエーションを行い、get_metadata や get_variable_defs などのプロトコルを使用して包括的なコンテンツ分析を行う。","ko":"에이전트가 피그마 디자인을 정밀하게 구현할 수 있도록 하며, MCP 구성에 따라 도구 변형을 수행하고 get_metadata 및 get_variable_defs와 같은 프로토콜을 사용하여 포괄적인 콘텐츠 분석을 수행합니다.","es":"Habilita a los agentes a implementar diseños de Figma con precisión, utilizando configuraciones de MCP para variaciones de herramientas y protocolos como get_metadata y get_variable_defs para un análisis de contenido integral.","fr":"Permet aux agents de mettre en œuvre des conceptions Figma avec précision, en utilisant des configurations MCP pour les variations d''outils et des protocoles tels que get_metadata et get_variable_defs pour une analyse de contenu complète.","de":"Ermächtigt Agenten, Figma-Entwürfe mit Präzision umzusetzen, indem MCP-Konfigurationen für Werkzeugvarianten und Protokolle wie get_metadata und get_variable_defs für eine umfassende Inhaltsanalyse verwendet werden.","pt":"Habilita os agentes a implementar designs do Figma com precisão, utilizando configurações do MCP para variação de ferramentas e protocolos como get_metadata e get_variable_defs para análise abrangente de conteúdo.","ru":"Наделяет агентов возможностью реализовывать дизайны Figma с точностью, используя конфигурации MCP для вариации инструментов и протоколов, таких как get_metadata и get_variable_defs, для комплексного анализа контента.","ar":"يمكّن العميل من تنفيذ تصاميم Figma بدقة، مستخدمًا تكوينات MCP لتغيير الأدوات وبروتوكولات مثل get_metadata و get_variable_defs لتحليل المحتوى الشامل."},"useCases":{"en":["Implementing pixel-perfect designs from Figma links","Automating design-to-code workflows with MCP configurations","Generating design metadata with get_metadata tool"],"zh":["从 Figma 链接实现像素级设计","使用 MCP 配置自动化设计到代码的工作流程","使用 get_metadata 工具生成设计元数据"],"ja":["Figma リンクからのピクセルパーフェクトなデザインの実装","MCP 構成を使用したデザインからコードへのワークフローの自動化","get_metadata ツールを使用したデザインメタデータの生成"],"ko":["피그마 링크에서 픽셀 퍼펙트한 디자인 구현","MCP 구성에 따른 디자인에서 코드로의 워크플로우 자동화","get_metadata 도구를 사용한 디자인 메타데이터 생성"],"es":["Implementar diseños perfectos en píxeles a partir de enlaces de Figma","Automatizar flujos de trabajo de diseño a código con configuraciones de MCP","Generar metadatos de diseño con la herramienta get_metadata"],"fr":["Mettre en œuvre des conceptions parfaites en pixels à partir de liens Figma","Automatiser les flux de travail de conception à code avec des configurations MCP","Générer des métadonnées de conception avec l''outil get_metadata"],"de":["Pixelgenaue Designs aus Figma-Links implementieren","Design-zu-Code-Workflows mit MCP-Konfigurationen automatisieren","Design-Metadaten mit dem Tool get_metadata generieren"],"pt":["Implementar designs perfeitos em pixels a partir de links do Figma","Automatizar fluxos de trabalho de design para código com configurações do MCP","Gerar metadados de design com a ferramenta get_metadata"],"ru":["Реализация дизайна с точностью до пикселя из ссылок Figma","Автоматизация рабочих процессов дизайна в код с помощью конфигураций MCP","Генерация метаданных дизайна с помощью инструмента get_metadata"],"ar":["تنفيذ تصميم دقيق بالنقاط من روابط Figma","آليّة سير عمل التصميم إلى الكود باستخدام تكوينات MCP","توليد بيانات وصفية للتصميم باستخدام أداة get_metadata"]},"limitations":{"en":["Requires Figma link access","Dependent on MCP configuration for tool availability","Limited to design implementation, no styling or variable definition without additional tools"],"zh":["需要 Figma 链接访问","依赖于 MCP 配置来确定工具可用性","仅限于设计实现，不支持样式或变量定义，需要额外工具"],"ja":["Figma リンクへのアクセスが必要","ツールの可用性は MCP 構成に依存する","デザイン実装のみに限定され、スタイリングや変数定義は追加ツールが必要"],"ko":["피그마 링크 접근이 필요함","도구 가용성은 MCP 구성에 의존함","디자인 구현만으로 제한되며, 스타일링이나 변수 정의는 추가 도구가 필요함"],"es":["Requiere acceso a enlaces de Figma","Dependiente de la configuración de MCP para la disponibilidad de herramientas","Limitado a la implementación de diseño, sin estilo o definición de variables sin herramientas adicionales"],"fr":["Nécessite un accès aux liens Figma","Dépendant de la configuration MCP pour la disponibilité des outils","Limité à la mise en œuvre de la conception, sans style ou définition de variables sans outils supplémentaires"],"de":["Erfordert Zugriff auf Figma-Links","Abhängig von der MCP-Konfiguration für die Verfügbarkeit von Tools","Begrenzt auf die Designimplementierung, ohne Stil oder Variablendefinition ohne zusätzliche Tools"],"pt":["Requer acesso a links do Figma","Dependente da configuração do MCP para disponibilidade de ferramentas","Limitado à implementação de design, sem estilização ou definição de variáveis sem ferramentas adicionais"],"ru":["Требуется доступ к ссылкам Figma","Зависит от конфигурации MCP для наличия инструментов","Ограничен реализацией дизайна, без стилизации или определения переменных без дополнительных инструментов"],"ar":["يتطلب الوصول إلى روابط Figma","يعتمد على تكوين MCP لتوافر الأدوات","محدود بتنفيذ التصميم، دون تنسيق أو تعريف المتغيرات دون أدوات إضافية"]},"version":4},"contentHash":"99f87aabcde18ed5a6fa23dd4c802fb46963a0c934922fb7d09e9036c3a26353","qualitySc